/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070925-7","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"厚生委員会","time":"午前１０時０３分～午後５時０３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"温泉法に基づく４のところで、品川区内ではどの程度の数がこれに該当するのか。同じく６で、旅館業というのは品川区で幾つぐらいあって、温泉のほうは品川区は、該当するものがないと聞いているんですけれども、そのあたりはどういうことか。それから旅館業というのはどの程度あって、継いでいくというのがどのくらいの数に想定されるのかなというのを教えてください。","respondent":"山岡品川区保健所衛生課長","answer":"近年ではこの何年か、数年の間でそういうことになっておりますが、ほとんど承継、これは法人格を持っている場合は、代表者が変更の場合は変更届だけで済みますのでこれに該当しません。個人の場合が相続という関係で、関係してくるということで、ほとんどない状況です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そんなに少ないという状況であるにもかかわらず、そういうふうに温泉法が改正になったという背景というのが何かあるのかということと、温泉法の改正の中身というのは、その承継のほかに大まかにどんなものがあるのかということも教えていただきたいと思います。","respondent":"太田健康課長","answer":"定期的な分析、１０年ごとに、その結果に基づく施設における成分の掲示の更新を義務づけたとか、あるいは許可の際の条件を新たにつけることができるとか、それら一連の中で、今回、承継手続について旅館業法とか、他の法律においては、既に承認ということではなくて。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"渋谷で、温泉の爆発の事故もありましたけれども、今、すごく深く掘って、温泉を売りにしていくというのがいろいろ出てきているということを聞きますけど、品川区ではそういう動きというのはどうなんでしょうか。","respondent":"山岡品川区保健所衛生課長","answer":"井戸の掘り上げるところ、あるいは万が一ガスが出て、それをセパレートするような設備については、すべて区内４施設については屋外に設置されているということで、特にガスがたまるような状況にはないということです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"今もお話に出ておりましたように、６月ですか、渋谷の温泉施設の爆発事故を受けてということで、新聞報道で申しわけないんですが、９月１１日でしょうか、東京都のほうでも、その温泉施設についての暫定的な指針案が示されたというか、そんな報道がされていますね。ちょっとその辺わかりましたら、教えていただけますか。","respondent":"太田健康課長","answer":"先ほど申し上げましたのは、さきの通常国会の中で、温泉法の改正がなされたということの、それに伴って、今回条例改正を提案するということをご説明申し上げたものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"西大井シルバーセンターについてなんですが、工事期間の変更というのが、８月１６日という日付での事項別明細では変更後、平成２０年３月から１２月までということで、１０カ月間の工事期間ということになっているんですが、これがまた９カ月ということで、１カ月短くなったということなんでしょうか。そのところをちょっとお聞かせください。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"工期の関係のお尋ねですけれども、これは予算の事項別では１２月というふうに表示をしておりますが、これは１１月に工事は竣工して、ただ検査が１カ月かかるということで。シルバーセンターが運営変更になった理由ですけれども、当初は、シルバーセンターは現在区立ということで、区立で予定しておりましたけれども、法人との協議の中で、いろいろな提案をいただきまして。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、シルバーセンターが、区立でないという、民設民営というのは今回初めてになるのではないかなと思うんですけど、そういう点では、一体的運営ということであれば、区立にして、指定管理者ということでも一体的運営ということにはなってくるんじゃないかと思うんですけど、そこのところが、指定管理者じゃなくて、民設民営ということになぜしたのかということと。","respondent":"冨岡高齢事業課長","answer":"運営の負担金につきましては、整備助成と同じで、助成金ということで対応したいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回のこの原小学校のところでは、ケアホームにしても、指定管理者じゃなくて民設民営、保育園も全部そういう形になるわけですけれども、そのところで、ケアホームは区立でやると補助金がとれないということで、民設民営でやらざるを得ないというのが、今までのお答えだったと思うんですけど、そういうところでも、きちんとチェックもしていけるように、選定もしていけるようにということで。","respondent":"冨岡高齢事業課長","answer":"これにつきましては、当然基本協定を結びまして、それからさらに助成金要綱ということで、報告をしてチェックができるようにする予定です。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が聞きたいのは協定だけじゃなくて、毎年毎年の日常的に、指定管理者であればモニタリングシステムという形でなりましたよね。そういう形で事業の報告書、それからまとめ、それから計画書、そういう形で区のほうに提出をされて、区としてもチェックできる、そしてまた議会としてもチェックできるという形がとれるのかということでお聞きしたのです。","respondent":"木下福祉高齢事業部長","answer":"できれば、それに加えて、さらに進んだ工夫をしていただくという点もありますし、ケアホームなども区の高齢者施策との一体性ということもありますから、いろいろな形で我々としては運営事業者と連携をしていきたいと考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、議会が、一体どういうふうな運営状況になっているのかということをチェックをしたいと思ったときに、チェックのできる文書とか、日常的にそういうふうなものというのはないんでしょうか。そこら辺のところもお願いします。","respondent":"木下福祉高齢事業部長","answer":"当然、ここは社会福祉法人こうほうえんが運営することになっておりますので、法人としての決算とか、事業報告というのは用意をされますし、私どもとしても、そのことについては把握していきたいと考えていますので、その中での取り扱いというのは可能だろうと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めての民設民営シルバーセンターということになりますので、そこら辺のところはしっかりと見ていっていただきたいし、議会でもチェックできるようにということでお願いしたいと思います。それが今、この財産の取り扱いということで民設民営になると、土地・建物を無償貸与ということで、財産そのものは区の財産でなくなるということではなくて、無償貸与ということでの考え方でいいんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"この土地・建物につきましては、端的には無償で貸与するということで考えております。ですから、区の財産でなくなるということではございません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"というのは、跡地利用ということで、初めてこういう仕組みをやったので、当初の見込みが来年の１月に着工できるという絵で予算づくりをされたと思うんですが、先ほどの説明を聞くと、いろいろ耐震等の問題があって、それを整備しなければいけない。それから、質問は２番目に相対的に圧縮された数字が上がってきているんですけれども、いわゆる減になってきたよと。","respondent":"蓼沼高齢福祉課長","answer":"双方が調整、合意しながら進めてきた結果として、こういうような数字になっておりますので、十分都との信頼関係については、区としての意を用いてまいりましたし、それについては今後とも十分気に留めて、都区の信頼については確保できるように。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"ちょっと五反田のケアホームに行ったら、隣に地域センターがあって、地域センターでいろいろな方々が練習をしたりしているので、そういうところと連携をとったらどうですかというのをケアホームの方にはちょっとお話をさせていただいたので、するとお金がかからないし、隣でいろいろな練習をしたり、若い子がダンスを練習している、何をしている、その辺をちょっと見せてもらったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"堺委員","kind":"確認","question":"何点か確認をしたいんですけれども、最初に予算書の３７ページ、先ほどご説明いただきました児童デイサービスに関連してお尋ねをします。社会福祉指定寄附金をここには充当して、たしかコンパスにモニターを設置するというご説明でしたけれども、これについての扱いというんですか、個人情報保護との兼ね合いの中で、どう対応されていくのかなんですね。","respondent":"高橋障害者福祉課長","answer":"モニターを設置するのは、訓練室の隣で、親御さんと指導員が見ながら、家庭でもどういうことをしたらいいのかということで、ご自分のお子さんを見るということで行うもので、メインはそちらで、ですので、ほかのお子さんを対象にどうだとかということではありませんので。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問","question":"機材がいろいろ置いてあった部屋のその隣でということですかね。そういう理解でいいですか。","respondent":"高橋障害者福祉課長","answer":"それで、従来でしたらマジックミラーみたいな形で見ている部屋があったんですが、それだと動きがあるお子さんについてはなかなか追えないという部分がありますので、モニターを設置することによってご自分のお子さんの動きを、多動のお子さんもおりますので。","id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"それから補正予算の件の中で、今、るるご説明いただきましたので、よくわかりました。西大井シルバーセンターの運営の変更、これもそういう方法もあるんだろうなと思います。ひとつよろしくお願いします。貸付ということですから、返済が当然あるんだろうと思うんですけど、その返済方法というものについては、どういう形になっているのか、ちょっとその辺を確認しておきたいんですが。","respondent":"蓼沼高齢福祉課長","answer":"具体的には、これは財産所管をしております、管財部門のほうと協定を別途結びますけれども、基本的な考え方としては、期間としては２０年間の貸付で、返済については無利子で返還をしていただくということで、返済方法等については、今後具体的に詰めていくです。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"２０年間無利子ということで、通常、こういうケースの場合は、それが標準的な対応の仕方になっているんですか。過去にも幾つかこういう例があったのかどうかも含めて、参考までに教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"この方式は、品川区の社会福祉施設を整備する方法として、いわゆる品川方式というような言い方をしていましたけれども、なかなかやはり法人、経営基盤が弱い部分もありますので、これまでも福栄会ですとか、品川総合福祉センター、建物の土地については区が無償で提供して。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"福栄会とか、品川総合福祉センターとか、これは公設民営というんですかね。今回は社会福祉法人に、今ある土地・建物も全部無償貸与にして、なおかつ貸付金が２０年間で無利子でやってもらうということですから、そういう今ある、委託を受ける業者にしてみれば、適切な言葉でないかもしれないけれども、いいお仕事だなと。","respondent":"蓼沼高齢福祉課長","answer":"ただ、その社会福祉法人の事業運営は収益を上げることが目的ではありませんので、やはりどうしても財政基盤といいますか、そういうものはあまり強固なものではございませんので、これまでの区内の法人と同じような財政支援を区としても。","id":"exchange-017"},{"speaker":"堺委員","kind":"確認","question":"次に確認で申し上げようと思っていたんですが、ちょうど適切な表現と自分では思うんですが、こういう形をとることによって、利用される区民の皆さんに質の高いサービスが提供できるんだと。そこだろうと、僕は思うんですね。やっぱり我々が望むことはそこなんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認可保育園のほうでお聞きしたいんですけど、これも事項別明細をとって、見ていましたら、事業費全体に対する案分変更を行うことにより、事業者負担を設定したということで書かれていまして、ここを見ても、補正前は自己資金というのはないところが、今回、補正後で６,４５０万円ですか、出てきていますけれども、これはどういう考え方でこういうふうになっているのかということをお聞かせください。","respondent":"小林保育課長","answer":"今回の補正のあり方につきましては、委員からご指摘のあった点も踏まえて、今後の事業の中では、きちっとした精査をしてまいりたいと考えていますが、ご説明させていただきましたように、この事業主の負担等を含めた総経費については、この平成１９年度の予算においては。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと具体的に６,４５０万円というものがどういう形で出てきたのかというのは、いろいろな精査の中でということなんですが、理解できかねるところがあるんですけれども、それはとりあえず、その説明を受けさせていただいて、それでもう１つお聞きしたいのは、私は、この保育園と、シルバーセンターもそうなんですけれども、ケアホームは指定管理者では補助金がとれないということで。","respondent":"小林保育課長","answer":"その運営につきましては、通常の私立保育園、公立等含めて、十分な連携をもって状況は把握できておりますので、公私ともに一体となった運営の管理を今後も継続していく予定でおります。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私立保育園は、区内にも何カ所かありますよね。そういう点から言えば、やっぱりしっかりと中身のチェックというのはできるようにしておくというのが、すごく大事なことなんじゃないかなと思うんですけど、議会としてもチェックできるようなことというのが必要だと思うんですけれども、そこのところはいかがでしょうか。","respondent":"小林保育課長","answer":"今回の原小学校につきましても、私立ではありますけれども、認可保育園をベースにして、なおかつ今後、それを基礎としてよりよい形を考えていこうということですから、その運営のありようにつきましても、十分認可保育園のベースで、保育事業の中で管理もしていきますし。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、品川ではぷりすくーる西五反田が指定管理者という形でなっていると思うんですけど、ぷりすくーる西五反田とかであれば、事業報告ですとか、計画書ですとか、体制がどうなっているかとか、そういうふうなものというのも常にチェックができるという仕組みになっていると思うんですけれども、そういうところも、ここの保育園も区のほうに情報を求めれば、保育の中身から。","respondent":"小林保育課長","answer":"基本的に私立の認可保育園、すべて会計年度が終わりますと、社会福祉法人会計にのっとって、その財務状況、そして業務の実績等、ご報告をいただき、それを保育課の中で精査する中で、次年度の運営の協議等を行っております。今回につきましても、同様の形で対応してまいります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それであれば、指定管理者と基本的には変わりないような、中身のチェックができるということでとらえてよろしいでしょうか。","respondent":"小林保育課長","answer":"ただ、指定管理者に対しまして、法人としての独自性を私立の場合は持っておりますので、そういった意味で、状況に応じた対応が、逆に言えば、独自の経営権の中でできるのが、あえて言えば私立保育園の特色かと認識しております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、しっかりと議会の中からもチェックをできるというところで、指定管理者ということでなくやるわけですから、そういうところではぜひチェックできる形でということで、情報も出していただきたいと思いますし、しっかりと把握もしていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"具体的には社会福祉法人ですので、先ほど申し上げましたように、経営基盤はそれほど強固なものではないということで、考え方としては区の助成と、それから貸付と自己資金という枠組みで提案があったわけですけれども、それを協議した結果。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"話し合いの中で一定程度、貸し付けるということなんですけど、そこの基準、区がどれぐらい持って、どれぐらいを事業所に持ってもらうとかというのは、そのときそのときで考え方というのはないんでしょうか。","respondent":"木下福祉高齢事業部長","answer":"ただし、品川区の場合、今そうは言っても、もう１つ、例えば介護報酬の中に入っていますよと言っても、回していくことによってたまっていくだけですから、最初からそのお金は当該事業所についてはあるわけではありませんので、貸付をすることによって、例えば２０年間の間で。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の考え方はわかりました。そんな中で、また補助金もどんどん下げられてはいますけれども、特別養護老人ホームは運営の経営支援金ですか、そういう形で出ていますけれども、このケアホームというのは運営するに当たってはそういうのは一切出ていかないということなんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"民間の特別養護老人ホームにあるような経営支援費のことかと思いますけれども、この原小学校のケアホームについてはそういうものはございません。先ほど申し上げましたように、基本的には介護報酬でということが原則です。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後にちょっとお聞きしたいのは、やはりこれもチェックの仕組みなんですね。これは特別養護老人ホームにかわる施設ということで建てられるのが、このケアホームだと思うんですけれども、そういう点では特別養護老人ホームでさまざまな問題が起こっていますし、区がかかわってやっていくわけですから、チェックの仕組みをどうするか。","respondent":"蓼沼高齢福祉課長","answer":"そのほか、これは介護保険制度で運営をいたしますので、区が保険者となるわけですので、保険者の立場として必要な運営の進行管理といいますか、そういう部分は必要に応じてやるといいますか、やらなければいけない立場にありますし。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ議会のほうにもご報告いただきたいと思いますし、くれぐれも問題が起こらないような形での品川区の実態の把握と、それから情報の提供ということでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと何点か確認をしておきたいんですけれども、１つは、先ほど耐震関係のお話があったんですけれども、今回の事業費のところにはそういうのが全く載っかっていないと思うんですけれども、今後、そういう費用はこの事業費とは全く別個の考え方になるのかどうなのか、そういう費用はまたこっちの事業費のほうに入ってくるよということになるのかどうなのか。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"そのほかの整備費助成については、ケアホームの助成ということで、別に項目を立てておりますが、その中に耐震補強の関係の費用は含まれております。シルバーセンターの一般利用との仕切りの関係ですけれども、やはり西大井シルバーセンターの移転ということがもちろん前提ですので、通常の今までの一般利用はそのまましていただいて、もちろんグループ活動もしていただいて。","id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、どうしてもシルバーセンターに出張ってくるというか、利用するということも出てくるのかなと思うんですけど、ですから、そこら辺のところはそういう仕切りをつくるのかどうなのか、そういうルールをつくるのかどうなのか、今の考え方は考え方でいいんですけど、そこのところはどういうふうにするのか。そこら辺の考え方というのはどういうことなのか、あわせて伺いたいと思います。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"その結果、先ほど申し上げましたように、大きくは区の助成をお願いするもの、あるいは貸付をお願いするもの、自己負担で自己資金を調達するものというのが、基本的なその３つの要素で提案がありまして。シルバーセンターの事業の仕切りの問題ですけれども、協定とか助成金の要綱で、協議の上、事業内容を決めていくというのがありますけれども、設置につきましては運営規定というようなものもつくっていただいて。","id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"これは自己資金だけじゃなくて、区の貸付金も出てくるということだと、当初の対法人との関係、募集のときの募集要項というんですか、そういうところとの関係ではどうなってくるのかなというのが、そこのところをちょっと伺っているんです。これはどうも、後からくっつけたと思えてしようがないんですけれども、そこら辺のところをちょっと説明いただきたい。","respondent":"蓼沼高齢福祉課長","answer":"それから施設整備費につきましては、原則として運営事業者が負担します。ただし、地域住宅交付金や都の補助金の歳入を建設費に充当するほか、区から一定の助成貸付を行う予定ですということが当初の想定です。","id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"当初、１６万円から２０万円、利用料の算定が出されていましたけれども、少なくともそういうところにも影響してくるかもしれないということになるわけですね。ですから、これは後から、これも負担が出ます、あれも負担が出ますというやり方は、やっぱりしないほうがいいと思うんです。ちょっとそんな感想を持ちましたということを言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護給付費と地域支援事業の負担金、交付金を返還するということでの、その主な中身について、教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"それから地域支援事業交付金ですけれども、国の負担のものについては、１,３４７万６,０００円、都の負担金については、６７３万８,０００円、支払基金交付金への返還が１,１２７万２,０００円、合計３億４,９４３万３,０００円です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは予定していたものよりも、使わなかったということで返還するということではないんでしょうか。それであれば、予定していたものが使われなかったという、そこの中身があるのかなというふうに思ったんですけれども、そういうところでの中身について、お聞かせいただきたいということです。","respondent":"蓼沼高齢福祉課長","answer":"実際に執行した介護給付費がありまして、それが当初予算よりも少なかったということで、結果として、その年度内にすべて清算もできませんので、一定程度の見込みで、国等から交付を受けるわけですけれども、平成１８年度、執行が終了した時点で。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当初予算を組んだときよりも、実際に給付してみたら、その給付が予算よりも少なかったということで、返還するということになるわけですよね。それなので、その当初見込みよりも少なかった主なものはどんなものですかということで、教えていただきたいということです。","respondent":"蓼沼高齢福祉課長","answer":"主なものは、平成１８年度の制度改正がありましたので、いわゆる予防給付です。要支援１それから２という区分が創設されましたけれども、そこのいわゆる予防給付費が当初見込んでいたよりも少なかったということが主な原因ではないかと思います。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、区としても予防給付ということで、予算としても減らした上に、さらにそれよりも下回るということの結果になったのかなと思うんですけど、そういう点では、それが実際の介護の現場にあらわれているというのがヘルパーの派遣であり、ベッドや車いすの削減というふうな状況になっていると思いますので、そういう点では、これは実際の実態に合わせた形での補正というふうなことで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと今の質問に関連してなんですけど、具体的に軽度の方が介護サービスを受けられないというのが非常に問題になっていたんですけども、実際に例えば車いす、あるいは介護ベッド、ヘルパーの派遣で、軽度の方が当初予算の利用が減るだろうということで、予算を組んでいたんですけれども、今の３つのサービスのところでは、実際にその見通しと現実というのはどんなものだったのかというのは、わかりますか。","respondent":"蓼沼高齢福祉課長","answer":"ただいまの車いす、介護ベッド、ヘルパーの時間数等というお尋ねですけれども、福祉用具の関係ですね、車いすと介護ベッドとの区分はちょっと手元にございませんけれども、大体当初、介護予防の方ですと、２億円の見込みが１,１００万円くらいですね。","id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと今、具体的な数字がわかればということだったんですけれども、ぜひこれだけの補正が出るわけですから、これは要するに実際の介護サービスが減っているということですから、やっぱりそこのところはぜひサービス利用がどういうふうになって変化したのかというのは、やっぱりかぎだと思うので、今日は持ち合わせていないということで、しようがないと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の宮崎委員の質問に関連してなんですけれども、介護ベッドと車いすは去年の９月から全面的にほとんど使えないということになったと思うんですが、その以前から、去年の４月ぐらいからはずっとそういうふうなことで対応がされてきて、半年間の猶予期間みたいな形であって、９月から全面的にという形になったと思うんですが、改めてこの介護ベッドと車いす、その前に使っていた方の人数と予算と、それから。","respondent":"蓼沼高齢福祉課長","answer":"６月の時点での数字ですけれども、福祉用具、車いすとベッドの区分はございませんけれども、件数で言いますと、平成１７年度、これは１月審査分ですけれども、３,０５１件、これが平成１８年度、やはり同じ１月審査分ですけれども、１,９３３件ということで。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そしてそれによって、予算がどう変わったかというのは、しっかりとデータとして持っていただいて、議会のほうにも報告をお願いしたい。ヘルパーの問題にしても、同様にぜひお願いしたいと思うんですが、いかがでしょうか。今の部分で、件数はおおよそわかりましたけれども、予算の部分でもちょっと教えていただけたらと思います。","respondent":"蓼沼高齢福祉課長","answer":"それからホームヘルプですけれども、同様の平成１７年度、平成１８年度のそれぞれの１月審査分の数字ですけれども、平成１７年度が４,０１１件、平成１８年度が３,６２６件、３８５件のマイナスで、金額としては２,８３０万円余というものになります。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ヘルパーのほうは、件数というのは受けている人ということですよね。そういうのだけでは、はかれない部分があると思うんですよ。時間数がほとんどの方が減らされたという問題がありますので、時間数もわかったら教えてください。","respondent":"蓼沼高齢福祉課長","answer":"時間数では、ちょっと出していないと思います。要するに月単位の定額制に変わりましたので、ですから、時間に換算するとという見方はあるかと思いますけれども、介護報酬を算定する上で時間数というのは多分出てこないと思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１時間やっても、１時間半であっても、同じ金額で事業所のほうには行くということになるので、難しい部分があるのかと思うんですが、現実問題は本当に２時間が１時間半に、また１時間に減らされたということで、大変な思いをしていらっしゃる方があるので、制度が大きく、こういう予防介護という形で変わったときなので、私は改めて、区のほうとしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"須藤委員","kind":"質問","question":"そういう仕組みが介護保険制度としてなされているならば、今のような話も違ってきちゃうと思うので、大抵今までは補正のときに見ていると、償還金という形になっているのだけれども、そのあたりの国とか地方自治体とか、こういうところの考え方はどういうふうになっているのか、教えてください。","respondent":"蓼沼高齢福祉課長","answer":"介護保険もそうですけれども、例えば老人医療費なども基本的には予算を立てて、それはやはり、どうしても見込みで立てざるを得ないと思います。","id":"exchange-043"},{"speaker":"須藤委員","kind":"意見","question":"中途でやり出したのは平成１６年のときからで、そのときは大抵足りなかったよという形ではなかったと思うんだけど、ずっと返しますよという形で清算したと思うんだけれども。そうすると、施策的にもっと根本的な予防給付をしっかり仕組みづくりをしなければいけないんじゃないかという話に、当然なってきちゃうと思うんだけれども、そのあたりはどうでしょう。","respondent":"蓼沼高齢福祉課長","answer":"平成１６年度から生じまして、東京都に返す場合は、その償還期限が１月ということが決まりでありますので、９月補正で対応せざるを得なかったというのが、この平成１６年度、平成１７年度、それから今年度の補正の処理です。","id":"exchange-044"},{"speaker":"堺委員","kind":"質問","question":"今須藤委員がおっしゃっておられましたように、ご説明いただいた考え方はわかりました。それで、平成１８年度にいただいた交付金の超過交付分を返還したと。当初見込んだ額ではなくて、それは超過交付金を返還したんですからね。だからそういう段階のときに、ちょっと説明するときに誤解を与えないように、きちっと説明をしていただければと思って、今回、この件についてもう１回改めて説明をしてください。","respondent":"蓼沼高齢福祉課長","answer":"これは介護予防、重度化予防という今回の制度改正の観点から、例えばホームヘルプサービスにしても、なるべく自立化を支援する観点からそのサービスの内容を見直しをしたものでございまして、そういう制度改正が恐らく影響して。","id":"exchange-045"},{"speaker":"堺委員","kind":"質問・要望","question":"そうなると、それ以上に何か繰越金があって、その一部を今回使ったけれども、全体で行くと、繰越金になるであろう金額が幾らなんですか、わかりませんが、そういう多額なお金とすると、考え方の中には、これはストレートに結びつけていいのかどうかわかりませんが、例えば保険料についても、もっと安くしたらいいんじゃないかとか、そういう理屈も出てくるんじゃないかなとなっていきやすいから。","respondent":"蓼沼高齢福祉課長","answer":"要支援の介護予防給付にいたしましても、今回の制度改正は要介護状態にならない介護予防、それからそういう要介護認定された方については、重度化予防という観点で見直しをしたわけですけれども、特に要支援１、２の方に給付する予防給付というものは。","id":"exchange-046"},{"speaker":"宮崎副委員長","kind":"質問","question":"給付のほうが私は落ちていると、その中身を聞いたんですけど、なかなか明確な話がないんで、ちょっと改めて伺いたいんですけれども、先ほどの介護ベッドなんかが給付対象から外れたんだということで説明があった。今まで給付されていた方で、見直しによって給付されなくなった人というのはいるんですか、いないんですか。いたら、何人ぐらいいるのか。そこのところの数字はありますか。","respondent":"蓼沼高齢福祉課長","answer":"それは先ほど申し上げましたけれども、ベッドと車いすの内訳はございません。ただ両方合わせた数字は先ほど鈴木委員に答弁したとおりです。","id":"exchange-047"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私ごとですけれども、品川区民じゃないんですけれども、去年要介護１で、それで介護ベッドのレンタルを介護給付で受けていたんです。それが見直しで、要支援２となって、もう見事給付が打ち切られました。起きれば、自分で何とか家事、料理、洗濯できる。私は今日、残念ながら具体的な数字が、今までの受けていた人で給付されなくなった数をしっかり出していただきたいと、重ねて言いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この国庫支出金の返還金というのは、総給付費の２５％いかないものが国の負担割合ですよね。ということは、総給付費にすると、どれぐらい減額になるのかなというのを考えたんですけど、これの約４倍と考えていいでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"質問のご趣旨がよくわからないんですけれども、要するに給付費の負担が、保険料が半分と税金が半分で、国が２０％、５％が調整交付金、都と区が１２.５％ずつと。支出が見込みよりも下回ったので、その割合に応じて返還するというものです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はどれくらいの給付が予定よりも下がったのかなというところを考えたいと思ったので、国の負担割合というのは品川区で言えば、調整金がありますので、２３％ぐらいになるのかと思うんですけど、それを考えると、総予算よりも給付費としてどれぐらい少なかったのかというふうなことを考えると、国庫支出金の返還金の約４倍の１４億円ぐらいということで考えていいんでしょうかということで、質問をしました。","respondent":"木下福祉高齢事業部長","answer":"それで、再三申し上げていますけれども、今回のこの補正は特別なことが背景にあるわけじゃなくて、要は平成１８年度中に国とか支払基金とか、東京都に見込み、何回か修正をして、交付金をもらうわけでありますけれども、大体過払いになるようにもらうわけですね。","id":"exchange-050"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"この被爆者に対する援護に関する法律で、いわゆる原爆症を認定してくださいということなんだけれども、原爆症認定と、被爆者健康手帳を持っている方々との差というのはどういうことがあるんですか。","respondent":"高橋障害者福祉課長","answer":"被爆者健康手帳というのは、地域が限定されたところで、そこにいるということが証明されれば、手帳が交付されるというような状況です。認定制度というのは、医療の給付や特別手当を受けるために、厚生労働大臣の認定を受ける必要があるので、認定を申請するというようなことです。","id":"exchange-051"},{"speaker":"須藤委員","kind":"質問","question":"被爆者健康手帳を持っていると、やはり医療の給付は受けられるんじゃないんですか。これはまた別になってきちゃうのか。原爆症を認定されて、初めて医療の給付が受けられるという形になっているのか。被爆者健康手帳を持っていると、それなりの給付があるんじゃないのかな、医療機関で。","respondent":"高橋障害者福祉課長","answer":"認定を受けることによりまして、認定による医療の給付、それから一般疾病による医療の給付の２つの制度が、全国で、無料で医療の給付が受けられるという状況です。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと今の説明で、まだ十分にわからないんですが、手帳を持っているということは、健康診断と指導、それしか受けられないという状況になっているんでしょうか。もう１つ、ここには手帳を受けられている方は全国で２５万９,５５６人いらっしゃるということなんですけど、品川区内では手帳を受けられている方がどれくらいいらっしゃるのかと、認定されている方の数も合わせて教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"ただ、私どもでは、８月に見舞金給付ということで、東京都からの名簿を受けまして、手帳取得者に対する見舞い金を交付しております。今年度につきましては、８月に支給したところでございまして、２１５人が手帳を持っているというような状況です。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にここに書かれているように、手帳を持っている方の０.８６％の方しか、そういう医療を受けられたり、手当が受けられていないという、これが何かあまりにも乖離があり過ぎるという感じがするんですけど、特に私も一昨日、ちょっとテレビの深夜番組で、この原爆症の方の問題を特集で取り上げているのを見たんですけれども、そこにも品川区の方も出られていましたけれども、被爆されたときに。","respondent":"高橋障害者福祉課長","answer":"申しわけございませんが、認定するのは厚生労働省のほうなので、その認定基準が乖離しているかどうか、私のほうではつかんでおりません。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、それそのものが大きな問題を抱えているのではないかなと思うんですけれども、そういうところもぜひ担当課というところでは思いを寄せて、つかんでいただけたらと思います。それからもう１つ、地域限定で手帳の交付を受けられるということなんですが、その地域というのは爆心地からどれぐらいという距離があるのかと思うんですが、そのことについてもお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"それと、そのほかに原子爆弾が投下されてから２週間以内に救援、医療活動等に入った者、それと、その胎児の者ということになっております。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"先ほど担当課長のご説明の中でも、３月９日ですか、都議会が、衆議院・参議院の議長、それから関係大臣等にも意見書を出された。そういう意味から、この請願書につきましては、意見書提出ということで、採択していただけるものと考えています。そういう方々のためにも、ぜひこの請願に書かれてあるようなことが１日も早く実現されるように、との思いを込めまして採択していただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"請願の趣旨につきましては、よくわかります。理解いたしたいと思います。私どものほうでも、会派の中でいろいろお話をやりとりさせていただいた経過もありますし、先ほど来、出ていますように、さきの首相ほか、国の動き、そして東京都議会の動き等々もありますので、私たちもこの委員会の中で、趣旨が理解されれば、意見書としてまとめて、国に対して要望していきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に戦争の犠牲で、被爆されたという、これほどの大変な犠牲になりながら、戦後６０年間、こんな事態に今までなっているということそのものが問題だと思いますし、共産党としても２年前からこの問題では対策委員会をつくって取り組んでいるところです。ぜひ採択をして、意見書提出というところでやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１回目、２回目、３回目。それで今回も、私が今、トータルしましたら、７６６人の方が、８月２１日に説明会がされてから、その後から９月１３日まで１カ月もない中で、こんなにたくさんの方が署名されていますし、１回目、２回目も１,０００名以上の方が署名されていまして、地域の方にとっては、強い願いだというところを、区としてどう考えられているのか。その点について、まずお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"それについて特に事前に説明会を開くということは考えておりません。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その利用料について、地域で理解が得られていると考えているのかということをお聞きしたいのと、これほどの強い地域の要望で、請願が出てきているということに対して、どう考えているかということをお聞きしたので、お願いします。","respondent":"蓼沼高齢福祉課長","answer":"ここに主張されているご意見は、特別養護老人ホーム並みといいますか、国民年金者でも入れる利用料にしてくださいということなんだろうと思いますけれども、これについては、さきの請願審査のときもご説明して、理解して、ご決定していただきましたように。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会ではそういう利用料について、決定したということはないと思うんですね。そういうふうなところで、地域にこれほど強い要望があって、これだけの運動がされていて、それで説明会も開いてほしいという、今回の請願が改めて出ているにもかかわらず、その地域が納得しないままに進めていくつもりなのか、そのことをちょっと、改めてお聞きかせください。","respondent":"蓼沼高齢福祉課長","answer":"そういう利用料についてのご意見、ご要望は、それはそれでおっしゃられることは結構だと思いますけれども、区の考えは、今検討しているところですけれども、大体の金額については、何回も申し上げておりますけれども、１６万円から２０万円ぐらいのところ。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、１６万円から２０万円ということで、今、出されましたけれども、その１６万円から２０万円という利用料というのが、何に基づいて、どういうふうに決められていくのかという、そこの仕組みを聞かせていただきたいと思うんですが、１つは介護報酬の特定介護施設の１割負担というのがありますよね。それとあとは食費になると思うんですけど、その食費がどれくらいになるのか。","respondent":"木下福祉高齢事業部長","answer":"請願のほうに上げられているような部分というのは、ここの施設では私どもとしても多様な選択肢を用意するという考え方でいきたいと思いますので、特別養護老人ホームについては、相当量ありますので、全体で介護を要する高齢期の住まいの施設が今。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"多様なニーズにこたえて選択肢を広げていくというのは、それはいいと思うんですよ。それはもう８０年にわたる原小学校の跡地、これは地域のシンボルという、それぐらいのものですから、特にこの原小学校の跡地には地域の方が本当につくってほしいという、こういう施設にしてほしい、排除しないでほしい、こういうことに対しては、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"全体の中で、その辺はご理解をいただければと思います。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういうお金なんですよね。そういうふうに、お金の出せる人だけを対象にした施設ではなくて、お金のない人を排除しない、みんなが入れる、そういう施設にしてほしいというのが、ほとんどの区民の皆さんの願いだと思いますよ。そういう姿勢で区が運営をしてほしい。そういう姿勢で建設をしてほしいということなんですね。そういう施設をぜひつくってほしい。こういう形でできないですかね。","respondent":"木下福祉高齢事業部長","answer":"全体としては、特別養護老人ホームを含めた中で、今のお話につきましては、私どもとしては対応をさせていただきたいと思っているところであります。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区がつくる施設として、厚生年金の方は入れるけれども、国民年金の方は入れない。国民年金の方を排除する施設、そういう施設を区の姿勢としてつくっていくということでいいんでしょうか。","respondent":"木下福祉高齢事業部長","answer":"それを原小学校の中で実現するのかということでは、現実には制度の枠組みから言うと難しいと考えています。今、お話があった部分については、特別養護老人ホームも含めて対応をするです。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、区がそういうふうに、お金のある方だけを対象にしたそういう施設を今までも進めてきて、さらにこれからも進めていくという、そういう方針を出していますけれども、そういう方針を出しているのって、品川区だけじゃないですか。どこの自治体でも、２３区、どこをとっても、その新型特別養護老人ホームをつくっているわけじゃないですか。だからそういう姿勢をほかの区はとっているんだと思いますよ。","respondent":"木下福祉高齢事業部長","answer":"やはり問題認識は、若い人に選ばれる職場にしていかなければ、これから介護現場は成り立たないということでありますので、そのことについて、多方面からの議論が必要でありますし、恐らく介護報酬に関しての各区の意見を求める機会が多分出てくると思いますので。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特別養護老人ホームの問題では、私も改めて特別養護老人ホームのお話を聞いて驚きましたけど、２.２対１というふうに実際はなっていないんじゃないですか、多分。だから自治体のやることですから、やっぱり本当にだれも、全員が入れる減免制度をつくるような、そういう施設に自治体としてやるべきなんじゃないか。その特別養護老人ホームの改善のために、区が力を尽くしてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと関連すると思うんですけれども、１つ確認しておきたいんですけれども、今回は利用料１６万円から２０万円を考えているという説明であるんですけれども、それが厚生年金で入れる施設だと、そういうことを考えて、この値段にしているという説明なんですけれども、そうすると、この請願にもあるんですが、国民年金しか収入がないという場合には。","respondent":"蓼沼高齢福祉課長","answer":"ですから、この年金受給者だけを入居者として想定しているのかというと、そういうことについては、特に区としては考えていないです。","id":"exchange-068"},{"speaker":"宮崎副委員長","kind":"質問","question":"私の質問が、単純明快にすると、答えを聞いているんですけれども、先ほど部長は厚生年金で入れるようで、そういう施設の視点で考えたんだという説明だったんですよ。課長は国民年金は大体五、六万円が月平均ですよという説明でした。そうすると、今度の原小学校の跡につくるケアホームは、国民年金しか収入がない人は対象外ですという想定で考えてもいいんですねということを聞いているんですが。","respondent":"木下福祉高齢事業部長","answer":"つまり、国民年金６万円で生活できるかという、これ、実態を見ていきますと、持ち家で可能性はあるかもしれませんけれども、家族の仕送り、あるいは同居、いろいろな形で支援を得ているというのが多くの方の状況だと思います。","id":"exchange-069"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういうふうに受け取ります。社会福祉法人のほうに負担を増やしている。もう１つ聞きたいんですけれども、多様なニーズにこたえるんだと言いますけれども、４５０人待っているこのニーズというのをどう考えるのか。このニーズをどう考えるのかということと、もう１つは今、区内の二葉町のあたりでも、民間の業者が有料老人ホームをつくっていますよね。そこのところはどういうふうに説明するんですか。","respondent":"木下福祉高齢事業部長","answer":"区全体の施策の中で、そこは対応をするということでありますので、あまり形式的にこういうふうな発言があったということで、誤解されるようなものの言い方はされないようにしていただきたいと思います。","id":"exchange-070"},{"speaker":"宮崎副委員長","kind":"質問","question":"リーズナブル、リーズナブルと言うけど、確かに今までの施設からすれば、今の１６万円から２０万円というのは大分安くなったと思いますよ。今、部長は家族、親戚から応援をもらえばいいじゃないかと、そういう説明でしたけど、それじゃあ、そういう人たちには特別養護老人ホームにいつまでに入れますという約束ができるんですか。そういうところはどうやって改善するのか、ちょっと最後に伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"特別養護老人ホーム、あるいはこういうケアホーム等、部長から再三ご説明しましたように、全体のバランスを考えながら整備する必要があるだろうということで、特別養護老人ホームについては大体７で、そのほかが３というようなことです。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが１つ。それから老人保健施設にしても、今５００人、老人保健施設を利用している。だけど、品川区内のベッドは１００ベッド。４００ベッドは他の自治体にお世話になっている。在宅にしても施設にしても。そこのところはどう考えられているのか。こういう中で、特別養護老人ホームを完備しているというのは、何を基準に、何を根拠にそう言われているのかということを改めてお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"それについては、今、この地域ケア整備構想、都が策定をしておりますけれども、具体的にそういう転換以降の調査はまだ進めているところですけれども、その結果、区としても具体的な、必要な支援等があれば、対応していくということになろうかと思います。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認定率はもう品川区はすごい低いですから。認定率は、もう本当に全都の中でも下から３番目かそのくらいじゃないでしょうか。それから待っている方というのも、前も申し上げましたけど、この待っている方というのは、ほかのところは半年ごとにというふうにやっているところはあまりないですから。１回申し込んだら、ずっと積み上げていくわけですから。このことを最後に教えてください。","respondent":"蓼沼高齢福祉課長","answer":"このケアホームについては要介護１以上の方が対象になるということで、その割合になろうかと思いますけれども、ただこういう施設サービスについては、ここだけではありませんので、特別養護老人ホームを含めて、原小学校、都南病院跡のケアホーム、あるいは西五反田も含めて。","id":"exchange-073"},{"speaker":"須藤委員","kind":"質問・要望","question":"請願につきまして、理事者にいろいろ質疑されたので、内容的によくわかってきましたので、逆に品川区の高齢者福祉施策の考え方もよくつかめてきて、ここだけの限定ではないというお話も聞かせていただきましたので、そろそろ結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"堺委員","kind":"質問・要望","question":"本日結論を出すということで、お取り扱いいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"堺委員","kind":"意見","question":"この件につきましては、結論からまず不採択ということで。それが１点。ただ、この請願項目にあるような、気持ちとしては私もなるべく多くの方々が利用できるような施設といいましょうか、利用料金を含めて、そういうものはわからないではないんですが、やはり全体のバランスということを考えると、現時点ではやはりこの請願についてはどうしても不採択にせざるを得ないということで、意見を申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中身に関してばかり話をしてきて「説明会を開いてください」というところの意見をなかなか言えないままに終わってしまったんですけれど、やはりあれほどたくさんの方が詰めかけて、あれほどの意見が出たわけですから、この地域の声を無視して強力に進めていくのではなくて、地域の声をしっかりと聞いて、そして地域の方々が納得できる形で進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"須藤委員","kind":"質問","question":"請願内容の１番目ですけれど、これだけを単独でというのは難しいという説明ですよね。法的にこれだけ単独でというのは、品川区が公的に責任を持ってやれというのは非常に無理な話になっちゃうのかな、こういう状況をつくるっていうことは。それをちょっと教えてください。","respondent":"高橋障害者福祉課長","answer":"看護業務ですが、基本的には医師、歯科医師の指示のもとに行うことが、保健師助産師看護師法第３１条に載っております。医療行為の禁止につきましても第３７条に、保健師等につきましては医師の指示のもとではないと業務を行ってはならないというふうになっております。","id":"exchange-078"},{"speaker":"須藤委員","kind":"確認","question":"では２番目をもう一度確認だけれど、今現在、障害児の自立支援法に訪問看護師派遣というのはないということですから、ケアの時間延長とそれに伴う云々というのはないよという理解、介護士でそういうのがあるよという形ですね。それから３番目、いわゆる訪問看護事業をやっていただいておりますけれど、これも補助金として行政からは支援していないという確認でよろしいですか。","respondent":"高橋障害者福祉課長","answer":"委員が言われたとおり、２番目の問題につきましては障害者自立支援法上、制度としてございません。それと３番目の補助金の部分につきましても、区内のヘルパーステーション、訪問看護ステーションにおきましても、介護医療報酬の中で運営を行っているのが現状です。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の訪問看護の制度が介護保険と健康保険、医療のほうの制度があるということなんですが、もうちょっと詳しくお聞かせいただきたいんですが、曜日、祝日、時間の制限を設けないでください、ということでありますが、ここら辺は実際はどうなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"この曜日、時間ということでは、主治医が指示したということになりますので、医療行為的な処置が必要かどうかというところで判断したかと思います。ですので、その辺の現状につきましては医師が判断したということになりますので、私のほうでは現状としてはつかんでおりません。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療での訪問看護という制度そのものが１週間に３回を限度として受けるという制度になっていて、２４時間体制ということでやっているとお聞きしました。だから、訪問看護を実際にもう受けているということであれば、曜日、祝日、時間で対応されないということはあまりないのではないかと思うんですが、そこら辺のところがわかったら教えていただきたいのが１点です。","respondent":"高橋障害者福祉課長","answer":"こういう方につきましては、看護師の派遣だけではなくてヘルパーの派遣も含めましていろいろな形でサービスを受けて、在宅での生活を続けていらっしゃる方かと思いますので、単独でこれだけが必要かということには、今の時点では考えられないかと思います。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ただ、そういう訪問看護ステーションで受けるという受け皿が足りなくて、訪問看護を受けたいと希望しても受けられないような状況があるのかどうかをつかんでいたら、教えていただきたいという質問です。","respondent":"高橋障害者福祉課長","answer":"ただ、いずれにしましても医師なり、かかりつけ医なりが必要とする判断をした中での在宅での生活ということになりますので、その辺については受け入れる、受け入れられないじゃなくて、そこの医師が必要と認めれば訪問看護ステーションのほうで派遣は可能かと思います。","id":"exchange-082"},{"speaker":"本間委員","kind":"意見","question":"私どものほうで紹介議員になっている関係もございまして、今、中身を十分説明いただきまして、よく理解しています。趣旨的には非常にわかる部分もありますが、少し勉強不足のところもあります。できましたら、継続という形にしていただけたらありがたいというのが意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"須藤委員","kind":"意見","question":"理事者から説明いただきましたように、請願内容がなかなか現状では、品川区が法的責任を持ってやるには法的な問題やいろいろなことをクリアしなきゃいけないと思うので、この請願内容ではなかなか前に進めがたいという感じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"本間委員","kind":"質問・要望","question":"先ほども言いましたので繰り返しになりますが、意見を言うならば、扱いについては継続にしていただきたい、再度改めてということもあります。そうでなければ、ここで結論を出すということであればそれなりの意見表明をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"堺委員","kind":"質問・要望","question":"ただ、近い将来、こういう方々が持っておられる悩みや何かも何らかの形で解消されるように、我々政治に携わる立場としては努力していかなきゃいけないのかなという気もしますし、また行政側でもそういう努力はしていただきたい。重ねて、いかなる人であろうとも「生きるために必要な最低限の権利」、これは保障されてしかるべきであろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ただ訪問看護の実態としては、訪問看護の体制がないために、ドクターからの指示が出て訪問看護をお願いしたいと、お願いしても受け入れ先がないということで困っているというお話もお伺いしましたし、またこちらに書かれている学校行事などについても全額自己負担で、全部ストレッチャーで行かなくちゃいけないようなときにしても、車から何から何まで全部自分でやらざるを得ないとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]},{"id":"topic-03","title":"の３、報告事項","agenda":"の３、報告事項","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今説明いただいたんだけれど、広域連合のほうで９月１２日に厚生労働省に要望を出されたことは、ちょっと触れておいたほうがいいんじゃないかと。","respondent":"冨岡高齢事業課長","answer":"委員ご指摘のように９月１２日に、一都三県の広域連合によりまして国への緊急要望書の提出がございました。その内容ですけれども、保健事業への財政支援、制度周知、国庫負担金等の速やかな交付、調整交付金の別枠交付といったような内容です。","id":"exchange-088"},{"speaker":"宮崎副委員長","kind":"確認","question":"先ほど交付金は３０％よりもうちょっと多くなりそうなことを言っていたんですけれど、それに関連してちょっと聞きたいんですけれど、この資料２－２の３ページのところに、平均的な所得水準の広域連合、低いところ、高いところとあるんですけれど、確認しておきたいんですけれど、東京はこの高いところに入るんだろうと思うんですけれど、そういうことでいいのかどうなのかということと。","respondent":"冨岡高齢事業課長","answer":"それで計算の仕方ですが、これは非常に複雑な計算がありまして、例えばこの資料に基づくところを見ていただきますと、１２ページの一番上ですけれども、そこに保険料が１,５８０億円となっております。","id":"exchange-089"},{"speaker":"宮崎副委員長","kind":"質問","question":"聞くところによると後期高齢者交付金は、いわゆる国庫だとかそういうところから抜ける分がこっちに財源で行くんだと聞いているんですけれど、それぞれの負担を増やしていくと、例えばここは約４０％になっていますけれど、これを増やしていくと今１０％の保険料が圧縮されていくというふうな計算にもなるんですけれど、果たしてそういうことは可能なのかどうか、どうなんでしょうか。","respondent":"冨岡高齢事業課長","answer":"可能かどうかということは、理論的にはあり得ると思いますけれど、具体的にはこれから検討がいろいろされていく部分だと考えています。","id":"exchange-090"},{"speaker":"宮崎副委員長","kind":"質問","question":"調整交付金が３０％と１００％と２つケースが書いてあるんですけれど、今の説明だと１００％というのはほぼあり得ない、大体３０％のほうにかなり近いのかなと受けとめたんですけれど、それでいいのかどうなのかということも、あわせて伺いたいと思います。さきほどの財源構成のところは理論上と言われたんですけれど、その辺は実際には議論されているんでしょうか。","respondent":"冨岡高齢事業課長","answer":"それから３０％がどうなのかですけれども、これは全国の所得と都の広域連合の対象者の所得という形の計算をしなければいけませんで、やりとりをしている段階だと聞いておりますので、まだこれからどうなるかちょっとはっきりしていないと。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１５ページのところに３０％と１００％交付時ということで、均等割、所得割とそれぞれ書かれていますけれど、ここにぜひ国保料が現在どれぐらいになっているのかということをあわせて示していただけたら、現在の保険料からどれぐらい変わっていくのか見えやすくなるので、そういう表をぜひ資料として出していただきたいと思うんですけれど、その点お聞かせください。","respondent":"冨岡高齢事業課長","answer":"それから資料の件ですが、これは資料の出し方が、基準が多分違っていると思いますので、ここに出すのはちょっと難しいかと思います。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そっくり出すのが難しいのであれば、幾つかの区がそういう資料を出しているというので参考にいただいたものがあるんですけれど、例として、年金額が幾らに対して、現在の国保料と今度の高齢者医療で３０％のときと１００％のときでどうなのかというところを、試算としてぜひ出していただきたいと思うんです。","respondent":"冨岡高齢事業課長","answer":"そこの下のほうに、（１）と（２）の制度が重なる場合は（１）を適用すると出ておりますので、こういうふうに対応されるかと思います。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこでちょっとお聞きしたいのが、資料２－２のところで国の負担の１２分の４の内、１２分の１が調整交付金ということで、それが所得水準の低い、高いで１２分の１全額もらえるかどうかが問題になっていると思うんですけれど、そこで減らされた分はすべて保険料としてかかってきちゃう、それ以外の都や区や負担金とかにはかからないで。","respondent":"冨岡高齢事業課長","answer":"それから葬祭事業を行うのか行わないのかというのも１つありますけれど、行うとすると保険料で対応すると。それからもう１つ、今の保健事業ですが、これにつきましてはやはり今のままですと保険料で対応するです。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば品川区にしても、国保に一般財源を平成１９年度でいえば３８億円余投入していますし、東京都でも１４億円余投入していますけれど、その国保の中で７５歳以上の医療費というのは給付の多くの部分を占めると思うんですけれど、それがそっくり後期高齢者医療制度に持っていかれちゃうということで言えば、区の負担は逆に減ることになってくるんでしょうか。","respondent":"冨岡高齢事業課長","answer":"この制度につきましては、医療の負担ということで皆保険の制度ですので、だれが一番負担が少なくなったかというと、支援金の現役世代の方が人数も減ってまいりますので、これ以上負担がかからないようにという形で対応しているものだと理解をしております。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何がどうなっているのか、なかなかわからない部分もあると思うんですけれど、そこら辺のところをもっとわかる形で明らかにしていっていただきたいと思います。こういうことでは、７５歳を過ぎた方が健診をやる中で重要な病気が隠されていることを発見できないんじゃないかという思いがしているんですけれど、７５歳を過ぎた方の健診項目に関しての考え方という点ではいかがでしょうか。","respondent":"中村品川区保健所長","answer":"もちろん健診項目は少なくなってありますけれども、７５歳未満の段階で基本健康診査である程度やって、異常があればもちろんそれが続くということで普通の医療の中で考えるですので、その後７５歳以上でこの項目で新たに異常が見つかれば、またそれで行くということで。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"各自治体でということであれば、品川区が今までやっていたものもプラスしてやっていくということも考えられるんでしょうか。","respondent":"太田健康課長","answer":"さきの本会議でも同一の質問がございましたけれども、現在、国民健康保険を所管する国保年金課を中心にして、庁内での検討会を今進めているところです。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"貧血なんかにしても、出血だけじゃなくてがんだとか腎機能だとかいろいろな問題がありますし、腎機能そのものも診ていませんし、心電図も眼底も診ていないわけですから、早期に対応すれば重症にならなくてすむ、隠されているものが見つかることが含まれているというところでは、７５歳を過ぎているからもういいですよというのではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"堺委員","kind":"質問","question":"今のことと関連するのかもしれませんが、資料１－１の説明の中で７５歳以上の健康診査等についての実施主体で、広域連合の努力義務とあるんですが、説明いただいたのかもしれませんが、この努力義務というのは何なんですか。","respondent":"冨岡高齢事業課長","answer":"努力しなさいということを義務づけるということです。実際問題といたしまして広域連合では、そうは言っても実施をいたしますという形で、今、協議会でまとめたところです。詳細についてはこれからさまざまな機関と調整しながら検討していくということになっております。","id":"exchange-099"},{"speaker":"堺委員","kind":"質問","question":"義務と努力義務というのは漢字の理解、解釈ではわかるんですが、さっきあったように７５歳以上になると、ある面ではある一定の年齢まで、平均寿命直前ぐらいまで生きたんだから健康診断しなくてもいいよというふうにとられているわけですよね。だけど、そうじゃないんですよということでしょう。だから決して高齢者の健康診断を軽視するということではないんですよというふうに理解をしていいんですか。","respondent":"冨岡高齢事業課長","answer":"しかも、実施については区市町村に委託化する方向で検討しているということで、そういう形ではまとまっておりますので、東京都の広域連合においては後期高齢者の方についても健診は必要だという判断をとっているところです。","id":"exchange-100"},{"speaker":"堺委員","kind":"確認","question":"したがって７５歳に到達したから、もう健康診断を受けなくていいよ、健康診断の項目が減っちゃったんだよということではないんですねと。その辺をちょっと確認しておきたいということです。","respondent":"冨岡高齢事業課長","answer":"そういうふうに国は考え、広域連合のほうも実施をするということで受けとめているところです。","id":"exchange-101"},{"speaker":"堺委員","kind":"提案","question":"最近いろいろな報道等でも医療費の増大というんですか、歯どめをかけないとこのまま行くと大変なことになってくるという形から、保険についても医療についても予防という視点に大きく変化している、そういう意味でいわゆる健康づくりという形の施策がどんどん取り入れられるようになってきたわけで、それは時代の大きな流れだろうなという気はするんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私も今の堺委員の提案に対して賛成です。いろいろな議会から、もう既に意見書が上がっているということもお聞きしていますし、ぜひこの厚生委員会としても国に対して意見書を上げていくという方向で、ご決定いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"須藤委員","kind":"質問・要望","question":"私どもも意見に賛同いたします。我々の中でも会派の中でいろいろな考え方が出されましたので、整理をして今日中に委員長のほうへお持ちさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"堺委員","kind":"質問","question":"それをもとに正副委員長に精査していただいて、極力各会派の意志が反映できるような形に調整していただいて、明日の委員会でその案文を皆さんにお諮りして、それをまず委員会の意志として固めていただければいいんじゃないでしょうか。それで、ステップとして今度は議会運営委員会に提出をされて品川区議会として出したほうが、と思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"須藤委員","kind":"意見","question":"今、堺委員より品川区議会として出したほうが、というお話もありましたので、厚生委員会として出すことも地方自治法の改正でできるようになったけれど、議長と委員長とでご相談していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどもお願いしたんですけれど、現在の国民健康保険の保険料がどれぐらいかという資料も、年金が幾らの人が幾らかというのは国保のほうで出せると思いますので、それがあるとより、現在と比較してどれぐらいの保険料になるかというのがすごく見えると思いますので、明日その案文とあわせてぜひ資料として委員会に提出していただきたいと思うんですけれど、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"須藤委員","kind":"意見","question":"私自身はまだ今回については、もう少しこの辺が固まってきて、じゃあ、それと比較しましょうというときならそういう話も必要かもしれませんけれど、まだあらあらで決まっていませんという状況なので、それだけの仕事を理事者にどうのというのは、明日までに意見書をまとめるという時期にちょっと無理な話だろうと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"堺委員","kind":"意見","question":"むしろ出すのであれば今日の審査に係る参考資料ということであれば、事前にあったほうがそれは参考になったかもしれませんが、個人的には委員会資料として要求する必要性はないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"本間委員","kind":"質問","question":"会合につきましてはまだまだ緒についたばかりということで、これまで２回ぐらいしか会合ができないとか、逆に見えない部分が当事者自身も一番困っている部分でありまして、須藤委員からもお話がありましたように、これからという中、先ほど理事者からもそれぞれのレベルでの報告をされましたけれど、そういう中でのことですから、まだ見えない部分。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"高橋委員","kind":"意見","question":"明日の意見書に関して必要かどうかということだと思うので、それを使って検討するのには必要ないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は介護保険の平成１８年度の品川区の制度運営状況について、ぜひ区のほうからご報告をいただきたいということでお願いしたいと思っているんです。だからぜひそういう点では、大きく制度が変わったその年のまとめですから、厚生委員会に報告をしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１２年からですからこれが６年目ですね。そういうところでぜひ私たちが介護の実態をつかむのも必要だと思うんです。そういうところで報告をいただきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"須藤委員","kind":"提案","question":"鈴木委員の提案が急だったのでちょっとあれなんだけれど、私自身は委員が報告せよと議会の中、委員会の中で要求してくればできることだと思います。ただ、唐突に何でどうだと言われたので、ちょっとそのあたり、もう少し鈴木委員の話を聞いてみないとわからないので、すぐ、じゃあ、賛成、反対ということではないので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-114"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"要するに、今までは各年度ごとの運営状況についての報告が厚生委員会にあったんですけれど、それが今はないので、そもそも介護保険は厚生委員会の所管なので、やはり年度の運営状況についてはしっかり報告をいただくということを求めておりますので、ぜひそういう機会をつくっていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問・要望","question":"だけれど、ほかでもそういう話はされていますよと。そのあたりは私どももきちんと整理をして、もう一度鈴木委員の質問に対して答えていきたいということなので、今すぐに賛成、反対ということじゃなくて、いわゆる全体の流れからやらないと、何でもかんでも全部、資料どうのこうのという形をつくっていっても大変な仕事になってくる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/443219?Template=document&Id=3182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":85146,"voices":279}},{"id":"h19-20070925-8","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"建設委員会","time":"午前１０時０３分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件抜き出しています。","topics":[{"id":"topic-01","title":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回、新設される大崎駅西口区営自転車等駐車場ですけれども、収容台数が、定期で６２０台、当日利用が３２３台とありますけれども、この台数というのは、どういった考え方によって設定をされたのか。それから、大崎駅西口第３のほうが、耐震補強工事終了後にバイクを移設すると書かれていますけれども、何台分ぐらい考えているのか、教えてください。ちょうど先週の土曜日に、周辺を見に行ったんです。","respondent":"松嶋交通安全担当課長","answer":"続きまして、大崎駅西口第３につきましては、耐震補強工事終了後にバイク駐車場としてやる予定ですけれども、現在の段階では、一応、バイクはおおむね１７０台ぐらい設置できるように考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"見た感じ、確かに自転車も、バイクもいろいろありますから、あれですけれども、利用状況調査を行っているのかどうか、そこを伺いたいと思います。それから、通勤、通学者の利便性というお話ですけれども、定期利用者のうち、高校生とか、大学生、いわゆる学生の利用者というのはどれぐらいになるのか、教えてほしい。ということは、一定の時間になると閉まるものなのか、どうなのか。","respondent":"松嶋交通安全担当課長","answer":"したがいまして、これも調べればわかる部分ですけれども、今は手元にございませんので、お答えすることはできません。続きまして、西口にシャッターがある、これはどうかですけれども、ここは、終電後にシャッターを閉めて利用はできなくなります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"シャッターのことですけれども、１１月１日から始まる話ですから、今の時点で、何時から何時が閉まりますというその時間を正確に教えていただきたいと思います。指定管理者制度の導入を考えているのか、その辺、ちょっと考えがよくわからないので、教えていただきたいと思います。その辺はどういう感じになるのか、ちょっと教えていただけますか。","respondent":"松嶋交通安全担当課長、青木都市開発課長","answer":"いわゆる、シルバー人材センターの者につきましては、委託先がどのようになるかは、私のほうではちょっと認識はしておりませんので、その点は都市開発課長のほうから。８月３日の、本委員会におきまして、有限責任中間法人大崎エリアマネジメントにつきましては、簡単にご報告したところですけれども、この会社は、大崎駅周辺のまちづくりにおきまして、各権利者。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問・要望","question":"先ほどおっしゃっていましたけれども、中間法人の大崎エリアマネジメントなんですけれども、考え方としては、例えば、ここでは施設管理事業などで得た収益をまちづくりに使っていこうということなのか、それはとりあえず切り離して、とりあえずは、これはこれで駐輪場の委託というのはやって、それは普通の会社みたいに、収益はそこのものなのか、どちらなのかということを教えていただきたい。","respondent":"青木都市開発課長","answer":"駐輪場の需要の件ですけれども、現在、公共の駐輪場としては、今、新たにできるものは大崎駅西口で完成するものだけになりますけれども、東五反田地区、あるいは北品川地区等でも、今後、開発が予定されておりまして、それに伴って見込まれる駐輪需要については。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"中間法人のご答弁のところで、管理委託先としてこの中間法人に委託するわけですけれども、委託料というのは、年間契約になるかと思うんですが、どれぐらいを、今、見込んでいるんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"おおむねなんですけれども、今年度、１１月から始まりますが、３月までは、この地下駐輪場だけではなくて、大崎エリアということで約２,０００万円弱を考えております。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"ＪＲの利用も増えるわけですから、そこら辺の協力関係をどういうふうにするとか話し合いを持ったのか、私は、持つべきだと思っているんだけれども、そこら辺のところの努力はどういうふうにされて、だめと言われたのかは別としては、そこら辺の考え方というのはあると思うんですけれども、いかがでしょうか。","respondent":"青木都市開発課長","answer":"都市計画的に、あるいは、現状の利用状況から、この９００台の駐輪場を設置しております。大崎駅東口についても、区独自で駐輪場を確保して、何とか駅前駐輪対策等を行ってきているところです。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やっぱり交渉は交渉でしっかりするべきで、協力体制をどういうふうに仰ぐかというのは、また議論があるけれども、離れていくにしても、大崎駅を使う部分が多い地域がこれからどんどん出てくるわけですから、北品川五丁目地区なんか、五反田駅へ行くか、大崎駅へ行くかといったら、大崎駅を使っている人の多いわけですから、そこら辺の点も踏まえて、そういうふうに考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"第７２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第７２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"三つの再開発事業のことになりますので、まず一つ目の大崎駅西口Ｄ地区のことについて伺いたいと思います。はじめに確認させていただきたいのは、Ｄ地区についての事業費の予定、補助金、準備組合の加入率、現状はどうなっているのか、変更がないのかということと、ディベロッパーと建設会社、そこがどちらになるのか、まず確認させてください。","respondent":"岩田まちづくり事業部長","answer":"担当課長が、ただいま総務委員会のほうに出ておりますので、戻り次第、それらについてはお答え申し上げるとしまして、本条例の内容については、担当課長がいなくても建築課長でお答えできると思いますので、できれば、そういう議論にお願いしたいと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"その点については、都市開発課長が戻り次第、現状を確認したいと思いますので、後ほど、お答えいただきたいと思います。Ｄ地区ですけれども、今年の事務事業概要にも、周辺環境に配慮した業務、商業、住宅とのバランスのとれた都市環境というふうに記されておりますけれども、Ｄ地区を見ますと、形としては１棟になるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に駅前の商業スペースというのは、商店街への影響というのはどういうふうに考えているのか、そのお考えを教えていただきたいと思います。住宅棟ですけれども、結局、完成次第５,０００万円とか、７,０００万円という金額になりかねないと思うんですけれども、それについても、お考えを教えてください。","respondent":"岩田まちづくり事業部長","answer":"先ほども申し上げたように、既に、この計画につきましては、本建設委員会でもご説明を申し上げて、都市計画審議会の場で採択をしていただいて、既に都市計画決定が終わったものです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"それについて、区の考えがないのかということを、先ほど、お聞きしたわけです。地元住民という話もありましたけれども、今まだ担当課長がいらっしゃいませんから、準備組合の加入率が、今の時点ではわかりませんけれども、少なからず、合意の面でも、進め方がどうなのか、どうしても伺いたいところでありますので、その１点について、お答えいただきたいと思います。","respondent":"岩田まちづくり事業部長","answer":"したがって、準備組合は、この段階では、一応、自分たちの想定している住宅がどれぐらいとか、オフィスがどれぐらいというのは想定はしていますけれども、あくまで都市計画で定められたのは容量の大きさですので、当然、その中身については、今後変更は十分にあり得る話ですし。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井町駅前で、量販店が自転車を販売しておりますよね。まちの自転車屋さんというのは、自転車を売ってなんぼの商売で、部品の交換、パンクの修理、これはいわばサービスとして、また自転車を買いたいときに、自分の自転車屋を使ってほしいという思いでやっているわけですよ。続いて、北品川五丁目の再開発事業について伺いたいんですけれども、進め方はどうだったのか、一番気になることなんです。","respondent":"岩田まちづくり事業部長","answer":"ある日突然、こういったプランをぽんと地域の方に説明されたわけではなくて、２０年ほど前に、あのあたりで土地を持っている、商売をされている方々が、将来の地区のことを考えて、勉強会から始めて、お隣さんに声をかけて、協議会から準備組合へと発展されて。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｄ地区の事業予定と、補助金と、準備組合の加入率と、ディベロッパーと、建設会社。２月の建設委員会でも報告がありましたけれども、その後、変更がないのか、現状を確認したいと思いまして、ご説明いただきたいと思います。","respondent":"青木都市開発課長","answer":"本件のＤ地区は、大崎駅西口南地区という再開発事業で想定してございまして、予定しています事業費が、再開発組合で試算しましたものが１８５億円ほど、そのうち１６億円ぐらいは補助金を欲しいというか、補助金に該当すればということでお話をいただいております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"南地区のほうについて一言。私は、そこもまた、まちの合意がされていないことの一つのあらわではないかと思うんです。１日４時間余りの日照を奪うこの計画に、改めて伺いたいのは、近隣の方々、御殿山小学校の保護者の方々、昔からそこに住んでいるまちの方々が合意されているとお思いなのか、どうか、教えてください。","respondent":"岩田まちづくり事業部長","answer":"一般的には、北品川五丁目の準備組合の行った説明会に多くの周辺住民の方がお見えになって、いろいろなご意見をいただいたそうですが、当然のことながら、今まで、十二、三階ぐらい、ソニー通り沿いですと１４階ぐらいの建物のところに。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"結局、そこの地権者だけで決めるという、それを再開発事業として、私はほんとうに、公共性というのをどういうふうに考えているのかなと疑問に思います。事業費としても、総事業費が、この前に伺ったら９５０億円、税金投入１３０億円弱という説明がありました。この計画に対して合意は得られていると思うのか、再度、お伺いしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"ただ、先ほど言いましたように、周辺住民の方は、こういった大きな開発計画が示されたときには、当然のことながら、非常な不安とか、そういったものをお持ちになるのは当然の結果ですから、それに対して、当初は、例えば反対となったとしても。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の変更が３点ある最後に、東品川四丁目地区に対して、若干伺いたいと思うんですけれども、ご説明にあったＤ街区のＤ３－１、Ｄ３－２、Ｄ３－３と、かなり細分化しているわけですけれども、それぞれこれは何m2になるのか、教えていただきたい。それから、こんな再開発はほかに見たことがないんですけれども、何でＤ街区だけこんなに細分化されているのか、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"これが細かくなっている理由ですけれども、当初、地区計画を定めるに当たりまして、地権者の同意が図れれば、Ｄ街区全体を一体的に開発することが望ましいということで地区計画の方針を定めておるんですけれども、いかんせん、地区計画は大まかな地域のルールでございまして。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"当初は、別の計画があったけれども、地権者の方々のお話があったというお話がありましたけれども、適切に誘導と言いますけれども、こんなに細分化された都市計画というのはほかにあるんでしょうか。どんなまちづくりにしたいのか、結局、それはただ考え程度のことでしかないんじゃないかと、私には思えます。いかがでしょうか。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"誤解のないようにしていただきたいんですが、東品川四丁目地区の計画図の１というのをごらんいただきたいんですが、何度か色が塗っている街区全体が地区計画エリア。今回、地区計画の大もとの大きいところは、私のほうからご説明させていただいているように、高さをどの程度で合わせるかということと、壁面線の後退、セットバックをさせることでもって空地をつくる、これを条例で定めないと。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、今、ＡからＦまで地区があって、例えばＦは、商業地域に建築してはならない建築物、道路および隣地から壁までの距離とか、こういう形になると、ここは、場所的には学校があるところだと思うんですけれども、聞きたいのは、例えば複合化の中で、学校をいろいろな形で複合化して優良施設をつくる、もし地域にそういう声があったときに、可能なのか、どうかというのを教えていただきたい。","respondent":"片田建築課長、青木都市開発課長、岩田まちづくり事業部長","answer":"例えば原動機を使って１５０m2以上の作業所を営む工場等については、商業地域の中にはできないといったような内容を決めてあります。２点、お答えいたします。北品川五丁目第１地区の区域のお問い合わせですけれども、当初から、ソニー３号館付近は再開発事業の区域には入れてございません。そこら辺については、今、区のほうでつくっております新・水とみどりのネットワーク構想の中で、海に面した区ですから。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"きょうは一番最初の部分なので、これについてはある程度理解をしましたが、特にＣ２というのは、完全に今現在の地権者の方々の部分だと思うんですね。ここら辺のところは、しっかりよく打ち合わせが、もちろんできていると思うんですけれども、Ｃ２というところが一番ポイントかなと、今の段階では思っておりますので、ぜひそこら辺をお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"三上委員","kind":"質問・要望","question":"そこに五反田保育園というのがあるわけですけれども、現実に都営住宅というのは、耐久年度的に、耐震的な部分はどういう評価になっているんでしょうか。それについて、また品川区としてはどう考えていかれるのか、そこだけ、ちょっとお考えを聞かせていただきたい。","respondent":"齋藤住宅課長","answer":"東五反田二丁目アパートは、昭和４８年に供用を開始しておりまして、２０８戸。東京都の基本的な改築の考え方ですけれども、全部で３,０００棟、２６万戸あります。昭和３０年代のものは６万戸ぐらいで、それは改築をする。","id":"exchange-020"},{"speaker":"三上委員","kind":"質問","question":"せっかく、隣接したところの計画が進み始めているわけでしょう。そういうことにあって、耐震診断をまずきちっとやることが大事なのかわからないですけれども、そこらあたりの見極めをまずやってからじゃないと話は進まないわけですから、それは早急にやるように、区のほうから申し入れをやっていったらどうかと思うんですけれども、いかがなものでしょうか。","respondent":"岩田まちづくり事業部長","answer":"ただ、最終的に、築年度がそんなに古くないということもあって、残念ながら、住宅局は開発には乗れないという回答があったもので、やむを得ずに、ここの街区との共同はやめて、現在の街区構成で再開発計画を進めたというふうに聞いております。","id":"exchange-021"},{"speaker":"三上委員","kind":"質問・要望","question":"これまでのいろいろないきさつはあるかもしれませんけれども、東京都も少し財政がよくなってきているという話の中で、こういう話になってきているんであればということで、計画変更というのもあり得るかもわからないので、改めて、いかがでしょうかという働きかけをされてもいいんじゃないかと思いますので、機会があれば、そういうふうにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"一番最初の質問の経過の中で、Ｆのところというのは、ここに出されている事業計画の中では、Ｆはないわけですが、事業者との計画の関連というか、それはどうなのか、全体像がちょっと見えないので、そこを教えてください。","respondent":"青木都市開発課長","answer":"北品川五丁目に関するご質問にお答えいたします。Ｆ地区が、当初、検討区域から外れていたものが、いつ入ったのかというご質問ですけれども、もともとＦ地区については開発の予定はありません。","id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"そうすると、２番目のＧ地区の件については、整備計画がまだできていないけれども、基本的には、敷地面積の最低限度とか、そういうのはどこかと一緒になるんじゃないかなと思うんですけれども。","respondent":"青木都市開発課長","answer":"もし、同様に開発を進めたいのであれば、Ｇ地区についてのみ地区整備計画を定めるという都市計画変更を行うことによって、何らかの新たな規制なり、緩和なりのルールが定まることになります。現段階では、それを用意していないということです。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"これによると、高さ規制というのは、法の仕組みがちょっと難しいので、ここではわからないんですけれども、高さの制限というのは、もう事業者のほうで、都市再生特別地区の変更というところで、建ぺい率とか、容積率などがあって、これはもう、ここには書かれていないですけれども、これがもう通っているということになるんですか。","respondent":"青木都市開発課長","answer":"委員、ご指摘のとおり、都市再生特別地区の規制の中で建物の最高の高さを定めてありますので、そちらの規制がかかるということで、今回の地区計画に関する条例には記載がないものです。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"先日来、住民の方たちは、御殿山小学校の南に当たるところでは１４３ｍ、また、ここは高台になっているわけですから、相当高くなっているところで、ほんとうにまちづくりとして問題にならないのかということが、やっぱりすごく不安に思う部分です。区民の感覚として、そういうことが出た場合には。","respondent":"青木都市開発課長","answer":"紛争等予防条例等は、今回の規模になると、これは東京都の所管になるかと思うんですけれども、それについては、調停やあっ旋という制度はありますので、ご意見等の調整は、そういった場を活用するものと考えております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"格差と貧困で区民の暮らしがほんとうに苦しい中で、今、急いでやることは暮らしのほうに切り替えることだと思いますので、やっぱり区民の暮らしに回すべきだし、実際に再開発ででき上がったマンションも、５,０００万円、７,０００万円では、とても庶民には手の届かないものになるわけですから、そういう政策というのは間違っていると思うので、第７２号議案には反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"井上委員","kind":"意見","question":"都市計画審議会のところでも審議があった部分で言うと、法の手続が、都市計画審議会が機能しているという、それが前提にあって、品川区がそうかというと、そうではないと思っています。それから、こういった高層を中心にしたまちづくりについて、考え直していく姿勢が必要であるというふうに思いますので、この条例には反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"基礎的なことで聞きたいんですが、認定（その１）と、認定（その２）ですが、一部は削っちゃっているところもあるんですが、同じ区間の場合に、やはり１回取り消して、そしてまた再度認定するような形にしないといけないと思うんですが、そこだけちょっと。","respondent":"松代管理工事課長","answer":"そういった場合の、路線の認定、区域決定および供用開始の取り扱いについてというので、国土交通省道路法に基づく通知というのを踏まえまして、一たん廃止をしまして、新たにここの区間ということで。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっとご説明いただきたいのは、目黒川に接している部分の道路を廃止して、さらに親水護岸整備の工事を行って、その後にある親水公園、それからちょっと離れますけれども、親水広場というんですか、この三つの関係がもうひとつよくわからなかったので、もう一度ご説明いただきたいと思います。","respondent":"松代管理工事課長","answer":"ただ、機能としては、車は通れませんが公園の中の歩行者の通路的な部分は、今後、計画されると聞いておりますので、歩行者の通路としての機能は残りますが、公園になった場合、本来の道路としての機能はないということから廃止をするものです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"開発に伴って親水公園をつくるわけですけれども、なぜ、開発に伴って親水公園をつくることと、今ある公道を廃止をしてまで護岸整備を進めて、いわゆる一体化するという考えでよろしいのか、そこがよくわからないので、もう一度ご説明いただきたいと思います。それから、今回、道路をとることによって、再開発本体の容積率というのに、何か影響してくるのか。そこもちょっとご説明ください。","respondent":"青木都市開発課長","answer":"親水公園の位置づけですけれども、品川区が進めておりますまちづくりの基本的な方針として、新・水とみどりのネットワークを整備していくということで、かつ、大崎駅周辺地域の都市再生緊急整備地域の開発に当たっては。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜそれを外して公園の一部にするということなんですか。これとは別の話で、地元から公園をつくってほしいということがあると、公共施設の適正配置だとかといういろいろな話で、近くに公園があるとなかなか認められないという話がある中で、すぐ近くに公園があるのに、またここにつくるというのも、なぜわざわざある公道を外してまでつくるのか、そこがよくわからないので、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"ここでは、全体の計画の中で、東五反田地区における幹線道路の整備ということで、道路のネットワークという点で計画がなされています。これは東五反田地区方針計画ということで、平成４年に建設大臣の承認を得てつくられているものです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"るるお話がありましたが、結局は、全体図を見れば、右側にある三井不動産の所有で第２地区再開発、親水公園の裏側にある野村不動産所有の、１００ｍ級のビル建設、それぞれのマンションのクオリティを高めるために、手前に公園をやっているようにしか思えないんです。なぜ、開発事業者のクオリティを上げるための工事になるのか。","respondent":"岩田まちづくり事業部長","answer":"これは、十四、五年前に国と東京都と品川区でつくりました城南３河川、河川環境管理基本計画の中で、将来の目黒川の環境美化のためには、水質改善もさることながら、護岸の形状等についても、将来的にはこういうふうにしましょうと。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"実際に、近隣の方々は、野村不動産が進めている裏側のほうで、日影の問題で、今、住民の運動も起きておりますけれども、話し合いに応じる姿勢も、態度も非常にひどいものだという話も伺っている中で、区がこっちでグレードを上げるといいますか、そういうのはほんとうにおかしな話だ、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"それとも、工事が進む中で、いつごろからとかという見通しがあれば、教えてください。公園が完成すれば、また通れるようになるというご説明だったんですけれども、公園ができるのは、全体の再開発の最後の時期と聞いていますので、そうすると、実際に廃止される、要は新たに認定されずに廃止になるこの区間は、いつからいつまで通れない状態なのか。","respondent":"青木都市開発課長、松代管理工事課長","answer":"全体の公園、護岸一体としてのオープンは、委員、ご指摘のとおり、再開発組合の施工がすべて完了した段階でということになりますので、全体のオープンは平成２２年に入ってからを予定しております。工事等のスケジュールがまた細かなところで、今後、きちんと詰められるでしょうから、そういったものにあわせて、こちらのほうもきちんと指導をして、歩行者の通行等に支障がないような形で、今後詰めていきたいと考えております。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"廃道になっても、当分の間はまだ歩行者が通ることができると。今は車両も通れる状態だと思うんですけれども、車両を含めて通れる状態なのか、どうか、そこのところ。それから、護岸整備が平成２１年ですか、そのころなんでしょうかね、実際に通れるのは。ごめんなさい、ちょっとわからなかったものですから、教えてください。","respondent":"岩田まちづくり事業部長","answer":"ただ、物理的に通しても、１週間とか、３日とか、とめるということはあり得るかもしれませんけれども、ずっと引き続いて、歩行者、自転車までとめるということは、そういうことをしないような工事計画を立てるというのは常識ですので。","id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"基本的には、歩行者、自転車については、工事の進捗にかかわらず通行可能であると。車両の部分は、いかがでしょうか。","respondent":"松代管理工事課長","answer":"基本的にすぐに工事の準備等に入りますので、車両は通れなくなると考えています。ただ、今、まちづくり事業部長も申し上げましたように、歩行者、自転車等は必ず通れるような歩行者帯というのは設けながら、工事を進めると考えております。","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"要するに、当面は迂回というか、そのまま通れなくなる。そうすると、再開発が終わるまでの迂回路というのはどういうことになるんですか。","respondent":"松代管理工事課長","answer":"現道の前に目黒川の護岸がありますけれども、護岸が内陸側に移ってまいります。ですから、当然、内陸側に移ってくる護岸工事をしますので、今後、施工計画等に基づいて、歩行者空間なども十分に詰めていきたいと思うんです。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、このあたりの内陸部分の車の流れというのは、やっぱり変わってくるのかなと思います。車が絶対多いところではないですけれども、そこのところ入っているところですので、うまくさばいていかないと、子どもたちの通り道なので、そこら辺の車両の予測ですとか、あるいは、場所によっては交通整理員を置くとか、そういったことはお考えでしょうか。","respondent":"松代管理工事課長、青木都市開発課長","answer":"しかしながら、今まで真っ直ぐに来れたものが来れないということで通行等に支障があろうかと思いますので、そういった場合には、表示、看板、もしくは必要に応じては、通行整理員といったものを、工事の進捗に合わせて配置をしながら。再開発事業、あるいは地区計画を定めるに当たりまして、現道廃止について検討した際の交通量調査のデータがございまして、平成１５年段階のちょっと古い資料ではありますけれども、五反田南公園のほうから、今回。","id":"exchange-039"},{"speaker":"阿部委員","kind":"質問・要望","question":"このあたりは角が直角ではなくて鋭角になっていて見通しがあまりよくないということもありますので、そういった意味では、先ほどもご答弁の中にもありましたけれども、様子を見ながら、危ないところがないように、ぜひきめ細かな対応をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここも視察してきましたけれども、直線の私道をＬ字の公道にするわけですけれども、近隣に接している方の合意の状況はどうなのかというのが１点です。それからもう１点、以前から疑問だったんですけれども、Ｌ字の内側というんですか、右上というんですか、ここだけなぜ開発のエリアから外れているのか、どういう計画があったのか、ちょっと教えていただきたいと思います。","respondent":"青木都市開発課長","answer":"ご賛成いただいているかどうかという、まず１点目。ここがＬ字型の道路となることについては、区民の方々のご理解をいただいております。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"近隣の方の理解を得られているということで、私道が公道になるわけですから、どういう形の合意といいますか、ちょっと合意の仕組みをもう少し詳しく教えていただきたいと思います。それから、容積率は動かないということですけれども、ぐるっと公道に囲まれると変わるんじゃないのかなと思っておりまして、もう少し詳しく教えていただきたいと思います。","respondent":"岩田まちづくり事業部長、青木都市開発課長","answer":"私道の土地を持っている方は当然のことながら、寄付をしていただく、あるいは、無償使用承諾をしていただくわけですから、当然、１人でも反対したら、それはできません。開発の容積率について、詳しく教えてくださいというお話ですけれども、これは既に、区の地区計画を定めるに当たって委員会でご報告をさせていただいて、ご説明しています。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"いずれも、この議案は悩んでいる部分があるんですよね。もう一つ伺いたいのが、近隣の方に伺いましたら、横が６ｍですよね、長いほうの幅は４ｍだと。右側に住まわれている方がいらっしゃるんですけれども、その方の１人に伺ったら、以前、野村不動産の開発事業者のほうから、無償で２ｍくれという話があったそうなんです。","respondent":"青木都市開発課長","answer":"その地区計画については、重複しますけれども、都市計画法の第１６条の説明会、あるいは第１７条の縦覧手続などを経て、区民の皆様にもご理解いただいているものです。もちろん、地元の方にもご理解いただいているものです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"右手も左手も、片方は１００ｍ、片方は１４３ｍですか、まさにそのすき間にあるわけで、ご商売されている方も、住まわれている方もほんとうに困るという話を伺ってきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"この部分で言うと、両側の人たちに私道としての権利があるのか。先ほどおっしゃった、旅館なんかがあった中で、片方の方たちでなくて、両方の敷地の方たちの合意で、一方は再開発のエリアなので、そこのところがどうかということ。それから、４ｍだと一方通行か、双方通行なのか、最終的にどういう交通の流れになるんですか。","respondent":"松代管理工事課長","answer":"下のほうに行きまして、右側の方が６ｍの現道です。そうすると、今後の通行形態ですけれども、こちらは双方通行になる予定です。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"左の２ｍというのが、道路となるんですか。その後、今、この計画で、区道としてここだけを認定をし、さらにその後にもう一度、６ｍにしたときに、認定をし直すということになるんでしょうか。","respondent":"松代管理工事課長","answer":"それが将来、こちら側の開発、もしくは合意形成がとれるとなれば、その２ｍの部分は区道として供出されるということであれば、認定された路線の中の幅員が４ｍから６ｍになると、そのことによって、区道として管理をするといった形になるものです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"八潮団地再生事業の検討業務委託についてお伺いしたいんですけれども、事項別明細の中で、都市計画変更手続に向けた資料作成とされているんですけれども、もう少し具体的に、どのようなことを考えているのか、ご説明いただきたいと思います。それから、八潮地域の問題ですけれども、住民参加の問題をどのように受けているのか、あわせてご説明ください。","respondent":"青木都市開発課長","answer":"予定では、住民の方々の意見把握の手法として、場合によっては八潮だよりという地元の情報手段を使って、あるいはアンケートなども視野に入れて、住民の意見を把握してまいります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"一団地という住宅施設、都市計画を廃止するときは、次の計画は何でもいいというわけではなくて、街づくり特別委員会の議事録を見せていただいたんですけれども、国土交通省の指針で、引き続き良好な住宅環境の確保が必要なんだという説明がありましたけれども、そのことと、学校と施設の部分の規制を変更するというんですか。どういう手法を考えているのか、もう少しご説明いただきたいと思います。","respondent":"青木都市開発課長","answer":"いくら何でも、つくるときには都合がよかった制度かもしれないけれども、団地を運営していく、あるいは、必要に応じてつくりかえていくという時代になってくると、いかにも不都合な制度ですので、これを廃止した上で、ご案内のとおり。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、学校のところだけこうしましょうとなっても、全体の一団地計画の変更の中で整合性のあるものになるのか、それとも全く、理屈上は違うものになることだってあり得るわけですから、その辺をどんなふうに考えているのか、教えていただきたいんです。","respondent":"青木都市開発課長","answer":"Ｂ案があって、都市計画が進んでいくというご意見はごもっともではありますけれども、現在のところ、Ｂ案が何であるかということを検討している最中でございまして、一方で、都市計画の手続には、東京都の審議会の日程であるとか、都の所管部局との調整、あるいは、住宅権利者。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"現段階から始めないと間に合わないというところが、よくわからないんです。今なぜ、地域の中で、どういう八潮の活性化を図るのかという話し合いが進んでいる中で、いろいろなご意見があって、今、いろいろ意見を出し合っているところですよね。簡単に言えば、今なぜ変更の手続を始めなければいけないのかというところが、どうしてもよくわからないところがありますので、そこら辺について、教えてください。","respondent":"岩田まちづくり事業部長","answer":"あわせて、先ほど、都市開発課長が言いましたけれども、連合自治会で募集して、地域の方で検討委員会がつくられておりますので、失礼ですけれども、ほんとうに普通の素人の方たちですから、これが欲しい、あれが欲しいという意見があれば、この委託先をつかって。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ地域の方々の合意や、また住民参加を貫いていただきたいと考えています。全く別の点で１つ伺いたかったのが、かつて八潮住宅の上に羽田空港行きの飛行機が飛んでおりまして、今コースが変更してあれですけれども、航空法の関係なんですかね、高さの規制が別の要因として定められているという話を聞いたんです。ちょっとその辺の法律のことが僕わからないので、教えていただけますか。","respondent":"阿部都市計画課長","answer":"ただ、私も、その結果、高さがどうなっているか、そこまでは把握してございませんので、わかり次第委員に連絡するようにいたします。多分変わってないとは思います。ただ、その辺、詳細は承知しておりませんので、また委員のほうにお伝えしていきたいと思います。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"それで、法律上定められている高さが、変な意味、ぐんと変わったりしたらまたそれで問題もありますし、大体今のまま、今の羽田空港の飛行機のラインでも今のままだというのであれば、その中の計画になるし、そこは大事な点だと思いますので、ぜひ報告していただきたいと思っています。","respondent":"阿部都市計画課長","answer":"見方によってはかなり近いところを通る場合も現在ありますので、多分、今申し上げましたけれども、高さの制限は変わっていないとは思います。","id":"exchange-052"},{"speaker":"阿部委員","kind":"質問・要望","question":"教えていただきたいんですけれども、委託、例えば工事委託というとイメージがわくんですけれども、検討業務の委託というのはどのような内容を実際委託するのか、だれに対してまず委託をするのか。これは、建設委員会から離れるのかもしれないんですけれども、こういうのは入札とかで決まっていくものなのでしょうか。","respondent":"青木都市開発課長","answer":"ご案内のとおり、１,５００万円で何をやるかということですけれども、もう一回繰り返しますと、まず調査として基礎的な調査、上位計画等を調べていくということ、あと現場での権利関係も再度確認するということ、あとできれば交通量、車両、歩行者ともに現時点の調査も。","id":"exchange-053"},{"speaker":"阿部委員","kind":"質問","question":"大分イメージできました。半年間でほぼそれだけの内容を、東京都への資料をつくるというところまで行く予定ということは、逆に言えば、来年度、平成２０年度以降は特にその種の検討業務の委託というのも終わっている状態になっているということになのでしょうか。それとも、また引き続き別の検討業務をさらに委託するというご予定なのでしょうか。","respondent":"青木都市開発課長","answer":"それは現段階での地元の検討、あるいは庁内での課題抽出の状況によって、平成２０年度以降高まってくると考えています。","id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"ということは、これはもう業務委託契約は終わっているということでしょうか。","respondent":"青木都市開発課長","answer":"申しわけございません、順番が前後しておりますけれども、契約は成立しております。で、既に業務を着手しております。","id":"exchange-055"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つかお聞きをしたいと思います。先ほどちょっとお話をしました。１つ、先ほど来、八潮の話をするとなると、流用で９カ月。構わない。それは全然構わないけれども、急いでやったほうがいいと思うけれども、１点、どっちみち１団地から地区計画に変えていくというのはわかっていた。どういうふうになっているかというのもわかっている。答弁は要らないです。それをわかっていれば、その２つ、教えてください。","respondent":"伊勢住環境整備担当課長、松代管理工事課長","answer":"ただ、国および東京都に対して早期の補助金システムについて要望したところ、来年度じゃなくて今年度それがつくということで、内示変更等により交付が見込まれるため、今回の補正予算を組んだものです。このことを踏まえまして、それまでにできる準備をしております。議決された後すぐに契約手続に入りまして、それで契約、または実施と、こういう形で来年３月末にすべて完成するように進めたいと、このように考えてあります。","id":"exchange-056"},{"speaker":"井上委員","kind":"提案","question":"ちょっと中身に入ってしまうんですけれども、踏み切りについてちょっと、こういう踏み切りの拡幅についても区民の方から要望があり、まちづくり事業部にも提案しているところなんですけれども、踏み切りの拡幅の工事というのはどういう内容なのか、説明していただけますか。","respondent":"松代管理工事課長","answer":"ここにありますように、大崎広小路２号踏切などはこの拡幅の対象ですけれども、そういったものを国の定める基準に沿うものの踏み切りをまずやりたいということで、今回、当初は５カ所を予定しておったんですが、その後都と国との交渉をさらに進めて。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問・要望","question":"荏原町の駅のところの踏み切りなんかも、木がカクカクになっていて、スペースとしてはあるんだけれども、１段、１段下りなきゃいけなかったり、車いすが通れなかったり、ベビーカーも通れないという声があって、何とかしてほしいということで、カラー舗装も有効かもしれませんが、歩道確保の、歩く人のスペース確保というところが本当に皆さん要望されていたので、ここはぜひ、国のお金だけではなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-03","title":"平成１９年請願第２２号 首都高速中央環状品川線事業の五反田換気所及び出入口に関する請願","agenda":"平成１９年請願第２２号 首都高速中央環状品川線事業の五反田換気所及び出入口に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"賛成をしているんだけれども、排気塔もできるのはしようがないだろうと、それは思っていらっしゃるし、東京都側が今度提案をされたのは、私も伺いましたが、最初の提案よりは大分細くなったりもしているという。しかしながら、この連絡会の方々は自分たちでも、ここでも書いてあるけれども、排気塔をどうしたらいいかという全国公募をしたり、いろいろ努力はされている部分は非常にある。","respondent":"阿部都市計画課長","answer":"この前、この建設委員会の中でもございましたけれども、インフォメーションセンターも土・日開いていないじゃないかという話がありまして、今月から土曜日は１回、日曜日は１回ですけれども、開いて。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問","question":"必ずどこかに排気塔、その排気塔のでかいファンで、こういう今の代替案というのかな、公募案というのかな、それもお話を伺いましたけれども、そういうのも含めて、ぜひいろいろな話をしていきたいんだというのが本来のその方々の話し合いだと、考え方だと思いますので、私どもは非常に趣旨は理解はできると思って、この部分で署名をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、例えばインフォメーションセンターの件も、これも１つ前進だと思います。これは単に一例で申し上げているんですけれども、そういったところの積み重ねの部分が非常に大きいのではないかと思うんですけれども、例えばこの、２番のデータ公開などについて、区のできることというのはもうちょっとないんでしょうか。","respondent":"阿部都市計画課長","answer":"先ほど説明して、ちょっと言葉足らずで申しわけございませんけれども、手続的には東京都が公表するですけれども、私どもも、新宿線は首都高速道路株式会社が事業者でやっているところですけれども、私どものほうから、今回のこの請願が出されましたので。","id":"exchange-061"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういうことだと思います。そこら辺を、ずっと言い続けていることですけれども、やはり説明、相手が納得する説明というのは必要でもあるし、この請願で最も求められていることじゃないかと、最後は意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"この請願の要旨、その他を見ますと、合同連絡会の方々は現在の計画に対して納得していない、また都の説明に対しても不十分であるということが書かれていますけれども、私も全くそのとおりだと感じております。１つ伺いたいのは、１－７のところで書いてあります大気汚染についてです。改めて、大気汚染がどうして改善するとおっしゃるのか、ご説明いただきたいと思います。","respondent":"阿部都市計画課長","answer":"それに伴って、一般街路の渋滞の箇所、品川線については山手通りでしょうけれども、そういうこともありまして、渋滞が解消されることによりまして、環境改善が図られるというふうに東京都等も言っておりますし、私どももそのように認識している。","id":"exchange-063"},{"speaker":"中塚委員","kind":"提案","question":"もう一つ伺いたいのは、地域の方々が提案されている４つのアイデア、どういうものなのか僕もわからないので、月刊『おとなりさん』の中にいろいろな公募された提案が、代案というんですか、載せられておりますけれども、区はこの代案については何か検討というか、研究はされたのか。どういうお考えがあるのか、ちょっとお聞かせいただけますか。","respondent":"阿部都市計画課長","answer":"これも本会議でご答弁させていただきましたけれども、これはあくまでも事業者は、品川線につきましては東京都と首都高速道路株式会社ですので、私どもは事業者に対して、公募案について詳細な検討を加えていただいて。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問","question":"今も元気ですけれども、いらっしゃるんです。それで発作が起きる。本当に苦しそう。今でも覚えているんです。やはりこういう子、ぜんそく患者が、時には、将来仕事に就けなかったり、そういった方もいらっしゃるわけですから、生活そのものが破壊されるわけです。こういうぜんそくの苦しみをしっかり受けとめていただいて、環境改善に向けたことが必要ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"説明責任とかそういうところでとっているところでも、あれだけ入って、区民の方たちの要望ということでは積極的に対応していただきたいと思うんですが、ずっと今までも言い続けているんですが、この請願でも、子や孫に対して悪くなる環境を残したくないという、そういう思いで言えば、環境評価があったとしても、前の公聴会のようなところでも、車の少ない水曜日に調査をしたとか、本当にそれが。","respondent":"阿部都市計画課長","answer":"東京都はそれに対して、供用開始前の大気調査を行いまして、必要であれば技術的動向を見ながらつけ加えていくということも言っておりますし、現に換気所についてはそういう最新技術も入るような大きさのものになると聞いてあります。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"低いというふうに言われているという評価に対する根拠もわからないというところでは、それを証明する手立てをとにかくやってもらえないだろうかというようなことは当然なことだと思うし、悪化した後に被害を受けるのはそこに住んでいる人とか、本当に、ぜんそくだったら１回発病してしまえば、その後ずっと継続して被害を受けていくわけ。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論は出したほうがいいと思います。それで、私どもの感覚では、先ほども言いましたけれども、皆さんの趣旨は非常にわかるので、私は趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"三上委員","kind":"質問・要望","question":"この問題については、私ども党としても古くからずっと取り組んできた問題でありまして、私が昭和６２年に議会に出たそれ以前から、もう既にこの中央高速環状線の問題については取り組んでいく必要があるという、以来２０年の取り組みをしてきております。今いろいろな問題が叫ばれている中にあって、人の健康ということについては一番大事になる。本日のところ、この請願、私は趣旨採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"きょう結論を出すということと、あと、態度につきましては、ここに書かれているように、標語の一つが、私たちは子や孫に大気汚染を残したくありませんと、五反田周辺も含めて今でも大気汚染の中でぜんそくで苦しんでいる方々がいらっしゃる中で、もうこれ以上はごめんだという請願者の趣旨は痛いほど理解できますので、態度といたしましては趣旨採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"阿部委員","kind":"意見","question":"私もここの品川区、地元が大崎ということで、決してこれは他人事でないといいますか、環境に影響があるかもしれないこのエリアにおりますので、ある意味自分も当事者だと思っています。結論を出すという形でお願いしたいと思います。この請願のことにつきましては理解できることですので、趣旨採択という形でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"品川区は今後も住民の立場に立って、東京都や事業者である首都高速株式会社に対しまして、住民が安心するように、今後も要請があれば住民の話し合いに応じるように、東京都や首都高速株式会社に今後も、長い期間ですが、話し合いに応じるように今後も引き続き要請してほしいということで、意見を述べします。今回に関しては結論を出すということで、趣旨採択ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-04","title":"平成１９年請願第２４号 目黒線立体交差事業に伴う洗足架道橋閉鎖のため設置された代替道路の使用方法および改修についての請願","agenda":"平成１９年請願第２４号 目黒線立体交差事業に伴う洗足架道橋閉鎖のため設置された代替道路の使用方法および改修についての請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ちょっとお伺いしたいのは、代替道路の台数ですけれども、以前の調査だと平均で言えば、大体自動車が２０台、バイクが十数台、１４台、１６台、この前やったら車が６３台、バイク４０台、約１.５倍に増えているというお話ですけれども、増えた理由はどのように分析をされているのかお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"今まで架道橋の下を通っていた分が５００台以上あったわけですから、そういうようなものがあそこが使えなければ違うルートを回ってくるです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"確かにああいう形の道路というのはあまりほかに見たことありませんし、しかも下り坂の左カーブですから、安全性がやはり疑問だなとは思います。それともう一つ伺いたいんですけれども、説明にはなかったんですけれども、交通網の中で一方通行が、要は双方向化への変更とありますけれども、この変更はなぜ行ったのか教えていただけますか。","respondent":"浜脇街路事業担当課長","answer":"先ほどのパネルの中で説明いたしましたけれども、結局、今、これまで５００台ぐらいが品川区から目黒区側に抜けるということがございました。","id":"exchange-074"},{"speaker":"中塚委員","kind":"意見","question":"この図で見ますと、この緑のところの台数を抑えるために、この赤いところの一方通行を解除したという話ですけれども、結局代替道路の台数が増えているのは、その緑のほうから代替道路に向かって、いわゆる電車の反対側に移動されている方が多い。それで知られると当然、便利だなということで、増えているのかなと思うんです。最後は意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"そもそもこの洗足架道橋を閉鎖をして、工事をしますよというときに、それを認めていただくような何か代案を考えてつくりましたということで、なおかつさらにつくり上げたものは使っていこうというのは行政としては当然だと思いますけれども、しかし、先ほど現地に行って、あの時間、２０分ぐらいだったでしょうか、１台も車は通っていませんでしたので、本当にあの道路が必要なのかどうなのかということを。","respondent":"浜脇街路事業担当課長","answer":"この道路は、今もご説明したとおり、閉鎖に伴いまして最大限にこの方々の通行と、あるいは救急車両といったものを確保するということが重大な使命になっておりまして、それはあらゆるこういった利便性といいますか、そういったものを追求したときに。","id":"exchange-076"},{"speaker":"阿部委員","kind":"質問","question":"前回の建設委員会でも視察させていただいて、１点、歩道橋のことだけは気になったんですけれども、改めて今回現地に行ってきまして、あの地域一角のためにものすごく装備がされている状態、本当に小さな住宅街の一角がまるでよろいをまとったような、ちょっと不思議な風景になっているなということを感じたんですけれども、これまでの間に、あの一連の装備と言ったらいいんでしょうか。","respondent":"浜脇街路事業担当課長","answer":"しかし、私どもとすればそういった、失礼ですけれども、なるべく一般仕様に、使えるものについては一般仕様でやろうということで、工費については東京都はじめ４者で拠出しているものですから、なるべく、そういった意味では。","id":"exchange-077"},{"speaker":"阿部委員","kind":"質問・要望","question":"それと、この道路の問題、先ほど言われましたけれども、最初の最初はやはりここが道路、通行できなくなる状態にはしないでほしいというのがたしか地元の方々からのご意見として、今回請願を出されている方とイコールで結ばれるかどうかは私はわかりませんけれども、少なくともこの地域、このエリアの方々から要望として出されたといういきさつがあったのでないかという、ちょっとその辺、確認させてください。","respondent":"浜脇街路事業担当課長","answer":"当然今まで洗足架道橋を使っていると、立体化されておりましたから、そういったものが、立体化のために自分達だけが犠牲になるということは大反対ということで、広範な反対運動がありまして、その中で私どもとしては話し合いの中で。","id":"exchange-078"},{"speaker":"阿部委員","kind":"意見","question":"そうすると、やはり、要するに道路近隣の方のご意向というのもあると思いますけれども、別に、道路というのはつながっていて道路であって、それぞれの地域の方が、このうちの地域の道路はうちの地域の人以外使っちゃ困るとはこの方もおっしゃっていないんですけれども、やはり地域以外の方もそれぞれに使うためにあるからこそ道路であるということもやはり踏まえなければいけないだろうなと、すみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう一度改めてお聞きします。これは車も含めて。周りへの影響をどう考えるんだということがすごく話になった。間違えていたら教えてね。それでまた大騒ぎをしたんだけれども、それから以降、着工するまでに何度も我々もそこの近隣の方々から直接的にお話をいただいたり、話があったけれども、一つひとつクリアをしていこうということで、いろいろな要望を伺いながら、何度も何度も書き直して変わってきた。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部長","answer":"それから都に対しても同じような行動をして、回答をもらっている。そういうことで、今でも説明していますし、口頭でやっているんですが、なかなかいいと、私どもの説明について、理解したといってくれない状況ではあります。ですから、今うちの代替道路や、目黒区方の相互交通に変えたところなんかに入ってくるのは、実はこのあたりに住んでいる、あるいはこのあたりの住居に用事がある車両、こういったものが入ってきているということで。","id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"ですから、ここのところでは、皆さんのこの中の人たちの生活道路として、この計画の中でも、前回の請願のときにも都市計画決定がされているのでという協議の場が持てなかったとか、いろいろ長い歴史の中でそういう状況にはあると思いますけれども、今の状況で言えば１日平均２２台、２０台前後ということであれば、この道路をずっと使い続ける意味が本当にあるのかということも含めて、もう少し。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部長","answer":"それが、現実的には今、逆に私どもから見れば、この台数は６３台、代替道路に入っているとすれば、６３台しか行かないんですから、５４４台はもう来ていないわけですから、これについては違った形で安全策がとれるということですので。これが閉鎖されれば、そこへ行ったら行くところがないですから、別の便利な道を通過交通は探しますから、そちらへ散るだろうと普通には考えていましたけれども。","id":"exchange-081"},{"speaker":"三上委員","kind":"確認","question":"１つ、まず、確認したいのは、この請願文というのは、項目については前回と同じですか、それとも違うようになっていますか。","respondent":"浜脇街路事業担当課長","answer":"先のものは騒音であったり、水たまりであったりしていたものが、こちらの今回の場合は、この代替道路、当然代替道路についても一部ありましたけれども、今回は代替道路とこの道路について絞っている部分が、前回２月に請願したときとは若干絞れてお話が出ているです。","id":"exchange-082"},{"speaker":"三上委員","kind":"質問","question":"絞れてきたということは、請願に通すなという話と、通っている現実を考えて、ああだよ、こうだよ、改善してくれというのと両方入っていたということでの、問題点としては不都合が生じたというふうに理解していいのでしょうか。","respondent":"浜脇街路事業担当課長","answer":"あの当時から見れば、私どもが区民の声にも回答しているんですが、その回答について答えてある部分については理解をしていただいて、残っているのがこういう話かなということで、少し、２月ごろから見れば、請願項目は少し減ったといいますか。","id":"exchange-083"},{"speaker":"三上委員","kind":"質問","question":"そうすると、請願項目の１つ目として、「特別な場合を除き歩道として使用し」という、こういうことになると、遮断しないために誤って通る車というのは必ずありますよね。そこらあたりというのは、交通管理者的な考え方からいったら、判断というのはどうなるんですか。","respondent":"浜脇街路事業担当課長、松嶋交通安全担当課長","answer":"やはり架道橋が閉鎖されて、あの位置でもって閉鎖されて、相互に交通できないということはやはり交通ネットワークとか、交通管理上あったほうがいいというご意見は、当然ありますから、私どもとすればつくったほうがいいということで。したがいまして、この場所を通行させないために、そういった公安委員会の規制をとった場合に、じゃ、どうするかということであれば、部分的な対応も時には必要かと、そういうふうに考えます。","id":"exchange-084"},{"speaker":"三上委員","kind":"意見","question":"もう一つ聞かせてもらいたいんですが、特に、「生活道路」という言葉がさっきから出てくるんだけれども、生活道路というのはそこに住んでいる方たちが利用する形だけを生活道路と表現するのかどうか。","respondent":"岩田まちづくり事業部長","answer":"したがって、税で管理されているですので、ここの場合は狭いですけれども、一応４ｍの幅員が確保されておりますので、区内には４ｍ道路はいっぱいございまして、相互交通がいっぱいある中で、ここは一方通行まで変更しておりますので、そういう面で安全性は十分確保されているし。","id":"exchange-085"},{"speaker":"三上委員","kind":"質問","question":"だけれども、最終的にはその整理を行って、角度がむしろ緩やかにするようにしたと、そういうことの説明で間違いないとするならば、これは元の高さ以下には戻っているということで理解していいわけなんですか。","respondent":"浜脇街路事業担当課長","answer":"資料２のときにご説明しましたように、一時期、けたを切るための鋼材が若干、６cmほど高くなって、それにあわせて舗装したときがあったようですが、これについては、この鋼材を取ったときに元の地面にならしたということで、なおかつ私どもで、先ほど申しましたように。","id":"exchange-086"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、この請願を求めるというのは、これはもう願意としては成立していると判断していいのか。","respondent":"浜脇街路事業担当課長","answer":"それについては警視庁と今後とも相談をしながら、やっていこうかなと考えています。","id":"exchange-087"},{"speaker":"三上委員","kind":"意見","question":"階段の件が出たから、私もそれは必要だなということは思います。そういう前提から考えたならば、私はむしろ、生活道路という考え方をするならば、それはそれなりの、やはり雨でも、雪でも、どういったときでも転ばないで少なくても歩ける方法論だけはきちんと整えておくほうがいいのかな。それは私も十分理解できる話だと、こういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほどもいろいろ、るる過去からの話も伺ったし、行政側の非常に、そういう意味ではしっかりと対応していただいて、本当に、私は、よくその部分は対応しているなと思うぐらい、住民の方に対し、２番のこともありますし、過去からの経緯もあるということも考えて、私は結論的には不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"三上委員","kind":"意見","question":"先ほども一部申し上げましたけれども、本日結論を出すということについては賛成します。態度といたしましては、１項目、２項目ともに、ある意味では願意に沿い難いということであるならば、これは不採択というふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"須貝委員","kind":"意見","question":"いろいろ話を聞いていまして、ここの道路は品川区の住民や、小山六丁目の人たちが行き来できる道路も私は必要ではないかなと感じます。できれば、一部の住民の方が交通事故等を心配されているということならば、ここの区間だけできるだけ安全対策を講じて欲しいなと思います。今回、結論を、長年やっているということで、結論を出すということで、私も同様に不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"井上委員","kind":"意見","question":"結論を出すということには賛成です。まだまだこの道路の安全性というのに地域の方たちが不安を持っている、また雨の日、雪の日というところも、これが解消されているというふうにはとても思えない。趣旨には賛同できますので、態度は趣旨採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"}]},{"id":"topic-05","title":"平成１９年請願第３３号 大井町駅東口改札口営業時間延長に関する請願","agenda":"平成１９年請願第３３号 大井町駅東口改札口営業時間延長に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"質問はあまりないんですが、今おっしゃったように、３月２日に来られて、４月１日から実施して、４月中旬行政側から話を伺いました。我々も署名する際にその経緯も聞きました。それで、ＪＲ東日本にも区長が出したんだけれども、それの返答がない。内容は書いてあるけれども、全面撤回。話し合いの場にも乗らないような状態だから、それはもう採択して、やるというぐらいの感じだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ質問ですけれども、もしわかればですけれども、ＪＲ東日本はなぜここを早く閉めちゃうのか。その理由はどのように把握されているのか、ちょっと説明していただきたい。","respondent":"阿部都市計画課長","answer":"それはＪＲ東日本も公益鉄道事業者ですけれども、民営会社の部分もありますので、そういう意味では経営努力を会社として求められていると。その一環として、こういう形というふうに理解しております。","id":"exchange-094"},{"speaker":"中塚委員","kind":"意見","question":"鉄道事業者として、本当に公共性の高い事業を行っている者として、結局利用者の利便性も考えない、また地域の方々の影響も考えない、こういうＪＲの姿勢というのは本当に許せないなと私も感じております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"三上委員","kind":"質問・要望","question":"なるべくならば、元に戻していただきたいという、これはもう地元の発展、利用者の利便性、いろいろ考えたならば、それは当然、元に戻していただきたいことを大前提とした上で、どうしたらいいか。そういう意味であっては継続する、それから採択する、そのどちらかしかないと思うので、態度については、本日出すということであれば採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"中塚委員","kind":"意見","question":"きょう結論を出すということと、態度は採択です。理由は、大井町東口改札口を短縮をするのは本当に全面撤回すべきだと思うからです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"},{"speaker":"阿部委員","kind":"意見","question":"私も、本日結論を出す。採択。やはり品川区としての意思というのをきちんと明確にあらわして、その上で交渉すべきと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"須貝委員","kind":"意見","question":"私も三上委員と同じです。強硬にやるとなれば態度も硬化する。それでもだめならば、それは、私は交渉が第一だと思います。だめならば、議会で強く採択してやるということも必要だと思うんですけれども、やはりまず交渉をできるだけ努力を、さらなる努力をお願いしたいと思います。今回結論を出すということなので、区民の利便性を考えたらいたしかたないというふうに思いますが、ちょっと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"私も、反対するものではないですけれども、やはり今区のほうから要望書を提出している中で、まだ回答が来ていないというところもありますので、皆さん、迷われている、判断する、しないというところでは同じなんです。区議会として当然であるというような主張でやるものでもないのかなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":84662,"voices":252}},{"id":"h19-20070925-9","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"文教委員会","time":"午前１０時０３分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","topics":[{"id":"topic-01","title":"第６３号議案 平成１９年度品川区一般会計補正予算のうち歳出の文教委員会所管分","agenda":"第６３号議案 平成１９年度品川区一般会計補正予算のうち歳出の文教委員会所管分","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"したがって、これについて強引に統合計画を推し進めていくという、急遽そういうふうにしていった背景というのを、改めてこの場でも伺っておきたいということと、それから、荏原第二中学校の改修工事というのも６６１万８,０００円計上されていますけれども、これも当初の計画にはなかったことですから、なぜこういう予算を計上しなくちゃいけないのかというところも説明がなかったので。","respondent":"古里学務課長、藤森小中一貫教育担当課長、市川庶務課長","answer":"これにつきましては、２月当初に統合の必要性について保護者の方にご説明申し上げ、その後るる協議をした結果、両校の保護者会において、６月６日。むしろ学校のほうとしましては、水泳指導は全身運動で非常に体力づくりにも効果的だということで。私のほうからプールのことに関連して、現行のプールを残すことを検討したらどうかということなんですけれども、検討はいたしました。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"しかし結果的にはこういう案になったということなんですけれども、そうしたら、児童・生徒の数にもよると思うんですけれども、しかし素人の私たちが考えても、２つのプールで夏の間実施していたプール指導が、１年生から９年生まで１つになるわけですから、とても入り込めないだろと思うので、それは日野学園のように通年を通してプール指導をやるという方向に変わっていくのかなと思うんですけれども。","respondent":"市川庶務課長、古里学務課長、藤森小中一貫教育担当課長","answer":"そういったことを踏まえながら、２１年４月からの新しい八潮地区の小中一貫校でのカリキュラムの編成にあたっては。６月ごろ、説明会としては最後になりましたけれども、その時点におきまして、区での負担を含めて検討をしますということで。例えば学校運営と教育条件の整備だとか、地域に開かれた学校のあり方だとか、あるいは新しいタイプの自立的な学校運営等。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"ここには、今おっしゃったような４つのテーマが書いてあって、今回のところは今お話があったように、学校運営と教育条件の整備というところでテーマを掲げてエントリーしたんだということなんだろうと思うんですけど、この研究タイトルが「品川区立小・中学校の学校規模の望ましいあり方と再配置のあり方の検討および統廃合の実施に伴う諸課題の検討」と書いてあるんですけど。","respondent":"古里学務課長","answer":"そういった意味での表現でございまして、この時点で予算要望といいますか、要するに研究開発をするにあたって、そのような表現、学事制度審議会が予定している検討事項を表現させていただいたというものです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"今、いみじくも学事制度審議会が出てきたし、適正規模、学校のあり方を定めるという表現だということで、なかなかはっきりとお答えになりませんけれども、それでは、ここに学務課のお書きになった事項別明細書もちょっと見ましたら、将来の制度改正を見据え、新しい教育システムの導入の可能性の検証を行う調査研究事業だと書いてあるんですけれども、将来の制度改正を見据えと。","respondent":"古里学務課長","answer":"先ほど申し上げたとおり、学事制度審議会で審議をしていただく事項は後ほどご報告申し上げる内容で設置をし、これから審議会の中でご審議をいただく内容ですから、それがどのような方向にということは私のほうから申し上げるべきではないということでございまして。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そうしますと、ちょっと聞き方を変えますけれども、調査研究事業として文部科学省の委託を受けようとした動機というのは何でしょうか。","respondent":"古里学務課長","answer":"先ほど小中一貫教育担当課長のほうから説明をしたとおり、この新教育システム開発プログラムという研究受託の事業の中には幾つかの事業がございまして、私どもが学事制度審議会を設置し、品川区のこれからの教育のあり方を検討するということも研究委託事業の内容でございました。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"私は非常にまともに姿勢を示そうとして議論していくべきだと、議会の意見を聞いていくべきだと思うんですね。こういう文教委員会にも報告もこの間しない中で、補正予算であえてこういうことを出して、聞いてみても改めてそこのこともはっきり言わないというのはどういうことなんですか。しっかり表明するべきだと思うんです。そこでいろいろ意見を聞くべきだと思うんですけれども。","respondent":"長田教育次長","answer":"今、手続の問題でいろいろご質問をいただきました。この学事制度審議会につきましては、区議会の一般質問等でも、今までもこれから検討していきますよ、あるいは区長の施政方針の中でも検討していきます、こういう表明を行いまして、この間、進めてきたわけです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"違うというお話ですけれども、私は教育委員会の議事録を読ませていただきましたけれども、教育委員会はこう言っているんですよ。議会や区民の意見をよく聞いて議論を尽くすべきだ、そういう発言が何回か出ています。どうなんですか。そういう発言はなかったですか。","respondent":"長田教育次長","answer":"ただ結論といたしましては、教育委員会の総意として、これから学校の適正規模、適正配置については検討していくということ、審議会をつくって検討していくということ、それから、審議会に対する諮問の内容、こういったものについてもご了解をいただいて進めてきたわけですから。","id":"exchange-007"},{"speaker":"南委員","kind":"提案","question":"確かに結論が出たことは私も読んで承知しました。後でそこのところは確認したいんですけれども、回答してください。つまり２月から２、３、４、５、６月、５カ月にわたってこの問題でずっと継続審議、修正提案して継続審議ということになって、ようやく６月２６日に了解するとなっているんですよ。１つのものをやっていこうとするのであれば、堂々とつまびらかにして意見を求めるべきですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"これを今、準備委員会を設置するというところではあるんですが、どういう方がどういう形で準備委員会をして、どう広めていくのかなという全体像をちょっと教えていただきたいのと、それからこの総合型地域スポーツクラブとはというところがあるんですが、今のところですけれども、イメージがわかないんですね。","respondent":"富田生涯学習課長","answer":"スポーツのすそ野を広げる、これは国のスポーツ振興計画が根っこにあるところですけれども、国民の２人に１人が１週間に１回はスポーツをするというふうに広げていこうというねらいがありますので、こういったところを受けて、特定のグループ等々に参加しなくても。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなってくると、この年間２５０万円という金額がどういう形で使われようとするのか、もしかしたら足りないかもしれないんですね。そうした場合に、多少の品川区として補助というものも必要になってくるのではないかなと考えるわけですが、今後これを拡大していくためには、予算上も品川区としての考え方も必要なのかなと思いますけれども、いかがでしょうか。","respondent":"富田生涯学習課長","answer":"したがいまして、あまりそちらの謝礼のほうにかける形でなく、やはりモデル事業の実施の段階から会員制、会費を徴収して自主的な組織を立ち上げて、自立して回っていただくような仕組みをつくっていくところに経費をかけていきたいと思っているところです。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれ要望という形でさせていただきたいと思います。ぜひスポーツ協会との連携を含めて、今後考えていただきたいと思います。ですから、これは今進めている八潮地区、それから荏原二中、平塚はもう既に始まっている段階ですので、それは早いうちから運営をきちんと整理させていただきたいなと思っています。それをきちっと知らせていただきたいと思うんです。それについて答えていただきたいと思います。","respondent":"古里学務課長","answer":"西本委員がおっしゃったとおり、八潮につきましても、荏原西地区中学校統合につきましても、それぞれ地域の方、保護者の方が入った部会を幾つも立ち上げて検討を進めております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"聞くところによると、荏原二中、平塚中のところについては、部会がきちんと立ち上がっていて、そこに一任しましょうという約束事で今進められているとお聞きしているんですが、全体の中でこういう部会がきちっとあって、そこで決められたことは重視しましょうという動きがさらにあると、その中で意見を集約したり、代表でも入っていられると思いますので、その代表者が自分の個人の意見ではなくて。","respondent":"長田教育次長","answer":"１つはホームページの問題も出ていましたけれども、この辺につきましてはできる限り、学校を一貫校あるいは統合するということは区にとっても大きな事業ですから、こういった部分の正しい理解をいただくため。","id":"exchange-012"},{"speaker":"金野委員","kind":"質問・要望","question":"教えていただきたいんですが、このスポーツに関しての取り組み内容の一覧に、生涯スポーツからの競技スポーツに通じるジュニアスポーツプログラムの実施とあるんですが、競技スポーツに通じるというジュニアスポーツというのはどういったことなんでしょうか。","respondent":"富田生涯学習課長","answer":"これにつきましては、本会議の答弁の中でも、スポーツ協会のジュニア育成の話をお答えしていると思いますけれども、そういったスポーツ協会と育成事業と連携するなりといった形で広く展開していけないか、これから検討していきたいと考えています。","id":"exchange-013"},{"speaker":"金野委員","kind":"質問","question":"今教えていただいたジュニアスポーツのアスリートを目指すというので、国体なんでしょうか。入ってみたんだけれども、結局その後、強化はとっかかりとして区として窓口というんでしょうか、それはすべきで、その後はご自分で強化をしていくようにしていきましょうという事業に変わっていったという経緯を伺ったんですが、その件はここに該当するんでしょうか。","respondent":"富田生涯学習課長","answer":"ということで、スポーツ協会にとっては、ジュニア育成の事業の中の１つと位置づけて、ジュニア向けのゴルフ教室を実施したですが、そこに参加すれば国体までつながるようにプログラムが組めているかというと、なかなかそこまでは難しく。","id":"exchange-014"},{"speaker":"金野委員","kind":"意見","question":"ぜひお願いしたいと思います。というのは、ずっとこれをこの委託事業の経費として使えるわけではないというところから、この取っかかりだけつくってはくださるんですが、その後どうかという周知も含めてしていただけると、この経費が生きるのではないかなという思いで今、発言をさせていただきました。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"大沢副委員長","kind":"質問","question":"今のスポーツの推進の追加分なんですけれども、都の１００％の委託事業ということですけれども、委託を受けるからには申請をしたと思うんですが、申請をして、委託が認可された日付というのはいつごろでしょうか。","respondent":"富田生涯学習課長","answer":"事業委託の募集がありましたのが今年度に入りましてからでございまして、東京都のほうからお話をいただきまして、正式決定は７月２４日に通知をいただきました。","id":"exchange-016"},{"speaker":"山内委員","kind":"提案","question":"先ほどの説明の中に校歌の話がありましたけれども、南委員のほうからもありましたけれども、校歌というのは、例えば専門家がプロポーザルのような形式で、提案型でこのようなコンセプトがあってという形での、そういう形で校歌を選んでいくのかとか、またこの１００万円の内訳というのはどういう形でしょうか。","respondent":"古里学務課長","answer":"委託の仕方ですけれども、プロポーザルとかという形は考えていないです。今のところはつくっていただけそうな人を何人かお尋ねしてお願いをするということで考えています。この内訳ですけれども、これは作詞作曲を含めて１００万円ということで予算を組んでおります。","id":"exchange-017"},{"speaker":"山内委員","kind":"質問","question":"もう既に日野学園と伊藤学園が開校しているわけですが、その伊藤学園はやっていないのか。そうすると、日野学園の校歌というのは、どういう形でやられているんですか。","respondent":"市川庶務課長","answer":"ご案内のとおり、森ミドリさんにつきましては、以前私どもの教育委員を務めていただいたという経緯もございまして、ただというわけにもいきませんので、相場よりかなり下回る謝礼でお願いをした経緯があります。","id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"じゃ、また今回その森ミドリさんにお願いするということですか。","respondent":"市川庶務課長","answer":"その辺は一切白紙です。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"さっきいろいろ聞いちゃったので、もう１回整理して２つだけ伺いたいと思います。ここのところはどういう問題意識というか、認識を持っておられるのか。学校選択制の評価というものをどういうふうにお持ちなのかをちょっと伺いたいと思います。とりあえずそれでお願いします。","respondent":"古里学務課長","answer":"後ほど、学事制度審議会の設置、それらの諮問事項についてもご説明申し上げますが、そうしたところがあるということでこのような表現をさせていただいたことです。","id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"そういう方々にこたえてこれたという、そこの点は私は否定するものではないんですけれども、しかしそういうことによってさらに小規模校をつくってしまったこの学校選択制ということについては、どういうふうに手当をしていかなきゃいけないと考えているのか伺いたいし、それが手当の方法として、学校適正規模、適正配置、つまり小規模校をなくして、大きな学校にまとめていく統廃合。","respondent":"古里学務課長","answer":"その結果、その小学校の住基人口が４０人を割るような学校がかなりの数に上っているというところがありますので、そうしたことも含めた学校の望ましいあり方というのを検討していかなければいけないです。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"つまり学校の規模について、検討する必要があると認識しているということを区長の気持ち、どこかの部分で発言されたんだと思うんですけれども、あるいは施政方針の中に書いてあったことをとって話されているのかもしれませんけれども、そういうことを紹介したんですけど、１年前に区長が述べられた学校は地域の文化、そして区政運営にあたっては区民の声を聞いていくと。","respondent":"長田教育次長","answer":"ですから、その部分をどのように実施をしていくかというのは、それぞれの教育委員会でさまざまな方法があるんだろうと私は思っています。品川については、そういった意味から、学校選択制度もその１つに取り入れたということで実施をしてきたわけです。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"どういうその辺は人数的には考えていらっしゃるのか、ちょっとその辺がはっきりわからずに、小規模だから悪いとは言ってこなかったと、予算もあるというお話なんですけれども、この辺の具体的な数字、レベルをどういうふうにとらえていらっしゃるのか、一緒くたにして小規模だと教育効果が上がらないから、これから適正規模、配置をやっていかなくちゃいけないんじゃないかというふうに思っていて。","respondent":"長田教育次長","answer":"主題であります。ですから、その中で同じことを検討するのでも、私たちは常に議会でもそうですけれども、行政効率というものは考えながら進めなければいけないというのは、今回の一般質問の再質問にもお答えしたとおりです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"しかしこの間の議事録を読んでみても、６月１２日に企画部長が教育委員会に出席されて説明されているのを、要点筆記だけですから、本旨が十分そこの文章に表現されていたかどうかは別として、また私の読解力が不足しているかもしれませんけれども、しかし少なくとも６月１２日のときに説明されたのは、品川の状況だけじゃなくて、今後１,０００校規模ぐらいの学校改築が出てくるんだと。違うんですか。","respondent":"長田教育次長","answer":"知識として、その検討を進めるときに、先ほどからも申し上げていますけれども、片や財政のほうから、こういったことで検討をして、こういった要請もありますよということで説明をしただけですから、別にここでの説明の中で。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"当たり前ですよ。そんなこと言ったら大変なことですから。言わない、言いたいけど言えない、そういう状況じゃないかなと私はむしろ思いますよ。それに、この実施計画を荏原二中と平塚中の地域に住んでおられる保護者の方は、やっぱりそうだったのかと、そういうのが第一印象だったと聞きました。いきなり統合計画を出して、制服も買って与えて、有無を言わせず統合に持ち込む。強くそのことは主張します。","respondent":"長田教育次長","answer":"その話を検討していく中で、地域への説明に入ったときに、地域の方々から、自分の出た学校、あるいは地域にある学校がどうなっちゃうのかという心配の中で、荏原二中については、ぜひそういう計画があるんでしたら、その計画の中に取り込んでいただきたいと。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ちょっとそれは置いておいて、制服のところなんですけれども、制服をこういう形で品川区が公費を使って計上したというのは、今までなかったとさっき答弁であったじゃないですか。そうしたら、地域からそういう声が上がったというのであれば、じゃ、なぜ八潮でもそういうことをしないんですか。それから、地域の声がスタートだったとおっしゃるけれども、いつどこの時点でそういう声があったんですか。","respondent":"古里学務課長、市川庶務課長","answer":"ちなみに２３区の中でさまざまに学校の統合とかが過去行われてきてありますけれども、こうした経緯で中学校等を統合した場合には、ほかの区はすべて公費負担で実施をしているということ、このことも調査した上での経費の計上です。平塚中学校と荏原二中に関する地域の声ということでのご質問ですけれども、いろいろな場で出ているんですが、先ほど教育次長のほうから説明をしたことは、昨年の７月に荏原西地区の小中一貫校の計画の概要を。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"今の地域の声の部分ですけれども、そうであるなら、そういう声があるんだったら、その声に基づいて、いきなり今年の２月６日に荏原二中のＰＴＡの役員会の席上で言うのではなくて、その間にもう少しいろいろな場面で情報提供して、どうですかと意見を聞く場面があってよかったんじゃないですか。なぜそれをしなかったんでしょうか。","respondent":"市川庶務課長","answer":"その意見をいただいたことをもとに、改めて新しい小中一貫校の就学者の推定なり、そういった調査、検討を進めた、その上で今年の２月の発表に至ったということでありまして、その間何もやっていなくて、いきなり結論を出したわけではございませんので。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"最後に。そうであるならば、そういう背景と布石があって打っているのであれば、あれだけ大きな声になり、怒りの声にはなってこなかったと私は思うんですけど。なぜああいう大きな声になったととらえていらっしゃるんでしょうか。","respondent":"古里学務課長","answer":"今、庶務課長のほうから報告をしたとおり、私ども荏原西地区一貫校の将来のあり方、周辺の学校のあり方をるる検討した結果、昨年度の希望申請の状況の最終段階ではございましたけれども、これは急遽発表せざるを得ないということで。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"最後に、本当に最後にします。本当に最後にしたいんですけれども、答弁を聞くと黙ってわかりましたというわけにはいかなかったので、よろしくお願いいたします。ですから、そういうやり方はこれからは慎むべきだと、もっと教育委員会らしく民主的に、そして、公開してオープンで区民の声を聞き、真摯に声に基づいた教育行政を行っていただきたいということを、改めてあえて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"私は新教育システム開発プログラムの内容と、議会にこのことを報告もしないで今日まで進めてきたことと、それから、新しい学校づくり推進計画の荏原第二中学校、平塚中学校の統合計画の、とりわけ効果の問題と標準服のこの予算計上、これは認められない、賛成できるものではないということで、この補正予算には反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"午後の審査ですけれども、今の午前中の審議の中で、(2)の学事制度審議会の話がかなり出ていたと思うんですね。ですから、ダブらないような形で進めていただきたいと思いますので、よろしくお願いします。","respondent":"若林委員長","answer":"西本委員から今ご発言がございましたので、各委員におかれましては、そういうことで共通の認識をして、午後の審議に入りたいと思いますので、よろしくお願いいたします。１時再開としますので、よろしくお願いいたします。","id":"exchange-031"}]},{"id":"topic-02","title":"平成２０年度学校希望選択","agenda":"平成２０年度学校希望選択","exchanges":[{"speaker":"市川委員","kind":"質問","question":"３ページのところに学校施設の制約や特色ある教育活動の継続性の観点から以下のとおりとする、小学校、中学校というふうに制約が設けられているんですけれども、城南第二小のように、かなり高層の住宅が建っているようなところは、児童の数も多くなると思うんですけれども、このぎりぎりの学校施設ということは、増えた場合は空き教室の心配というところも考えていないということなんでしょうか。","respondent":"古里学務課長","answer":"来年の入学予定者につきましては、この２クラスの中でおさまるというところで設定をしていますが、３クラスにしますと、ご指摘のとおり空き教室がなくなり、少人数指導ですとか習熟度別指導に資するような部屋がなくなってしまうということから。","id":"exchange-032"},{"speaker":"市川委員","kind":"質問","question":"これから先のこととしてもそういう予測は持っていないということなんでしょうか。","respondent":"古里学務課長","answer":"将来のことも含めて、そういうことで考えているところです。したがって、来年、再来年につきましても、人口の動態を見ながら、そういう意味では継続的な受け入れができるような形で、あらかじめ今のうちからということで考えているところです。","id":"exchange-033"},{"speaker":"石田（慎）委員","kind":"質問","question":"この３ページのところなんですけれども、２クラス、３クラスと書かれているクラスというのは、１クラス３５名前後を目安としての１クラスということでよろしいんでしょうか。","respondent":"古里学務課長","answer":"ただし６年の間に転校してくる子がいますので、学校の状態がぎりぎりというところから転校枠を改めて差し引いた１００名、中学校については１０５名、３クラスのところは。４クラスにつきましても、マイナス１５という形で定数を決めていきたいと考えております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせてください。中学生が１５名枠をつくったというのは、この数字が違うというのは、想定する上で中学校の転入が少ないからということの想定なんでしょうか。これが１点。当然物理的な問題ですから、それ以上受け入れられないというのは当然だと思います。ただ次の特色ある教育活動の継続性の観点ってどういう意味なのかというのを、もうちょっとご説明いただきたいと思います。","respondent":"古里学務課長","answer":"中学校につきましては、小学校は６年間推移をする中での転校枠の設定です。中学校は３年間ですので、半分ということも考えられるんですが、この辺は安全率を見込んでマイナス１５という形でとらしています。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"途中の受け入れ枠ですけれども、もう少しはっきり書いていただいてもよかったのかなと思うんですが、この地域の人口増加というのはどういうふうになるのかというと、これは確かにこういうところはありますけれども、ただ完全に受け入れませんよということではなくて、例えば行きたいんだけどという相談にはぜひ乗っていただけないかなとも思っているので。","respondent":"古里学務課長","answer":"私どもとしては、今まで品川区はこの制度の中で、長い歴史の中でそれぞれ保護者、それから生徒の皆さんがこれを理解し、学校選択を進めてきたと考えていますので、この後もこの方針につきましては、それぞれの年度で問題点もつぶさに検証しながら。","id":"exchange-036"}]},{"id":"topic-03","title":"品川区学事制度審議会の開催","agenda":"品川区学事制度審議会の開催","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、説明いただきましたけれども、まず非公開の理由をさっきおっしゃいましたけれども、自由闊達な意見が出ない、委員の不利益が出るため、こういうふうに説明がありましたけれども、なぜ公開すると自由闊達な意見が出ないんでしょうか。委員の不利益が出るというのは、どういうことを想定してそういうふうにされたのかが、説明が全くありませんでしたので、伺いたいんです。","respondent":"古里学務課長","answer":"これは関係機関と協議しながらパブリックコメントを、今、制度に入れたばかりの状態ですので、これからこの件につきましては協議をしながら、どのような形で進めていくかということを、具体的な検討をしてまいりたいと考えてございまして。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"パブリックコメントについては、非公開だったら、私たち区民はどうやって情報をいただけるのかが、ちょっと今の説明ではわかりませんので、もう１度説明をしていただきたいと思います。学校選択制を導入することによって、小規模校ができてしまった。学校を選んでくださることで、大きな学校規模になってしまった。したがって、今の説明をもう１回求めたいと思います。","respondent":"古里学務課長","answer":"それからパブリックコメントにつきましては、中間のまとめとして、それまでの論議のまとめをお出しするものですから、それについてパブリックコメントを求める、あるいはこうした制度を活用するというのが区長の方針ですので、その点につきましては。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"それからパブリックコメントについては、中間のまとめを１つの文章としてまとめたものを出して、それについての意見を聞くということですが、いろいろな意見を聞いて、いろいろな状況を聞いた上で、私はこう思う、ああ思うという、そういう意見がわりとスムーズに出てくるものと思うんですけれども、いきなりこうだ、こう考えているけどどうだという意見の求め方では、柔軟な意見。","respondent":"古里学務課長","answer":"３点目のご質問の趣旨が理解しかねた部分があるんですが。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"ことしの２月２日付で教育委員会がお出しになった文部科学省の新教育システム開発プログラムに事業実施計画を出されましたよね。その計画の中身、ここが非常にこの審議会の審議内容と密接不可分にかかわってくる問題だと思うんです。したがって、この審議会に、この計画については資料としてお示しをするのかどうか、そこをちょっと伺いたいと思います。","respondent":"古里学務課長","answer":"公開・非公開の問題ですけれども、私の説明が間違った説明をしているのかもしれませんけれども、設置要綱のところで先ほど申し上げたとおり、会議については非公開とするということで設置要綱を定めさせていただいてあります。","id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"その機関というのが検討委員会というふうにここには書いてありますけれども、多分この学事制度審議会のことを指しているんじゃないかなと想像して読んだんですけれども、そうすると、わざわざそういう検討機関を設置して、この学校規模適正化の検討をしていただく、そういう関係にあるこの事業計画を、教育委員会が今年２月時点に計画書をつくって文部科学省に出して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"委員長のおっしゃりたいことはわかりました。それは全然構いません。しかし、これはせんだって補正予算が配付されたときに、検討した際に、こういう資料があるんだということを私ども発見しまして、事務局を通じて教育委員会からもらったものですから、大いに請求してここに出していただいていい性格のものだと思いますので、わからなければ、ぜひ委員長としてそういう采配をとるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"そぐわないって、もう終わっちゃうじゃないですか。あるいは提供が嫌であれば直接もらっていただきたいということを申し上げているんだから、そこの判断は質疑に必要な部分ですから、正副として判断してはからってください。そのことがなくて質問できないということにはならないと思います。正副で検討してください。ちょっと質問を保留します。中身も知らないで論議なんかできないですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"今日の審議の資料は先週いただいて、それは正副のところできちっと準備をしていただいて調整をしていただいたもので今日、明日と審議するわけですから、ですから、ぜひ今回の資料をもとに、関連するのも全部わかります。わかりますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"でなければ、別途、項目の設定をしていただくとか、それは正副のほうで、あと教育委員会のほうで話をしていただいて、ほかの設定をすべきものなのか、あとはここの場でこの資料で十分に議論できるものなのかということだと思うんですね。ただ今日はこの資料をいただいているので、それで議論するという形でよろしいんじゃないんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"学事制度審議会という新たな審議会ですよね。これは学校適正規模の問題を審議するものだとわかったので、これがいわゆる学事制度審議会に相当するもの、ここで検討するものですから、関連があるんです。区が出しているものだけで判断しろという、そういうことを西本委員はおっしゃっているんですか。そういう中身もわからないで、西本さん、言うべきじゃないですよ。慎んだほうがいいわよ、そういう発言は。","respondent":"若林委員長","answer":"そのために理事者に説明を求め、また議論を交わすわけですので、その範囲の中で今日はお願いいたします。その上で、さまざまな委員会、また教育委員会に対して、また新たな提案等がありましたら、それをまた正副のほうに教えていただければです。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"資料があるんだということを申し上げたんですから、少なくともこれにみんなが目を通して、やっぱり必要なかったよ、こういうことなら、今の委員長の話も、委員長はそう判断したんだなと思うけれども、そういうこともしないで、これだけで質疑してくれなんていうのは、私はこの委員会の果たす役割としてどうなんだということが疑問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"それからさっきはしょっちゃったので、一番最初に伺えばよかったんですけど、今までこの種のテーマを検討する場合には、学校規模適正配置に関する審議会みたいな、そういう具体的な名前が冠してあったと思うんですが、今回、学事制度審議会というネーミングにした理由というのはどういうことなのか、今までこの種の審議会は、１回２回ぐらい設置されて審議されて。","respondent":"古里学務課長、長田教育次長","answer":"公開、非公開の話ですけれども、先ほど来報告をしているとおり、このことを進めていくにあたって、さまざまな観点から論議を進めていく、あるいは率直な意見の交換が必要になってまいりますし。非公開かどうかという話なんですけれども、これにつきましては、学務課長の説明もそのとおりなんですけれども、この審議会を実施していくについて、先ほどもちょっと話題に出ましたけれども、どこどこの学校がという学校を特定した発言。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"公開がされないのであれば、少なくとも区民への公聴会等々を開いて、中間あるいは最終答申前に、区報だとかホームページ等々でパブリックコメントを求めるというお知らせはありますけれども、パブリックコメントだけでなく、やっぱり大事なまち全体の問題、町会の役員の皆さんも、自分のまちにある学校がどうなっていくのかというのは最大の関心事ですから、そういう思いもある中で。","respondent":"長田教育次長","answer":"それから学校選択制との関係ですけれども、もともと小規模校が出てきたというのは事実ですし、これは子どもの数がほぼ半分に減っておりますので、それが主なる原因だと、この辺はもとになる認識の問題ですので、そこはぜひ押さえていただきたいと考えています。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"それと４ページのところの検討事項の３点、この１番と２番のところの意味なんですが、１番の意味は適正学校規模、小中一貫教育ですので、これがちょっと意味がよくわからなかったので、説明を再度お願いしたいということと、それから２番目は、規模別学校配置ということですから、１番と２番との違いがあって、あえて１番と２番という形にしたのか、関連しているものなのか。","respondent":"古里学務課長、藤森小中一貫教育担当課長","answer":"2)の学校選択制度のもとでの規模別学校配置のあり方ということですけれども、これは地区ごとにいろいろな規模の学校がどのようにあるべきなのかなということ、そうしたことをそのブロックごとに学校選択。そういった最終的な教育のねらいを到達させるためには、当然社会性あるいは学力の問題等々で、この学校規模の関係もかかわってくるのではないかという視点ですので。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"一貫校の中の何クラスあるべきかとかというところのことをおっしゃっているんですか。そうすると、連携校はどうしてくるのかなという、連携校がちょっと見えない部分があるので。連携校とかいろいろ配置を考えていくと、2)のところにも関係してくるわけで、同じことを言っているんじゃないかなと思っているんですが、その違いがあれば。","respondent":"河野指導課長","answer":"ここで言っている適正な学校規模というのは、例えばやることは同じなんだけれども、極端に学級の人数が少ないという場合には、十分な教育活動ができないということは以前から指摘されているところです。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"そちらを考えていきましょうと。じゃ、それをするときに、実現するための方策というのが３番に入るというふうに流れているということですね。理解しました。そうした中で考えるときに、厚生委員会の中に入れるべきなのかどうかわかりません。１番、２番、３番も、ときには、当然それがリンクしていって、同時並行でいかないと、そういうふうに進められないことだと思うんですが、その辺はいかがですか。","respondent":"古里学務課長、長田教育次長","answer":"したがって、この委員がおっしゃるような具体的な学区域の検討ですとか、そういう話はこの検討の後になろうかと考えておりますので、そういう段階で必要が出てくれば、この答申に基づいて学区域の検討もしなくちゃいけないような状態。それからあと、人口動態ですとか、今想定をしていないものがこの検討の中で起こったときにどうするのかということにつきましては、要綱上の７条にそういった必要が生じた場合については。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"ここの委員の人たちというのは、自分一人の問題じゃなくて、そこの今までのいろいろなかかわりの中、団体から来ているということでは、その人たちの意見をまとめるという役割も果たしていると思いますので、この認識はちょっと確認をしていきながら、品川区全体像を見ながら将来にわたって決めていくのだという、そういう意識づけというんですかね。","respondent":"長田教育次長","answer":"これが区政の根本になるものかどうかという、そこまではちょっと自信を持てないですけれども、この検討の中から波及する問題について、この中で一定の考え方は示していきたい、このような形で進めてまいりたいと考えております。","id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"したがって、私は先ほどこの実施計画をこういうふうに持って、教育委員会としては検証していきたいという思いで、文部科学省の委託を受けてやっていくという計画について、この学事制度審議会にこういう計画を持って進めているんですよという計画書なり、教育委員会の考え方なりを情報提供していくのかどうかということを聞いたんですけど、それについてはどうなんでしょうか。この計画と審議会との関係です。","respondent":"長田教育次長","answer":"学校選択制の話が今出ましたけれども、学校選択制の効果については先ほど申し上げたとおりでございまして、品川区については、この学校選択制も１つの学校の改革の方法として、これからもさらに発展をさせて取り組んでいくと。これについてはそのような形で答弁を申し上げました。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"だから今、次長がおっしゃったことは今まで繰り返しおっしゃっていることですから、それはそれとして、私は異論はあるけれども、わかっています。その上に立って、この計画そのものを、こういうことを持っていますよ、進めていますよという情報提供なりはしないんですかということを聞いているんです。","respondent":"長田教育次長","answer":"この件につきましても、先ほど学務課長のほうからお答えをさせていただきましたけれども、この審議の中でそういう内容が必要であればということが、学事制度審議会の委員長のほうから要請があれば、私どもなりに拒否をする内容でも何でもございませんので。","id":"exchange-055"},{"speaker":"南委員","kind":"確認","question":"そうすると、再度確認ですけれども、要請がなければしないということなんですか。","respondent":"長田教育次長","answer":"ですから、私のほうから、この部分が前提としてこれこれがありますよという情報の提供の仕方というのは、現在のところでは必要ないものと考えています。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"私はこちらからあえて提供しないという姿勢であれば、委員の方々にせっかく時間をかけて集まっていただき、２年近くにわたって審議をしていただく、方向性を出していただく、そういうことに品川区は別立てで研究しているということがわかったときに、私は失礼になるんじゃないかということをすごく心配するので、どうなんですかと聞いているんですけれども、そういうふうには考える必要はないんでしょうか。","respondent":"長田教育次長","answer":"南委員の意見としてはそうでしたということは、私の胸の中にしまっておきたいと思います。","id":"exchange-057"}]},{"id":"topic-04","title":"品川区立小中学校における動物飼育支援活動に関する協定書の締結","agenda":"品川区立小中学校における動物飼育支援活動に関する協定書の締結","exchanges":[{"speaker":"山内委員","kind":"質問","question":"スケジュール的なものはどういう感じで動いているんでしょうか。支援活動の内容というのがありますけれども、例えば１か月に何校、獣医師会の方々が何名で訪れてそういう講義をするとか、そういうスケジュール的なものというのは、大まかでいいんですけれども、教えていただけますか。","respondent":"古里学務課長","answer":"それぞれの事業について、例えば訪問授業については２カ月に１回巡回に行くとか、そういう形ではございませんので、あくまでも学校側から要請があった際、それを行いに行くという形で、今のところ事業の安定化に中心を置いて活動を広げてまいりたいと考えています。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"学校の生き物を飼育をするという全体的な統一的なルールみたいなものはあるんでしょうか。例えば学校によって決めているものなのか、それとも教育委員会が率先して生き物を飼いなさいよという指導のもとで飼育をしているものなんですか。","respondent":"河野指導課長","answer":"それぞれの学校がそれぞれ教育目標を定め、それを具現化するためにどういうことが必要なのかということに基づいて、それぞれの学校の教育課程を編成していくわけですが、その過程の中で必要がある場合には、学校として小動物を飼育する場合もあれば、学級活動の一環として。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"ずっとそこの学校に、今であれば校長先生の考え方で継続的にやっていけるんでしょうけれども、いろいろ変わってしまうという中では、強制はしないまでも、ある程度情操教育上とか効果もあるので安心して飼うこともできるし、子どもの教育にとって生き物を扱うと非常にいいことですから、今まで事件はいっぱいありますよね。それにあわせて予算も必要ではないかと思うんですね。","respondent":"河野指導課長、古里学務課長","answer":"最終的にはそれぞれの学校長の判断と申し上げましたけれども、それは単純にいるから飼うとか、いなくなったから飼わないとかというだけではなくて、もろもろの状況を判断した上で、学校としても熟慮の上、継続するのか。ただ今後これらの事業を発展させていく上では、一定程度の予算化は必要かなということを考えてありますので、今後予算化に向けた検討を来年度予算に向けてやってもらいたいと考えています。","id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"１つ答弁漏れだと思うんですが、通常飼うときのえさ代とかというのは、学校の中でどういうふうにやりくりをしているのかなというところが１点ありまして、それが答弁が漏れていましたので、済みません。","respondent":"古里学務課長","answer":"これにつきましては、各学校の予算の中でそれぞれ都合をつけてやっております。治療に関しましては、学務課のほうの予算で、学校から請求があった場合、獣医師会と相談をして、私どものほうで支払い手続を進めております。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"それはぜひ推進をしていただきたいというところですが、お子さんのアレルギーもあるんですね。ですから、それもいろいろと校長先生等々で思案すると思いますが、可能な限りいろいろ検討していただいて、それぞれの学校で生き物を通していろいろなことを学んでいただきたいと考えていますので、よろしくお願いをして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-05","title":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","agenda":"今定例会の一般質問に関する所管質問ですが、今定例会の一般質問の中で、文教委員会にかかわる項目","exchanges":[{"speaker":"西本委員","kind":"提案","question":"武内議員の質問にありましたいじめ・不登校の中で、荏原二中でほっとステーションの構想を武内委員が提案した中で、荏原二中でいじめも含めて考えていますよという話がありましたので、どういう内容なのかお知らせいただきたいということ、それからカウンセラーの設置をされて、かなりカウンセラーを増員されているんですが、それの実態と、それから昭和大学病院等々があると思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、先日の我が会派の委員会報告の中で、建設委員会のほうから、少年少女のためのサッカー教室という報告がありました。","respondent":"富田生涯学習課長","answer":"委員ご指摘の案件は、８月２７日建設委員会で報告されました少年少女のためのサッカー教室、オリンピアンふれあい交流事業ということで、１１月１０日に天王洲公園のグラウンドで開催されるものです。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4612#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":65436,"voices":170}},{"id":"h19-20070925-5","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"総務委員会","time":"午前１０時０２分～午後３時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"その後も３分の１というお話がありましたけれども、公共上の役割というのがこれまでの郵政事業の場合、非常に大きいわけですけれども、もちろん今回民営化して公社でなくなるとか、そういう理由はわかるんですけれども、問題は、今実際に品川でもそうですけれども、ＡＴＭが少なくなったり、撤去されたり、あるいは年金なんかは、お年寄りの場合は郵便局から引き出すというような方が多いんですけれども。","respondent":"中川原広報広聴課長","answer":"この８条は個人情報に関することを言っているものなので、情報公開については、それぞれの会社もしくは自治体がそれぞれの規定に基づいてやっております。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"ということは、品川区にその株式会社に対する情報公開をしていくにしても、従来の、どういう情報を品川区が持っているのかちょっとわからないですけれども、会社そのものについての情報というのは得ることができるという意味なんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"ちょっと今の関連になろうかと思うんですけれども、情報公開に関して独立行政法人までという解釈でよろしいんでしょうか。独立行政法人自体、国の法律によって決まっているところだと思うんですけれども、そのステップとして、そこまでが情報公開という、今のご説明のところなんですけれども。","respondent":"中川原広報広聴課長","answer":"８条によります、ちょっと条文が長いので大変恐縮ですけれども、２ページを見ていただきますと、そこに「公務員等」というのがありまして、国家公務員法とそれから独立行政法人法と地方公務員法、こういうものを私どもの条例では主に「等」という形にしています。","id":"exchange-003"}]},{"id":"topic-02","title":"議案審査の(2)、第６６号議案、政治倫理の確立のための品川区長の資産等の公開に関する条例の一部を改正する条例","agenda":"議案審査の(2)、第６６号議案、政治倫理の確立のための品川区長の資産等の公開に関する条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、この中で言っている第２条というのは、区長が当選から１００日以内に資産を、作成報告書ですか、報告書の作成をしなくてはならない。この条例が変わることで、改めて区長のほうは報告書の切りかえというのか改正というのか、そういうことをして公開の対象にしなくてはならないのですか。","respondent":"桑村総務課長","answer":"その意味では、このことははっきり言って文言改正だけで、別に文言改正ではなくて、もう法律のほうが変わってしまえば、自動的にもうこの金銭信託の概念というのは今の条例が生きていても、そのままの形になるものですので、特に新たに報告書をつくる予定はございません。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つ、契約金額の３億７,８００万円ですけれども、護岸工事の場合、川の管理者のところから、国なり都なりからいろいろな形で工事費というのは出てくるんだと思うんですけれども、この３億７,８００万円の内訳をちょっと教えていただきたい。そこを教えていただきたい。","respondent":"青木都市開発課長","answer":"随意契約ですけれども、こちらにつきましては先ほど理事者のほうからご説明しましたとおり、大崎駅周辺についての都市再生緊急整備地域の公共施設整備につきましては、都市再生総合整備事業を施行し得る都市再生機構と基本協定を締結しておりまして、その中で、設計から施工。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"あの、ごめんなさい。契約金額の中身を聞いたのは、国の補助金がどれぐらい入るのか。それと、ついでに、いつ今の護岸がつくられたものか、ちょっとそこの年度も教えていただければ。","respondent":"青木都市開発課長","answer":"補助金額につきましては、まだ確定はしておりませんけれども、補助対象金額の３分の１を予定しております。補助対象金額は２億４,０００万円ありまして、そのうちの３分の１ということで８,０００万円ほどを予定しています。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"国のほうから８,０００万円ぐらいの補助ということで、残りはもう２億９,８００万円ですか。これは区の一般財源から出てくる、そういう解釈でしょうか。そこをもう一度お願いします。","respondent":"青木都市開発課長","answer":"それにあわせて今回の護岸整備を行うものですから、再開発組合にも一定の負担をお願いしたいということを協議してございまして、まだ協議中ではありますが、再開発組合は事業の収支状況によっては一定のまちづくりに対する寄附をしたいということはお話し合いをしておりまして。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"委託内容の中で、この１２ページの委託内容の中で、東五反田二丁目第２地区市街地再開発事業にあわせて目黒川親水護岸の整備工事に至るとありますけれども、今、午前中に見せてもらった範囲では、ずっとたぶん同じ時期に護岸整備がされて、また十分に危険性のない使い方ができるような護岸なんだと思うんですけれども、この開発にあわせてということであれば、残金の２億９,８００万円というのが。","respondent":"青木都市開発課長","answer":"親水広場、護岸も含めて、民間の開発あるいは組合の開発に任せて、それの寄附をいただくというような、現物寄附をいただくということは方法論としては可能なんですが、今回、この護岸を改修するに当たりまして、管理しています東京都河川部との協議も進めていく中で。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"公共性が高いというのは、護岸ですからもちろんそうだと思いますけれども、ただ、いまのお話だと、実際にじゃあ補助金を投入をして、手直しをしていかなければならない状況にあるというわけではないわけですよね、一般的に護岸を工事する場合には、当然いろいろな規定があるんでしょうけれども、通常は河川管理者のところから工事費というのは出てくるものだと思うんですけれども、今の話だと。","respondent":"青木都市開発課長","answer":"この全体の親水広場の位置づけですけれども、まちづくり事業で進めております水とみどりのネットワークの中での目黒川をより親しい水辺空間として活用していこうというところの１つの拠点としても位置づけてありますので。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"まち全体のポテンシャルと言いますけれども、それであれば、今開発地域ではない部分も親水公園形式、それがポテンシャルを高めることになるかどうかわかりませんけれども、とにかく広げていきますよということなんですか。今後も継続をしてあの延長線上をやっていくという計画を持っているわけではないわけですよね。","respondent":"青木都市開発課長","answer":"今回ご説明しております工事に該当する部分を水とみどりのネットワークの１つの拠点としたいということで整備を進めるものですので、目黒川の護岸全体すべての延長にわたってこういった同様の整備をするというものではございません。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"それはたしか視察に行ったのではなかったかなと思いますけれども、そのような形のものもいろいろ考えていく上での１つだなというふうに思ったんですけれども、そういうことでいいかということが１つ。これはだれのものかによって管理の仕方が違うことになるでしょうから、そこら辺はどうなるんでしょうかということをお聞かせください。","respondent":"青木都市開発課長","answer":"ここの広場については区の公園としてご提供いただきますから、河川管理区域の中であるとか外であるとかにかかわらず、管理責任という意味でいうと品川区に帰属いたしますけれども、一般的な日常管理については、再開発組合が今後発展していく中で。","id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"ということは、今はこの土地全体は、その護岸の手前の川のへりを除いては、再開発絡みの皆さんの土地だと。最終的にはそれがご寄附をいただいた形になって区の所有になります、こういうものですと。そこに今この護岸の後退とあわせて小公園的な形の開発をして、水辺に親しめるようにするんですよ、こういう計画だということでよろしいんですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"原委員","kind":"確認","question":"先ほどの説明で、都市再生機構にしたという２点ご説明をいただいたんですけれども、この件自体のことではない、特に限定はいたしませんけれども、通常設計施工と工事管理というのはやっぱり民間レベルであれば、もう９割方ほとんど、いわゆる施工上もしくは施工後の責任関係として出てくるので、公共性が非常に強い河川ですから、それは非常によくわかるんですけれども、将来的に。","respondent":"青木都市開発課長","answer":"委員のご指摘はいろいろな公平性とか、あるいはいろいろなもので、汚職とかということを考えて、というご指摘だと思うんですけれども、大崎駅周辺地域、これは緊急整備地域に指定されましたのが平成１４年で、その根拠となりましたのが都市再生特別措置法という時限法です。","id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"ただ、今お話をいただいたようなところまでは、ちょっと私のほうは特に踏み込んではおりませんけれども、通常で考えますと、やっぱり一般的に、再度申し上げてしまいますけれども、特命、施主特命というような場合、もしくは今のお話だと本当に特殊性があるからということで、なおかつ一番初めから都市再生機構というのが立ち上げからということで、それは了解しておりますけれども、そうすると。","respondent":"青木都市開発課長","answer":"先ほどの答弁がちょっと的を射ていなかったかもしれませんけれども、都市再生機構に委託したものにつきましては、都市再生機構がいわば行政になりかわって競争入札に付して専門の業者を選ぶということで、また工事管理等につきましても。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"もう１点なんですが、実際のところ、こちらのほうの場所というのは防災上の問題、ただ先ほどからご説明いただいている、将来的には防災だけではなくて、まちづくりとの関連で、現実の問題としては地域住民の方のお話をお伺いすると船が入ってこれないという問題があるんですけれども、その辺に連動して、要するに出来上がったあとに、憩いの場みたいな形での防災だけではなくて。","respondent":"青木都市開発課長","answer":"今回の議案にはご説明が載ってこないものですけれども、再開発組合のほうで施工するほかの部分の広場の設計においては、近隣の方々あるいはより広い方々が集まれる、地域に貢献できるような小屋というんでしょうか、部屋をつくりたいということでご提案いただいておりまして。","id":"exchange-015"},{"speaker":"浅野委員","kind":"意見","question":"今回、こういう形で公園が整備されますと、たぶんここをスタートとしてということで、水とみどりのネットワークを今後進めていくという話ですけれども、やっぱりそれにあわせて親しみやすい川という意味では、目黒川をきれいにしていくというのも苦労されているかと思うんですけれども、ぜひとも今後ともお願いしていきたいなというふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今のお話にも若干重なるんですが、親水という名前がついたり、それから、今の先ほど見てきた目黒川の現状を冷静に考えていくと、本当に親しみやすいのかなということを考えていきますと、今の質問にあったように、非常にその部分がこれからかなという感じがしますので、多くは建設委員会と重なる視点を持ちますけれども、要は親水公園を整備していくと同時に目黒川自体の浄化をどうしていくかということで。","respondent":"青木都市開発課長","answer":"その本年度の実験の成果等を踏まえて、今後、今お話ししたような浄化対策を現実のものとしていくかどうか検討していくということで、私どもの部のほうで進めてあります。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"名前が「親水護岸」という表現になっていますけれども、これが例えば「護岸工事」であるならば、そんなに浄化のこと云々、それから船着場のことも話をしなくていいんでしょうけれども、そういう表現がついて、しかもこれを掲げるわけですから、親水という位置づけをもう一度ぜひよく考えていただきたいということをお願いしておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけ。たぶんそういうものには補助金はつかないというふうに聞いていますけれども、８,０００万円のこの補助金というのは、当然さっきからおっしゃっている公共性という部分なんでしょうけれども、どういうところに使われているという形になるんですか。実際の補助金として、この８,０００万円がつけられた理由のところが知りたいんです。","respondent":"青木都市開発課長","answer":"難しいご質問なんですけれども、今回行います親水護岸というのは、名前は護岸改修を含むので親水護岸という形で委託件名を決めましたけれども、全体として修景する、都市環境をよくしていこうというところで環境整備に該当するものでございまして。","id":"exchange-019"},{"speaker":"菊地委員","kind":"確認","question":"環境整備につけられる補助金だと。そうすると、私は前段で言いましたけれども、一般的に護岸がもう耐久年数になっている、改修しなくてはならないといったときには、護岸工事そのものに費用というのは投入されるわけですよね。ちょっとそこだけ確認させてください。","respondent":"青木都市開発課長","answer":"委員ご指摘のとおり、これは河川管理者、東京都になるんでしょうけれども、河川管理者としてある一定の年限が経って護岸の改修が必要になるということになれば、それは河川管理事業の、ちょっと正式な事業名はわかりませんが。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"私は、地域の皆さんにこの親水護岸が必要かという話をちょっとお聞きをしにいったんですけれども、確かに１カ月ほど前に説明を受けたということなんですけれども、しかしだからといって、親水護岸がどうしても憩いの場として必要なのかという声は、その方たちの中から聞くことはできませんでした。開発との関係で、この議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"川保育園新築工事請負契約、第７４号議案、（仮称）都南病院跡地高齢者福祉施設・品川保育園新築機械設備工事請負契約および第７５号議案","agenda":"川保育園新築工事請負契約、第７４号議案、（仮称）都南病院跡地高齢者福祉施設・品川保育園新築機械設備工事請負契約および第７５号議案","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"聞き漏らしたかもしれないんですけれども、階数が地上４階地下１階になっているんですけれども、地下１階がどうだったかというのは説明があったどうか、その点をちょっとお願いします。","respondent":"中島経理課長","answer":"申しわけありません、地下１階が漏れました。地下１階ですけれども、これは高齢者施設と保育園、それぞれの倉庫のスペースとして地下１階を用意しています。それと、駐輪場もあわせて設置する予定でおります。","id":"exchange-022"},{"speaker":"浅野委員","kind":"質問","question":"先ほど監視カメラというお話がありましたけれども、これはやはり駐輪場とか倉庫ということで設置をしているということでよろしいのでしょうか。","respondent":"中島経理課長","answer":"おっしゃるとおりです。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"もう一つなんですけれども、グループホームとケアホーム、１、２、３ですね、ありますけれども。〔「５ページですね」と呼ぶ者あり〕すみません、５ページと６ページですけれども、グループホームとケアホーム１から３まですけれども、それぞれの部屋数と定員ですね、直接は関係ないかもしれないんですけれども、教えていただければと思います。","respondent":"宍戸施設担当課長、日下部企画財政課長","answer":"部屋数につきましては、それぞれ定員２９名で、２９室です。ケアホーム、１人１室で個室になっておりますので、定員が２９人で２９室、それから認知症の高齢者のグループホームにつきましても、１室１人ということになりますので９室、あわせて個室が３８室ということになってあります。","id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"ページ数でいきますと最後のページの電気設備関係で、エレベーターのほうに関しましてはわかったんですけれども、施設の性質上なんですけれども、これは自家発電関係、停電等になったときの対処というのはどういうふうになっているのでしょうか。","respondent":"中島経理課長","answer":"すみません、今ちょっと調べておりますので、もうちょっとお時間ください。","id":"exchange-025"},{"speaker":"原委員","kind":"意見","question":"もう１点が、グループホームとそれからもう一つがケアホームのほうなんですけれども、この所管の関係が保健所であったり、若干ずれている部分があろうかと思うんですけれども、その辺のところがもしわかれば説明いただけると助かるんですが。そこまで。","respondent":"宍戸施設担当課長","answer":"失礼いたしました。非常用発電設備についてです。こちらにつきましては、屋上に屋上キュービクル型発電機を設置いたしまして給水ポンプ、排水ポンプ、高齢者ゾーンの部分照明、コンセント等のバックアップ等を行う予定です。","id":"exchange-026"},{"speaker":"原委員","kind":"質問","question":"それは区のほうの立場ということですよね。解釈としてはそういう解釈で。ちょっと私がした質問は、たぶん面積的にも若干ルールが、ご承知だと思うんですけれども、ルールが変わってきて、ひと部屋の大きさ等が。自家発電で、ちょっとお聞きした件とは違って、それはわかるんですけれども、上にケーブルが乗っかっていますので。施設設備、施設柄、非常にその辺が大きいのかなと思ったものですから。","respondent":"宍戸施設担当課長","answer":"失礼いたしました。約１２時間もつものです。ただし内容といたしましては、先ほど申し上げました給水ポンプ、排水ポンプ、それから高齢者ゾーンの部分照明等に使うものとして１２時間です。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしたいのは、３つの議案等それぞれに契約金額を出されていますけれども、補正予算の中で、原小学校の跡地にできるケアホームなんかは３カ年間の貸付事業というふうになっているんですよね。ここにできるのもお年寄りの施設の中でケアホームだったりするんですけれども、この違いというのはどこにあるんでしょうか。そこをちょっとお聞きしたいのと、それから指定管理者が入りますよね。","respondent":"日下部企画財政課長","answer":"原小学校との違いですけれども、これは明日補正予算の総合審査ということでこちらでご審議をいただきますけれども、その際にまた改めてご説明をしますけれども、原小学校については、基本的に土地建物は、これはもちろん区の所有でありますけれども。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"その中身は何ら変わりがない中で、運営上の問題として、今おっしゃられた公設民営と民設民営の違いということは、区の口を出す権限といったらおかしいけれども、そういう違いもまた今のお話だと出てくるということなんでしょうか。","respondent":"日下部企画財政課長","answer":"今ご指摘にありましたように、設置の形態は違いますけれども、基本的には介護保険制度の適用を受けた施設、ケアホームということで、これは区の言い方なんですけれども、基本的にはそういうような介護保険制度に立脚した施設ですから、運営。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"確認","question":"７３、７４、７５号議案、それぞれなんですが、まず、この入札が成り立たないで何回か流れたという報告を聞いたんですが、確認したいのは、それぞれの議案について、報告では１回入札となっていますけれども、まずその入札が成り立つまで何回かかったかということについてを教えてください。","respondent":"中島経理課長","answer":"この７３号、７４号、７５号と３案件ありますけれども、電気設備、電気と機械につきましては、１回の入札で成立しているということであります。建築関係の入札ですけれども、これが２回不調になりまして、３回目に落札できたです。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"６月２５日の総務委員会で報告のあった案件でもそうだったんですが、そのときには、契約案件３件のうち、１つが入札５社のうち辞退が３社。だから業者側としては、それを入れられないという事態が生じたわけですから、やはりそういうことについて、たまたま今回は７３号議案だけだったということなんでしょうけれども、再度、品川区の算定の考え方とか積算の考え方をお聞かせください。","respondent":"中島経理課長","answer":"３回目につきましては、予定価格を、これは当然予算の範囲内ですけれども、見直しをしまして、結果、こちらにつきましても対象者が、親のほうですけれども、区内９社、区外２０５社を対象として公告をかけまして、５つのＪＶが結成されて、無事落札できたです。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、やはりいろいろな経過があって、要は予定価格を見直したわけですね。いわば入札価格を下げたわけでしょう。あえてかなと思いますけれども、ちょっとその確認だけ。","respondent":"中島経理課長","answer":"この間、１回目から３回目の中で、いわゆる積算基準と言われているものがありますけれども、それが改定されてあります。その改定に合わせて予定価格を上げたということですか、結果、落札できたです。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、あとこの部分については監査の指摘もありますよね。ですから、私の言いたいのは、その積算の積み上げの仕方、それからそれに加えて、前からその点でお話をしておりますけれども、現下の経済情勢に合わせた仕組みを考えていったらどうですかということを最後に質問と確認だけしておくんですが、いかがでしょうか。","respondent":"田中総務部長","answer":"予定価格は軽々には変えられないというのは私どもの１つの見解ですので。ただ、昨今の情勢あるいは基準価格がこの３回目までにいろいろ変わりました。それを踏まえてもう一度積算をし直し、予定価格を設定しまして、今回に至ったです。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"今の積算基準があって、それらに基づいて積算をして、３回目についてはそれによって手直しをしたものでかけたと。基準を積算し直したんですから。だろうと思うんですが、その辺はどういうことを意味しているのかということが１つ。そういうものに対する対応対処というのはどういうふうな考え方になっているのか、どういう考え方という形で聞かせてもらいたいんですが。","respondent":"田中総務部長","answer":"資料でお答えしますと、先ほどの１回目と２回目は、予定価格が実は同じでございました。３回目が、実は東京都の基準がその間に変わりましたので、積算も一応し直したという形で設定をして、今回に至ったです。","id":"exchange-034"},{"speaker":"土井委員","kind":"質問","question":"機械的に見直すわけですね。ただ、東京都がどんな形でやっているのか、総合的に全部見直されたのではとてもたまらないけれども、１品目や２品目が大変急騰している、ステンレスが盗まれてしまう、滑り台が盗まれてしまう時代ですから、それらが急騰した、さあ、どうしようというので、そこだけ直すような場合だったら、積算をもともとしてあるわけですから、そこだけ直せば積算できるわけですね。","respondent":"宍戸施設担当課長","answer":"それから製作品ですよね。それにつきましても実勢価格を上げました。したがいまして、全体について見直したもので、再度起工したのが３回目というふうな内容です。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"今回のこれについては一定程度理解をします。不調になったら見直すというのでは、先ほど言われたように、業者も何回か不調を出せば見直してくれるのではないかという話になりますから、そうではない、それは物が上がったときばかりではなくて、下がったときだって同じことなんですから。その辺はどうなんでしょうか。","respondent":"宍戸施設担当課長","answer":"今般も、通常であればないですけれども、１０月１日付で財務局のほうも改定するという話がございまして、品川区といたしましてもその上げ幅を見まして、同じように上げるかどうかというのを判断してまいりたいと思います。","id":"exchange-036"},{"speaker":"土井委員","kind":"質問・要望","question":"わかりました。その考え方はあれなんですけれども、例えば電気工事あたりになりますと、銅線が上がっちゃうと、もうめちゃくちゃな値段になっちゃう可能性が出てくるわけですよね。私も昔仕事をやっていましたから、銅線が上がるとアルミを使えという話になるので、一生懸命研究をやらされましたので、それはそういうひずみがどうしても出るんですね。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"武内副委員長","kind":"意見","question":"完成予想図のほうで、右上の園庭の白い何か屋根みたいなものがあるんですけれども、これは何か説明がなかったので、違うと思うんですけれども、太陽光か何かをやっているのかどうかというところと、細かいところで申しわけないんですけれども、先ほど５ページ、６ページで企画財政課長のほうから、ケアホームが２９名でグループホームが９名ということで、合計３８室というお話があったんですけれども。","respondent":"宍戸施設担当課長","answer":"屋上の、園庭のところの屋根でしょうか。","id":"exchange-038"},{"speaker":"武内副委員長","kind":"質問","question":"６ページの下のほうの４階平面図のほうの一番下の右下のところの居室というのが、何か３部屋分ぐらいのところに居室となっているんですけれども、単純にこれはそういう図面上、もっと広いのか、あとさっき私が質問をしたのは、この居室というところを全部数えたら３９室あるんですよ。数え間違いかもしれないんですけれども。単純にそういう疑問なんです。","respondent":"宍戸施設担当課長","answer":"小規模多機能の居宅介護、３階の部分だと思いますけれども、これは、拠点施設として、デイケアのほかショートステイ。〔「それはリビングというところですよね」と呼ぶ者あり〕リビングがあって、右側に畳の４畳半のところが３つある。","id":"exchange-039"},{"speaker":"武内副委員長","kind":"質問","question":"３９ありませんか。では、あとで教えてください。すみません、たいしたことではないので。で個別に。申しわけないです。時間をとって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-04","title":"に移ります。本庁舎窓口の日曜開庁","agenda":"に移ります。本庁舎窓口の日曜開庁","exchanges":[{"speaker":"土井委員","kind":"意見","question":"日曜開庁の必要性を論ずるためには、いままでの夜間とかサービスコーナーにおける土日とか、それらの状況というものを一定程度きちんと把握をしておく必要があるというか、総括をする必要があるのではないかというふうに思うことと、それから、いままでの土日等でという、サービスコーナーのあり方みたいなものが、変更することによって変わるというようなこともあり得るかもしれないので。","respondent":"堀越行財政改革担当課長","answer":"そのほか、サービスコーナーのあり方という部分ですけれども、こちらでの業務の拡充、拡大等のご質問だと思いますが、こちらのほうは施設のいろいろ、面積のちょっと狭いということですとか、今体制が再任用職員の交代制勤務ということもございまして。","id":"exchange-041"},{"speaker":"土井委員","kind":"質問","question":"窓口でやることと、人の絡みといろいろかかわるわけですから、本庁舎ということになりますと、少なくとも窓口なんかがいろいろあるわけで、先ほどのここに書いてあったところなどがあるわけですけれども、すべての業務というわけでもないわけですよね。だからそこら辺での人件費よりも設備のほうを増したほうがいい場合だっていろいろあるわけで、その辺の考え方をもう一度聞かせてください。","respondent":"堀越行財政改革担当課長","answer":"それで、今回日曜開庁を実施したあとでの庁舎利用の方の動向ですとか、行政サービスコーナーへの影響ですとか、そういうのも考慮しながら、今後については動向を見ながら対応を検討していきたい。そういうふうに考えてあります。","id":"exchange-042"},{"speaker":"土井委員","kind":"質問","question":"それで日曜開庁ということであっても、すべてじゃないわけですから、すべてがなんて、いつもの役所とはやはり違うわけですから、そこら辺で考えたときに、先ほど言ったサービスコーナー等でのとか、地域センターなどでの割り振りとか、そういうものの発想というのがあってもしかるべきではないかというふうに思えるものですから、そこら辺の関係について聞きたいということです。","respondent":"堀越行財政改革担当課長","answer":"区民の方々に一番基本的となる事務にどう対応していくかという点で今回考えまして、証明だけではなく、届出事務等も対応するという形ですので、一定程度の面積等も必要になりますので、今回本庁舎という形での実施ということにしています。","id":"exchange-043"},{"speaker":"土井委員","kind":"質問","question":"地域センター絡みのことはどうお考えいただいているのでしょうかということです。そこで働く人たちのことは、どう考えているんでしょうか。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"４月につきましては、今ちょうど所要人員をやり始めたところなんですけれども、その中で全体を検討していきますけれども、やはりローテーション勤務を組まないと平日への影響が大きくなりますので、平日のマンパワーが減らないように。今回の場合は、地域センター等ではなくて、いろいろ本庁舎のほうで、本庁舎のほうが、いままでの動向をいろいろ見ますと、地域センター等の利用等、それから本庁舎の利用が非常に増えているというような状況もありますので。","id":"exchange-044"},{"speaker":"土井委員","kind":"質問","question":"ただ、本庁舎は非常にある意味ではいろいろなものがそろっていますから、そっちのほうがいいやということと、宣伝が行き届いていますから、本庁舎は知っているよという人がいらっしゃって多くなるというのは大いにある話だとは思うんだけれども、逆の意味で地域センター等々がもっともっと活用されるのか、これからどう考えていくのかを含めて、こっちで始めちゃって、さあ地域センターといったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"確認","question":"それで、品川区の業務は当然もっともっとたくさんあるわけで、まず１つ確認したいのが、対象業務を要するに絞り込んだ基準といいますか、考え方といいましょうか、それはどういう基準で考え方を絞り込んだのでしょうかということが１つ。それから、確認しますけれども、サービスコーナーは、いまたしか武蔵小山にもありましたよね。大井町にもあります。","respondent":"堀越行財政改革担当課長","answer":"もう１点のサービスコーナーでの利用の動きですけれども、これについては、サービスコーナーを証明発行業務ですとかで利用されている方もいらっしゃいますので、当面続けまして、また先ほどの答弁と重なりますけれども、今後の動向を見ながら。","id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問・要望","question":"おそらく土井委員もそういう思いだと思うんですけれども、やはり確認というか、もちろんこれから研究をしたり施策を検討していくんでしょうけれども、これは１つの方向性ですよね。そういうやはり考え方の整合性というのはどこかできちんととっていかないと、おかしな様子だと指摘をしますが、そのことについてお答えいただきたい。そのことの答弁をお願いします。","respondent":"堀越行財政改革担当課長","answer":"そういうことから、効果的な対応をするためにはどうすればいいのかという観点から、こういった形で実施ということを判断したものです。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まだ納得していませんけれども、やはり大きな方針転換の一部であると私たちは思います。ですから、いったん外に出した部分については賛成したわけですから、そのことについてどうこう言うわけではありませんけれども、でも今度それが終わったら、中央にまた戻していくということの過程の中においては、もう少し内部なども検討していただいて、議会に説明をしていただきたいことをお願いをしておきます。","respondent":"福田企画部長","answer":"地域センターの役割につきましては、引き続き検討してまいりたいというふうに、地域センターにつきましては、そのように考えているところです。","id":"exchange-048"},{"speaker":"菊地委員","kind":"質問・要望","question":"それぞれのこの５つの戸籍住民課から当面考えている人員の配置数を教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"菊地委員","kind":"質問","question":"もちろん雇い入れるときにそうした話をして規定は持つんでしょうけれども、その辺の、最終的に足りなくなれば非常勤でという考え方は相当な裏付けが必要だと思うんですけれども、ちょっとそこを教えてください。","respondent":"榎本人事課長","answer":"非常勤なんですけれども、とりあえず今想定しているのは再任用、嘱託員が終わったあとの非常勤ということで、区のＯＢ職員を想定をしています。","id":"exchange-050"},{"speaker":"土井委員","kind":"質問","question":"裏の７番のところに準備担当組織ということが記載をされておりまして、日曜開庁担当主査を置くことになっておりますけれども、これは７番の主題に書いてある準備担当組織という言い方からすると、時限なんでしょうか。激務のところ大変だと思います。","respondent":"堀越行財政改革担当課長","answer":"管理職そのほか責任体制の部分については、今後の試行、それから４月からの本格実施に向けて現在検討している最中です。","id":"exchange-051"},{"speaker":"土井委員","kind":"質問","question":"そうではない、そこら辺をどのレベルでどういう形で、職務的にも皆さん優秀な方々ですから、戸籍住民課のことも学務課のこともみんなおわかりで、だけれどもたまたま今そこの仕事をしているというだけだから大丈夫だということになるかもしれないし、でも指揮命令系統もありますから、どうするのかということになるので、そこら辺はどのようなお考えがあるのか。","respondent":"堀越行財政改革担当課長、榎本人事課長","answer":"失礼いたしました。全員が毎週日曜日に出るという形ではございません。交替制なりで済む形で対応していきたいです。〔「全員じゃない、主査だよ。日曜開庁担当主査については、連絡調整の責任者として置く形で、実際には戸籍住民課の課の一人として交代で出るという形になるかと思います。","id":"exchange-052"},{"speaker":"菊地委員","kind":"質問","question":"さっきの総合評価方式ですか、これでずっといろいろ書いてあるんですけれども、要は例えば指名競争入札というと、それなりの例えば技術を持った、こういう技術だけはちゃんとなくちゃならないよとか、そういう基準があってやられるんでしょうけれども、その基準にさらに基準を上乗せするということなんですか。ちょっと今。","respondent":"田中総務部長","answer":"やはり制限付き、あるいは指名というのは、やはりランクといいますか、いくら安く入れてきてもその業者はとても事業ができないよというところがありますから、実績等で格付けを行います。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1760#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":49422,"voices":194}},{"id":"h19-20070926-6","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"区民委員会","time":"午前１０時０３分～午後０時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"再委託の件でお伺いしたいんですが、ガイドラインでは原則禁止ということで、やむを得ない場合には所定の手続きを経て、これを認めるとあるんですけれども、実際きゅりあんでの再委託先というのはどのようなことになっているのか教えていただきたいと思います。","respondent":"鷹倉区民課長","answer":"具体的には、受付業務だとか、舞台装置の関係、この辺が専門業者となっていますので、大まかに言うと、そのような形です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"最後の、裏面の最後の下のところなんですけれども、経営会議における検証ということなんですけれども、指摘事項はないということなんですけれども、かなり膨大なシートが会議にかけられると思うので、多分大変だとは思うんですが、実際どのような議論が行われたのかをちょっと知りたいなと思ったのと、設置目的に男女共同参画推進等がありますが、こちらの設置目的に挙げられている男女共同参画の推進。","respondent":"鷹倉区民課長","answer":"１点目の経営会議の関係ですが、総括シートの内容等に大体こういう形で、総括に書いてありますが、やはり利用者の満足度をきちっととらえていく必要があるということですね。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"言葉の中で確認なんですけれども、総括の中で、工事で施設利用ができなかった分についてなんですが、この期間というのは当然利用率の数からはカットしているんですね。これだと、その期間を含んでいるというように見えたので、そこら辺の確認、どういう意味かなとちょっと教えてください。","respondent":"鷹倉区民課長","answer":"ちょっと表現が適切ではなかったと思います。期間があったにもかかわらず、利用料収入が増えたというところを強調したかったもので、利用率については分母と分子がほぼ同じということで、ちょっと適切ではなかったと思います。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"裏面の３番のサービス向上の中で、下から２番目、会館近隣の住民という部分なんですが、これは文化振興事業団の事業のほうの情報提供ですよね。会館の管理委託、そこら辺がちょっとどうなのかと思ったのと、それから、大井第一地域センターがあります。そこら辺はどう考えているのかなと、ちょっと確認したいということです。","respondent":"鷹倉区民課長","answer":"下から２番目のところ、財団主催の事業を会館で実施したという意味で、指定管理の範疇かなということで、ここに書かせていただいているわけです。それから、後段のお話です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本当に頑張っていただいて、これだけ利用率を上げていただいていることは十分わかりますので、後の部分は費用対効果というので、ただ、現実的には本当に近い地域に何かもうちょっと考えれば、やりようがあるのではという気もしますので、ぜひまたご検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"設置目的のところの男女共同参画推進と女性の社会的地域の向上ならびに母子福祉の増進を図るため設置するということと、指定管理者モニタリング・評価とは別という意味なんですか。","respondent":"鷹倉区民課長","answer":"指定管理の場合、場所的範囲と事業の対象ということで、場所的範囲および事業の対象から外れているということです。","id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"この３階部分は団体に貸しているということですよね。団体でも借りたいのに、なかなか借りられないとか、いろいろな、１団体が長いこと借りるとか、いろいろな意見があるんですね。その辺はどこでどう仕分けされているのか。","respondent":"鷹倉区民課長","answer":"したがって、位置づけ的には、あそこに現場にいる職員ということで、きゅりあんの指定管理からは外れているわけですけれども、連絡をとりながら、あるいは本庁の母子福祉ですと児童課が本課になるわけですけれども、この辺のところも本課とも連絡をとりながら。","id":"exchange-007"},{"speaker":"山路委員","kind":"意見","question":"もう少しはっきりしたいんですけれども、男女共同参画推進はこれから重要な行政の事業に入ってくると思っているんです。そこがいま一つ見えないんです。そこは区で直接やっているということでいいわけですよね、指定管理者とは関係なくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問","question":"初めての総括シートなので、どういったものが出てくるかなと大変興味深く見せていただいたんですが、モニタリングをするときに、私、行革の委員だったから、指定管理者と区とのコミュニケーションを図るために重要なものだというご説明を受けたわけなんです。それ以外に外部的な評価をする場所がこれ以外でもあるのかどうかというあたりを、大きなところで教えていただければ。","respondent":"鷹倉区民課長","answer":"全体的な、今の評価の視点のところで挙がっている、項目的には例えば、サービス向上および業務改善というのが３番目に挙がってありますけれども、その中で、参考に申し上げますと、例えば、重点テーマを設定し、取り組む、指定管理者からの提案等、業務改善によるサービスの向上。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問","question":"だから、その辺の、例えば、このくらいだったらよしとするみたいな基準的なもの、先ほどの物差しというところに戻るんですけれども、客観的にだれでもが、ああ、この評価はこうなんだと納得できるようなことは考えていなくて、このシートが出てきたのを区民課なり、担当の所管で論議してオーケーとするのかという、物差し自体は難しいということなんですか。","respondent":"鷹倉区民課長","answer":"は区の行政についても、接遇に対する評価があるのと同じように、指定管理者もどういう満足度、あるいは接遇の部分で職務怠慢ありだとか、いろいろな補足項目も入っておりますが、そういうアンケートを並べていって、いい方向に行くということが客観的な評価、区民の方々。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その辺も、もしあらわせたらいいのかなと思うのと、あとこの状況だと、職員の体制とか、どういった方たちがかかわって仕事をされて、先ほど再委託は２種類だけなんですか、さっきありましたけれども、委託とか、さまざまな方がお仕事をしていると思うんですが、特に区民会館というところは対人的なサービス、人と人の接するところがすごく重要ですよね。","respondent":"鷹倉区民課長","answer":"具体的に、さっきもお話ししましたこの施設を管理する上で受付の業務、それから、舞台装置については再委託をしながら実施されているという部分が一番大きなポイントになるかと考えているところです。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"意見","question":"特に人がサービスを提供するという職員配置のところが、ここには舞台技術者のことなんかも書かれておりますけれども、職員体制のことというのはすごくチェックをする必要があるのではないかと思うんですが。","respondent":"鷹倉区民課長","answer":"執務室での状況等何げなく見るだけでも、危機管理意識を持って仕事をしているかということが感じ取れる部分がありますので、頻繁に行って、向こうの状況を確認している。それが問題の発生を食いとめる一番の近道かと考えているところです。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"確認","question":"実際に足を運んで現場を見てコミュニケーションをとっていくというのが最も大事な部分だと思います。ここに書いてある中身について、議会としてというか、議員が要求したら、ここに至るまでの資料というのは情報公開の対象でしょうか。ちょっと確認して終わります。","respondent":"鷹倉区民課長","answer":"通常の情報公開の部分にのっとっていけると思いますが、相手方の分とこの分の仕分け、細かな部分をもう少し当局とも相談しなければいけないところもあるのかもしれませんけれども、基本は情報公開にのっとっていけると思います。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その辺、確認して次にご答弁いただけますか。いけると思います、この間、行革でもかなりそこを詰めてきて、具体的にこういう状況なので確認させていただきたい。","respondent":"鷹倉区民課長","answer":"これは指定管理者制度全体にかかわることですので、企画財政当局のところで聞いていただければありがたいと思います。私どもの指定管理は全体の枠の中での話ですので、よろしくお願いしたいと思います。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"８階を使ったり、１階を使ったりして、そういうときに時々アンケートをとっている。そこによって、施設の利用度合いとか、そういうものは入っていたかどうか記憶がなかったので、その辺も少し活用すれば、今度借りている人じゃなくて、利用する、参加するときのアンケートが少しはとれるんじゃないかなと思ったので、その辺いかがでしょうか。","respondent":"鷹倉区民課長","answer":"その方が利用するときに職員の対応とかどうだったか、使ってどうだったか、設備はどうだったか。今ご指摘の、施設に事業に来られた方、それは別途聞きますし、それについては事業に生かしていきたいし、ここに関連することであれば、それを踏まえていきたいと思ってあります。","id":"exchange-015"},{"speaker":"山路委員","kind":"質問","question":"今日の中途議決で、昨日出ました改正案が成立したと仮定した場合に、今お話があったのは、利率が、ここにあるのは０.７％になっています。銀行の利率というのはこれと全く同じなのか、そこをちょっと教えていただけますか。","respondent":"金子産業振興課長","answer":"利率につきましては、ご指摘のとおり、全く同じです。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それが全区展開になっていったときに、年間２,０００トンというのは現状でかなり、そのぐらいの、モデル実施したことによってこの数字になっているのかどうか、まだモデル実施になって短いですよね。それから、１１ページの７番、これはあんまり、区の直接ではなくて二十三区清掃一部事務組合のお話だと思うんですけれども、し尿関係、今、品川の中というのはどのぐらいあるんですか。","respondent":"秋山資源循環推進課長","answer":"全区展開の量ですけれども、これはモデルの実施の前に策定しておりますので、モデルの内容については、モデルの内容から引き出した２,０００トンではございません。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"廃プラの関係が２,０００トンより低くなる。この辺がモデル収集ではちょっと少ないということは、３割よりもうちょっと残ってしまうのかなというのは、不燃ごみがもっと増えるのかなという感じがしたんですけれども、それはどうなのかなというのがわからない。はさっき３６件と言われた、これはもう全然、これ以上は減らない状況なのか、その辺とりあえず。","respondent":"秋山資源循環推進課長","answer":"全区展開の際は、委員がおっしゃるとおり、資源化センターではもちろん容量的に足りませんので、どこかでうまく無事にですけれども、幸い新規の参入業者が平成２０年１０月までには間に合わせた施設をつくりたいというお話も伺っておりますので。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"３６世帯というのは、何か特殊な事情がある、多分道路づけとか、そういうんじゃなかったでしたっけ。理由が何だったかわからなかった。廃プラ関係の中間処理、確かに資源回収するとお金がかかるけれども、やはりやっていかないと、やむを得ないのかなという感じもするし、当然その前に発生抑制しなければいけないということで、その辺の考え方というのはどうなのかなと。","respondent":"島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"全部で３６件ですけど、一応下水道を全部整備して１００％なんですけれども、私道の関係で、権利の関係でできない。発生抑制をして、資源化を行って、資源化できないものについてはサーマルリサイクルして再利用という順番は品川区としても推進していくべきものだと考えていますので、お金というか。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"細かいところなんですけれども、説明の中で、サーマルリサイクルを全面実施すると不燃ごみが減るので、週に１回をさらに減らすということでいいんですか。","respondent":"秋山資源循環推進課長","answer":"そうすると、モデル地区ですと、週に１回でこのぐらいだという量ですので、それを週に１回というのが効率的かという点から、収集回数の減を検討するということになりました。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"週１回を減らすということは、隔週にするという話ですか。","respondent":"秋山資源循環推進課長","answer":"隔週であるとか、１月に２回とか、それはいろいろあるかと思いますけれども、それは検討していきたいと思います。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"しかも平成２８年度までの計画ですよね。これからの社会の方向のあり方をかなり決めていくと思いますので、そこら辺は拙速な気がするので、非常に不安はあるんです。場合によっては、もう少し区民の声やアイデアを聞いたり、必要であれば、大胆な中身の見直し、方向性の見直しとかも考えるべきなんじゃないかと思うんですけれども、そういうことはお考えでしょうか。","respondent":"秋山資源循環推進課長","answer":"パブリックコメントの期間ですけれども、１０月１１日より３１日ということで２０日間ほどとっておりますので、パブリックコメントの手続き自体は、区民の意見を広く知った上で計画をつくる、策定するですので、そのパブリックコメントをやるということ自体が。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"なおかつＣＯ2の問題もあります。やっぱりどんどんごみを出す側というか、物をつくる側もどんどんつくってしまうし、ごみを出す側も、どうせ燃えるんだからということで、どんどん出すような風潮にもつながりかねないんじゃないかと思うので、もっと多くの方の声を改めて取り入れながら計画を策定すべきだと思うんです。その点に関してはもう一度ご努力いただけないでしょうか。","respondent":"秋山資源循環推進課長","answer":"どんどん出す風潮につながるのではですけれども、当然私どもが説明をしているときには、まずは発生抑制です、それから、資源化できるものについては、汚れていないものについては資源化をします、それでもどうしてもだめなものについて、熱利用しますという形で。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"発生抑制のことなんですけれども、家庭ごみというのは日本全体の数字を出して申しわけないんですけれども、今、市民の生活から出るごみの割合というのは７.７％で、産業や事業所活動に伴う排出というのは、廃棄物の９割を占めるというデータもあります。発生抑制という点では、努力はしますという話なんですが、特に大規模事業者への働きかけなども含めて、どのような対策を考えているのでしょうか。","respondent":"秋山資源循環推進課長","answer":"特に生ごみの処理機のことですけれども、家庭の場合は生ごみが大きく占めていまして、生ごみ処理機の導入助成とか、そういうのを進めて発生の抑制を進めていくというのが今回の取り組み内容です。１１ページから１２ページでご説明した内容です。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"発生抑制１人１００グラムごみを減らしますというのは大事なことだと思いますけれども、それは主に家庭系ごみの対策だと思うんです。１２ページの排出量なども含めて、どういった考えでしょうか。","respondent":"秋山資源循環推進課長","answer":"区の収集でいけば、３２.５円ですけれども、事業所系の場合、業者に依頼をすれば、３２.５円というのは上限ですので、それ以下の金額でできる。そういうことで、事業系のごみについては発生の抑制を進めていくというようなことは可能かと考えます。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"はちょっと別になるんですけれども、新たにサーマルリサイクルとあわせて容器包装のプラスチックのほうはリサイクルするということで、そのリサイクル自体はすごくいいことだと思うんですけれども、実際リサイクルというのはどのようにされるのかというか、そこにどれぐらいの公費がかかって、そこにそもそもそういうプラスチック製包装資源というのをいっぱいつくっている事業者があるわけですけれども。","respondent":"秋山資源循環推進課長","answer":"区民は発生抑制をして、分別をしていきましょうという３者それぞれの目的が書かれておりますので、容リ法に基づいて、事業者については再資源化の費用を負担しているという状況です。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"再資源化の部分に関して事業者に負担してもらうということなんですけれども、運搬にもかなり経費はかかるとは思うんですが、今回のリサイクルにプラスチック製容器包装を回すということで、プラスチックのリサイクル自体は進んでいくとお考えですか。","respondent":"秋山資源循環推進課長","answer":"おっしゃるとおりです。進んでいくものと考えています。","id":"exchange-027"},{"speaker":"山路委員","kind":"確認","question":"ちょっと確認したいんですが、６ページのサーマルリサイクル全面実施により、東品川清掃工場は廃止する予定というのは、天王洲アイルの横の中継所でいいんですか。そうなりますと、全部なくなるわけですか。","respondent":"秋山資源循環推進課長","answer":"不燃ごみが３割減りますので、その部分、他区からの搬入もなくなる予定ですので、東品川の船舶中継所は必要がなくなるということで廃止を予定しているです。","id":"exchange-028"},{"speaker":"山路委員","kind":"質問","question":"ただ、つい先だって改修をやったばっかりですよね。経年劣化でかなりやったばっかりで、もう廃止になるのかと驚いていることと、あそこは品川区の土地でしたよね。一組じゃなかったですよね。ということは、もう今度からは、平成２０年からは品川清掃工場から京浜島へ直接ということですね、これは、それでよろしいでしょうか。","respondent":"秋山資源循環推進課長","answer":"中継所を経由しないで直接京浜島の不燃ごみ処理センターへ陸上輸送です。","id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"中継所全体は壊すというか、今後どうなるのか、予定をちょっと教えていただきたいんですが。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"したがいまして、２３区全体の枠組みを変えて、２３区として廃止等を決めなければいけないということですので、すぐにどうこうということは。それはもう既に交渉中でありまして、向こうも検討していただいているという状況ですけれども、その結論が出ないと何とも申し上げようがないというようなことです。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問","question":"一つは、パブリックコメントなんですが、先ほど２０日あるということなんですけれども、私は短いと思います。１カ月はないと、今忙しい人たちが意見を寄せようかなと思っても、あっという間に終わってしまうという状況なので、これは短いなと思うのと、あと方向はどのような方向でするのか、それを一つ。網羅はしているんです。いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"意気込みなんですけれども、私の話し方も悪かったのかもしれません、伝わらなかったのかもしれませんけれども、１１ページに書かせていただいたように、今後の取り組みのところを１人１日１００グラムというのは、実際問題としては。","id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"Ｅメールとかいろいろ、ケーブルテレビで流すというのはないんですか。ぜひ区民の方に広く、今こういうのを出しておりますといって、よりよいものにしていきたいと求めてほしいのと、廃棄物減量等推進員の方にも、これを直接渡して意見を求めるとか、関心のある方がたくさんいらっしゃるので、知らない間に終わってしまったということがないようにしていただきたいというのがまず１点です。","respondent":"秋山資源循環推進課長","answer":"ＰＲに関しまして、ケーブルテレビ、啓蒙推進等というお話ですけれども、１０月１１日号の広報しながわにつきましては、私どものパブリックコメント、あと建築課のパブリックコメントと２面一緒に特集号ということで配らせていただきますので。","id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"サーマルリサイクルについて、区民が意見を言う場がないということに対しては、どう受けとめていらっしゃるんでしょうか。区長会決定です、はいという、行政のほうはそうなのかもしれません。だからこそ余計にパブリックコメントを重視して、いたらなかった部分をここで挽回していただきたいと思うんですが。","respondent":"秋山資源循環推進課長","answer":"そういう意味で、パブリックコメントにつきましても、１０月１１日から２０日間行いますし、そういう基本のところでＰＲはさせていただきたいと思います。","id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もうちょっと積極的な姿勢をいただきたい。インターネットを開けれる人、この素案が置いてあるところに行ける人はいいですけれども、そうじゃない人、もっと意見を聞く姿勢を持っていただきたいと思うんですが、悪いんですけれども、答弁、私は不十分だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"提案","question":"ぜひ意見を受けとめていただきたいと思うのと、あとサーマルリサイクルのところで提案をされています廃プラスチックを洗って、ちょっとゆすげばきれいになるといった部分のプラスチックを再利用しようと、このことは大変いいことで、ぜひ拡大していただきたいので、その辺も地域の方への説明というのを十分して、リサイクル量が増えるように努力していただきたいと思います。","respondent":"秋山資源循環推進課長","answer":"１点目、サーマルリサイクル、区民の方へのＰＲということですけれども、これにつきましても、今後説明会等を数多く開催して、なるべく多くの方々にご理解をいただくという努力はこれからももちろん進めていくつもりですし、ＰＲ用のチラシとか、資料等につきましても。","id":"exchange-035"},{"speaker":"山路委員","kind":"質問","question":"職員の方は処分ということで、処分を受けた方は大変気の毒であると思っているんですけれども、これを受けていた三菱重工にはどういう処分があったんでしょうか。","respondent":"秋山資源循環推進課長","answer":"平成１８年、でき上がりましてからまだ１年もたっておりませんので、当然まだ瑕疵担保期間中です。今原因がどこにあるかということで、話をしているところでございまして、設計、施工上に瑕疵が認められる点があれば、求償等求めるです。","id":"exchange-036"},{"speaker":"山路委員","kind":"意見","question":"三菱重工は大きい会社でもありますし、調査しているということなので、今どうこう言われませんでしたけれども、その辺はこれからも、よく調査して、真実をしっかりとらえてもらいたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは区の起こした事件ではないので、区としての話じゃない、二十三区清掃一部事務組合の話なんだけれども、これを品川区として知ったのはいつごろなんでしょうか。というのは、議運の中で議長報告で聞いたことがあったと思うので、こんな事故があったという状況の説明があったんですけれども、区側としてはまずこの事故があったということはいつごろ把握していらしたのかなと。","respondent":"秋山資源循環推進課長","answer":"今回の事件につきましては、９月１４日に課長会がございまして、そこの時点で一組から報告を受けています。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"とまっていた理由というのは、何にも説明はなかった。当然知らないんだから、答えようがないんだけれども、向こうが隠していたという状況の中で、これは一部事務組合として、そんなことを隠しているというのは、区としても非常に、何というか、そういうことは当然すぐに発表すべき話じゃないかと僕らは判断するんですけれども、区のほうとしては、その辺、どういうふうにお考えなのかと。","respondent":"秋山資源循環推進課長","answer":"課長会で報告がありましたときも、品川区として、こういう情報を初期に開示して、説明をし、当然連絡も徹底するようにということで、課長会の当日に強く一組の担当者に申し入れたところです。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"確認","question":"品川の清掃工場にも灰溶融施設がありますが、これはもう全然問題ないという確認だけです。","respondent":"秋山資源循環推進課長","answer":"水銀のこういうことは起きていないということで、測定結果を確認しております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の水銀の値なんですけれども、具体的に、ちょっとわかりづらかったので、どのような影響を及ぼすような値なのかというのを教えていただきたいのと、職員が実際に作業をされていたから、４日間そういう環境にいたということなんですけれども、管理者、職員の方への影響というのはどうなんでしょうか。","respondent":"秋山資源循環推進課長","answer":"煙突から出たものですので、かなり拡散していきますので、一組のほうでシミュレーションしていると聞いておりますけれども、そこの中ではきちんと大気中の水銀濃度と同等であると。","id":"exchange-041"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ここに書いてあるところにおいて、多分この中防の施設というのは、昨年１２月にできたばかりですよね。何で試運転したのかなと思ったら、その前段階がどうだったのかというのは、多分把握されていらっしゃると思うので、そこのところは教えていただきたいと思うのと、わかったら、この１時間平均値は、何で最高と最低があるのかわからないんですが、その辺の数値的な説明もできたらお願いしたいと思います。","respondent":"秋山資源循環推進課長","answer":"お尋ねの２点についてお答えしますけれども、１時間の平均値のほうです。これは数値を機器で測定しておりますので、上がったり下がったりするわけです。","id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"スラグから鉛が出た。この間説明が、ＪＩＳ規格をとっているということにおいて、安全だと宣伝をされているわりには、その辺がまだまだ証明されていないということですね。排出された排ガスに水銀が出たということ、とても不安だなと思うので、ぜひ私たちも聞きたいし、区民への説明というのも今後考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/593414?Template=document&Id=2498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35014,"voices":130}},{"id":"h19-20070926-7","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"厚生委員会","time":"午前１０時０２分～午後３時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"最初の家庭あんしんセンターのほうで、使用料がひまわり荘のところでというような形ですけれども、平成１６年から平成１７年、平成１８年と、ちょっと数字的に使用料がグンと落ちてきて、またもとへ戻したというような変化があるんですけれども、このあたりの状況というのを教えてください。それから、経営会議における検証、経営会議というのはどういうことなんですか。","respondent":"諸岡児童課長","answer":"使用料ですけれども、ひまわり荘につきましては、母子自立支援施設ということで福祉施設ですので、所得階層によりまして利用料がきめ細かく分かれております。それで、収入の少ない方については、利用料はかかりません。最高の方でも月額１万４,５００円です。","id":"exchange-001"},{"speaker":"須藤委員","kind":"意見","question":"具体的にサービス向上の基本改良点で、母子家庭の自立支援のために面談を行いながら、その背景等をというようなことも考慮しながら援助計画を作成するという、これがどこまで、極端に言えば、その家庭の経済的な問題とか、いろいろな暴力的な問題、いろいろなことがあるだろうと思うんだけれども、どの辺まで援助計画というものにサポートしていけるのか、されているのかなという思いがちょっとあるので。","respondent":"諸岡児童課長","answer":"背景につきましては複雑ですが、借金を抱えていたり、あるいは過去に家庭内で暴力を受けた方、それから外国人の方などもおられます。それぞれに合わせた形で就労の計画を立てまして、１日も早く自立をしていただけるようにきめ細かく支援を図っている、そういうことです。","id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"それで、年々利用者が増えてきて、それに定員を変えなければというようなお話もさっき載っていたんだけれども、９５名、１０５名、１１１名というのは、稼働率としたらどのくらいまで現在の定員ではオーバーになってしまっているのか。","respondent":"高橋幼保一元担当課長","answer":"ただ、３歳については、３歳児クラスを担当するということについては、園のほうとしても、２歳から３歳の移行というところで、幼児部門に入るというところの気持ちとか、そういった意味では、急に外から増やすのはいかがなものかということでは増えていない状況ですけれども。","id":"exchange-003"},{"speaker":"須藤委員","kind":"意見","question":"行政としては、これだけに限らないんだけれども、その委託料という考え方をどの辺で線引きをして、最低はここまでだよというような考え方をお持ちになっているのかどうかお聞かせください。","respondent":"小林保育課長","answer":"したがいまして、この２つだけを見ましても、団体の運営に資する経費はこの合計額という形で、いい保育をして入園者が増えた、その分の保育料、ないしは、それ以外に特別保育として、預かりだとか、延長、夜間保育等の対応等もあります。","id":"exchange-004"},{"speaker":"須藤委員","kind":"意見","question":"ＮＰＯとか、普通の会社というか、法人、いろいろなところが指定管理者になっているので考え方は難しいと思うんだけれども、ＮＰＯだからあまりもうけはどうのという考え方も当然あるんだけれども、さっき、使用料については先ほどの最初の説明では、区の歳入ですという表現をされたので、ちょっと今のように、これはＮＰＯに入りますよという表現だと、先ほどの説明と今度変わってきてしまうので。","respondent":"小林保育課長","answer":"失礼しました。使用料、これにつきましては、一たん区のほうへ入って、その部分について運営費からの精査をしていますけれども、利用料部分の幼稚園の保育料に相当する部分、これにつきましては直接団体のほうへ区を経由せずに収納していただいているという形です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"モニタリングシステムのこの本の中にも、職員配置については、実際の配置数を報告するということで書かれていますので、指定管理を受けている事業者のほうからはそういう報告があると思いますので、ぜひこの資料の中にも入れていただきたいというふうに思うんですが、いかがでしょうか。","respondent":"古川児童保健事業部長","answer":"それに先立ってのモニタリングなり、あるいは評価の方法につきましては、さまざまな経緯をたどりながら区の経営会議の中で一定の方針を定め、そして先ほど児童課長から全体として申し上げましたように、行財政改革特別委員会で一定の方針をお示しをしています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、ここの中にも、５ページのところ、緊急時の連絡網を整備して非常時に備え全員に配付しているということが書かれていますし、私もこれの報告は報告書を情報公開でとって見せていただいて、改めてすごい行事をたくさんやっていまして、先ほどのご報告の中にも、園と親と子どもが一緒になって取り組むというふうなことが報告ありましたけれども。","respondent":"高橋幼保一元担当課長","answer":"保育園だと思って入園したのに途中で保育料の体系が変わるというところでは、そういったご意見等もありまして、平成１７年、平成１８年、平成１９年の入園のときに当たりましては、入園説明会をきちっとして。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、連絡網にしても、そういう親もいるかもしれませんけれども、それがないために、本当に緊急時に、例えば親御さんが亡くなられて皆さんに連絡したいというふうなときも本当に困ったというのも区に訴えがあったと思うんですが、そういうところで親同士の連携というか、仲よくなれるというか、そういうところが切られてきた部分があったというふうに思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"例えば、家庭あんしんセンターの場合ですと、区民の満足として、この２ページのところでは、直接利用者と懇談する機会を持っていますよだとか、あるいは意見箱を設けていますよというふうになっているんですけれども、利用者と懇談する機会というところでは、しっかり例えば区のほうから行っているのか、あるいは意見箱というのは、そこに設置されているんだけれども。","respondent":"諸岡児童課長","answer":"家庭あんしんセンターにつきまして、利用者との懇談会等ですけれども、これはもちろん指定管理者が主催をして利用者の方に入っていただいて実施をしているわけですが、これは私どもの職員、婦人相談員等も入ってお聞きをしています。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、意見箱のところは、管理というのは、そうすると区ではなくて事業者のほうでなさっていて、区のほうではそういう意味では管理できていないということなんでしょうか。区のほうがやるのか、区のほうがやるんだったら、そういう懇談というのはやっぱり私は基本的に区が参加するということが必要なのかなと思うんですけれども、そこら辺の考え方というのはどういうふうになっているのでしょうか。","respondent":"諸岡児童課長","answer":"そういったことで、職員は必ず１名は入っておりますけれども、その他、必要に応じて事務的な、例えば施設関係の職員が必要に応じて入ったり、そういったそのときの議題に応じて職員も参加しているというものです。","id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"意見","question":"意見箱、やっぱりここら辺は何か１つの実態をつかむ、区が直接つかんでいく上ではやっぱりポイントかなと思うんですけれども、そうすると、例えば４番のところの適正執行の視点というところでは、苦情に対しては法人の規定に基づいて適切に処理されているというふうになっているんですけれども、そういう評価が実際に、要するに、情報をどういうふうに管理されるか、つかんでいくかによって。","respondent":"高橋幼保一元担当課長","answer":"日々の意見とか苦情につきましては、それぞれ園のほうで対応するというのが基本になってます。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"意見","question":"園の中の様子は大体見えているということなんですけれども、先ほど、私ちょっとよく聞こえなかったんですけれども、第三者委員会の構成のところ、最初のほうはＮＰＯの会員が２名と、その次は、子育て何とか、そこが聞こえなかったんです。","respondent":"高橋幼保一元担当課長","answer":"子育て品川の幹事です。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そうすると、さっきと同じような質問になるんですけれども、区側のほうでやっぱりしっかりこういうところにメンバーとして入っていくだとか、そういうふうにしないと、今、中がよく見えているというお話なんですけれども、私はそこら辺のところが何かそういうのをしっかり見える担保になっているのかなというのが、正直言って心配なんですよね。ここはちょっと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"３点目が、自治体の管理経費の軽減である。指定管理者制度を導入して任せたわけですから。だから、そういうものに向けて、確かに重ねてご心配なされる点は多々あるのかもしれませんが、そういう面でよく行政は行政としての責任を果たすべき対応の仕方というのも、これも当然あるでしょうから、その辺、しっかりと取り組んでいただきたいなと、この意見だけ申し上げて私は終わりたいと思います。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"改善が必要な事項といたしましては、利用率を増加させることということで、この原因の分析といたしましては、この利用率増加策の検討・取り組みが必ずしも十分ではなかったということで、この対応方針といたしましては。改善が必要とされる原因の分析等はございません。裏の２４ページに参りまして、区民満足の視点ということで、意見箱を設置するなど、入居者の声を収集し、対応しているです。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"高齢者住宅のほうの区民満足度というのが、入居者というので、最初に戸数があって、もう戸数はいっぱいですよ、１００％入って、その年に新規に何人、４人、５人という数字であらわしているのだろうというふうに理解するんだけれども、その区民満足度というのが単に入っている人たちに区民満足度を聞くのか、高齢者住宅について満足度はどうなんだという考えをするのか。","respondent":"蓼沼高齢福祉課長、山田副区長","answer":"それから３点目の経営会議につきましては、これはちょっと私どもがどのように答えていいかわからないところがありますが、これはそれぞれの施設ごとに経営会議で検討されて議論された結果だというふうに認識をしております。経営会議での指摘事項ということでお話がございましたけれども、経営会議の中でこうした同じような詳細な資料をいただいて、それぞれ見させていただきながら。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"経営会議の中で見てきて、本当の区民にサービスになるようなものにつながってくるのが、指定管理者の今度のこういうモニタリングの仕組みだと思うので、そこでやはり、もちろんコストも大切なことなんだけれども、それだけでこういった福祉施策というのが行われるものではないと思うので、そのあたりも区民の気持ちになって指定管理者の運営というものに当たっていただきたいと思います。","respondent":"山田副区長、蓼沼高齢福祉課長","answer":"そのよりよいサービスを支えていく上で、いかに効率的な運営の仕方ができるかという観点もきちっと経営者としてとっていくという部分で、品川総合福祉センターのところではプロジェクトを組んだりとか。そうした中で、ショートと複合的なそういう施設の特徴を生かして、先ほどおっしゃいましたような緊急時にも対応できるような部分にそういう空いているところを活用していこうというのが考え方です。","id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"同じ一覧につくっていくという難しさが当然出てくるので、その辺のところは僕らも見ていて理解するところなんだけれども、これが１つの例で、まただんだん改善されてくる形になろうとか思うんだけれども、やはり指定管理者には区民にサービスしていくという視点をまず持っていただいて、コストが云々という、当然それは考えなければいけないことなんだけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこで、ちょっと１つお聞きしたいのは、先ほども申し上げたんですが、職員体制がどうなっているのかということを、特にこの３つの特養ホームで介護職員が何人ずつ配置されているのかということを、常勤、非常勤の数で教えていただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"職員の配置ですけれども、まず戸越台特養ですけれども、介護職員は常勤で２１名です。それから、荏原特養につきましては、介護職員が３７名。中延特養につきましては、３２名という状況です。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そこら辺の職員体制というのが私は今回の高齢者施設の中では最も大事な部分で、ここのところを確保するのが本当に大変だという、そこの中からくすのきの郷の問題なんかも起こっているわけですから、ここのところをしっかりつかんで、区がやっぱり大変なところには支援も含めて行っていくというのが大事なのではないかなというふうに思いますので、これはぜひ常勤、非常勤。","respondent":"蓼沼高齢福祉課長","answer":"基本的に先ほど申し上げました大規模加算と、それから都の制度に準じた経営支援費、そのほかの若干の委託料も含めた金額がこちらに入っているわけですけれども、区としては継続的に特養の運営を支援してきているというふうに認識しております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"報告書、計画書が。それで、１年前の計画書、報告書の中には、常勤、非常勤、しかもその介護職員の中身までしっかりと書かれているんですよ。そういうところでぜひ区としても把握していただきたいというのは要望しておきます。そして、特養ホームの再委託先というのは、調理業務とかなんかがあるのかなと思うんですが、それ以外に何かあるのか、そのこともお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"この再委託先への指導といいますのは、これは情報公開規定は及ばないものと考えております。この後段の個人情報保護の部分についての指導であろうというふうに考えます。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それなので、現場のほうからは、委託そのものもすごく大変だし、委託先が食材費、７８０円、今まではしっかりと確保できていたんですけれども、それそのものも確保するのが大変だという声もお聞きしたんですけれども、そこら辺のところは区としてどのようにつかんでいるのか、そしてそれに対してはどう改善について考えられているのかということでお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"平成１７年１０月にホテルコスト、食費について、食材利用費等については保険の給付の対象外になったです。これは在宅にいる方との負担の均衡を図るですので、これについてはそういう制度改正の趣旨で必要なものについてご負担をしていただいているです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つお聞きしたいのは、戸越台の特養のところでは、個別ニーズに即してサービス提供の向上を行っていくということで、そうすると、個別ニーズというのが強調されているなというふうに思ったんですが、以前ちょっと私が相談を受けたときに、頸椎から来る病気で、手がもう冷たくて、しびれて、特養に入って、１日１回でいいから暖めてもらいたいという、そういう要望が出た。","respondent":"蓼沼高齢福祉課長","answer":"そういう観点で、この戸越台のシートの記述では、そういう趣旨でこれの問題認識と対応の方針が書かれているものというふうに考えております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は個室ユニットケアのような個別、そういうところのもちろん個別ケアと言ったのではなくて、一人一人違うわけですから、その方、その方に合わせた介護というところで、特養ホームであってもぜひ、もちろんこの戸越台だけでなく、どこでもぜひやっていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"先ほど、子どものほうの施設のところでもちょっと聞いたので、ある意味では同じ角度かなというふうに思うんですけれども、例えば、先ほど説明があったこの２ページのところで、サービス劣化というのは、これはサービス低下というふうに理解していますというふうなお話しだったんですけれども、これ、具体的にどういうことを言っているのか、ちょっと私、これも読んでいて意味がわからなかったんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"苦情等ですけれども、これにつきましても、ここに記載していますとおり、現場のリーダー・施設長が窓口になって、それについて受けとめて対応策を検討し、取り組みをしているということが第一義的な取り組みであろうというふうに思います。","id":"exchange-024"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"これは私、どうも意味がよくわからないんですけれども、引き続き、福祉カレッジの受講の励行、これで問題解決するのかどうなのかはわからないんですけれども、この日々の実践に活かしきれない面があったというのは、具体的にどういうことを言っているのか、区のほうはつかんでいるのか、そこのところはちょっと、細かいことであれなんですが。","respondent":"蓼沼高齢福祉課長","answer":"あわせて意識改革を図っていくですので、区としてもこの認知症ケアの専門研修は介護福祉専門学校に委託をして実施をしていますので、それは研修の実践の場ですとか、施設に持ち帰ってどのようにケアの中に活かしていくかということは。","id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私、今の説明では、実態がやっぱり全然把握されていないと思うんですよ。この事業者からこういった報告を、モニタリングを受けて、それで、それを所管課が評価して、事業部経営会議で評価するわけですから、やっぱりそういう仕組みの中にあるというのは、区の側がいかに実態を把握するかというのが私は命だと思うんですよ。これは全体に言えることだと思いますので、重ねてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問・要望","question":"送迎の再委託においては、日々のミーティングに運転手の参加を求め、利用者の身体状況や対応方法について情報の共有を図った。それから、２０ページです。３行になっておりますが、この真ん中の行のところです。ですから、そういうようなことをぜひ実施していただいて、よりいい形に区民の皆さんに喜んでいただけるような方策を取り入れていただければなと、そう思うんですが、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"ただいまの指定管理者間の情報交換、意見交換の場はいかにというお尋ねですけれども、これはそれぞれの、例えば４ページの４番、組織管理体制のところ、施設連絡会、あるいは社会福祉法人の懇談会、年３回。","id":"exchange-027"},{"speaker":"堺委員","kind":"意見","question":"ここに書いてあるのはそういうことだったんですね。確かに書いてあるんだけれども、区が主催をしてこういうことをやっていますよと何か一言あると私でも理解できたんです。ただこれだけだと施設連絡会、要するに、三徳会が自分が受けている施設間かと、そんなふうに思いました。ぜひそういうところでいい面については利用者のサービス向上につなげるという、そういうことでお願いしたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２１ページのところで、さくら会で、月見橋在宅サービスセンターで、ここのところだけに送迎車両に緊急対応用備品を装備するというふうなのが書いてあるなと思ったんですけれども、ここのところで上のほうへ行くと、救急対応体制というふうなこともありまして、これは何か事故か何かがあったのでしょうか。マニュアルもあわせて。","respondent":"蓼沼高齢福祉課長","answer":"緊急時の救急対応体制ですけれども、これについては、ここにもありますように、送迎時・退出時における体調不良などといったときに、伺っておりますのは、事故というほどではないんですけれども、やはり迅速な対応といいますか。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"緊急対応用備品というのは、薬品というのがちょっとよくわからないんですけれども、これを１つ具体的に教えてもらいたいのと、それとあと、このデイサービスのほうが多くのところが利用率の増を図るというのが書かれていまして、この利用率のところを見ても、先ほども出ていましたけれども、本当にまだまだゆとりがあるなというふうな思いがするんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"利用率につきましては、高いところもありますけれども、低いところもあるということで、それぞれこういったようなさまざまな機会をとらえて、その原因を分析して、それについて必要な対応をとりながら利用率の増加に努めようということでございまして。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと一番最後に、私はこのデイサービスにしても、人の問題というのがやっぱりこの介護の問題というのは一番の問題で、現場の職員は本当に頑張って、その頑張りで支えられているというのが今の介護の現場ではないかと思うんですけれども、そういう中でやっぱりきちんと人が配置されて、やりがいを持って働ける、そういう体制をつくるということが一番大事なことだと思いますので、そういうところでの把握と。","respondent":"蓼沼高齢福祉課長","answer":"確かにおやめになる方も結構早い時期にいらっしゃるというふうに聞いておりますけれども、各施設の具体的な離職率については、数字を把握をしていないです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは社会的な問題にもなっていますので、区としても実態をつかむというところでも大きな指標の１つになると思いますので、この離職率についてもぜひ今後つかんでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者のほうも職員体制を確保するのが大変だけれども、障害者のほうも大変だというふうに聞いているんですけれども、そういうのがなかなかここの中からは見えてこないんですけれども、そこら辺の実態とあわせてお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"心身障害者福祉会館につきましては１７名、それと品川児童学園につきましては８名、西大井福祉園につきましては８名、それからかがやき園につきましては１６名です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大きく制度が変わる中で現場の実態を踏まえて、ぜひ現場が充実したサービスができるように支援をしていっていただきたいということで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"須藤委員","kind":"質問・要望","question":"３５ページのところが、定員７人で入所者、退所者がずっとゼロですよという形で進んできた。それで、そこに高齢者が１名出ました。それから次でもやはり同じようなことで高齢者が出てきた。それから、こういった入所希望者というのがどの程度いらっしゃるのかと、いろいろな状況で入所を希望する人がまだまだいらっしゃるのかどうか、そのあたりを教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"それと、３５ページのところですが、高齢者が今後増えてきて応援体制等ですが、今の時点で１０年たって約６０代の人が１名増えてきたということですが、知的障害者の方につきましては、今後、私どもでも課題だと思っているんですが。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問・要望","question":"平塚きぼう荘の使用料というのは、家賃という形なんだけれども、２戸というのは、１人ずつ入っているんですか。そうすると、月５万幾らというような費用になってきてしまう、これも所得だとか何とかでいろいろ違いがありますよという考え方なのか、その辺を教えてください。","respondent":"高橋障害者福祉課長","answer":"平塚きぼう荘の家賃のお尋ねですが、条例では月額７万７,０００円ということなんですが、ただ、この入居している２人の方につきましては、生活保護を受けているので、生活保護の限度額ということで。","id":"exchange-036"}]},{"id":"topic-02","title":"本件を終了いたします。 次に、後期高齢者医療制度に関する意見書案","agenda":"本件を終了いたします。 次に、後期高齢者医療制度に関する意見書案","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、１の７４歳までの特定健診と同様の財政支援というところなんですけれども、７４歳までの特定健診と同様と言うと、７４歳までの保険でやるというようなことになると思うんですけれども、そういうことを求めていくということなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"新しい制度できのう説明いただいた４０歳から７４歳までの特定健診という形が国、都、それから保険料自己負担という、３分の１ずつというような形で記されていますよね。ですから、そのいわゆる国の負担というか、補助というのを入れてやってくださいという意味で今回こう記してあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"須藤委員","kind":"提案","question":"きのういろいろ話しているときは、委員長が説明して議会全体の、厚生委員会だけではなくていろいろな方々もこのことを懸念しているので、議会全体の総意という形のほうがいいんじゃないだろうかというお話があって、委員長が議会運営委員会で説明して、議運のメンバーが提案者というほうがいいじゃないかというようなお話もちょっとあったので、ですから、そのあたりを今ちょっと決をとる前に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"堺委員","kind":"意見","question":"須藤委員がおっしゃったように、たしか昨日、そういうことも含めて申し上げたつもりでおります。品川区議会としてきちっと物申すというふうにしたほうがより重みがあるのではないかということも申し添えたいと思いますので、できれば皆さんに諮っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"本間委員","kind":"意見","question":"今、堺委員のご意見がございました。厚生委員会の総意としてのまとまりはこれでいいと思いますが、やはりより幅広く東京都、国に意見を申し上げていくというふうな場合には、やはり議運の中でもう一度、手続き上可能であれば、議運の中でもう一度諮っていただいて、総意としての意見の取りまとめとして上に上げていくというほうがより強固な形になるのではないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"ただ、この間、地方自治法改正で各委員会からも提出できる云々というものが変わってきているので、委員会で出したほうが議会全体としての意思として流れていくやにも、そういう改正になってきているので、そのあたりをですから今、決めてしまわないで、どちらのほうがきちんとしたというか、両方ともきちんとしているんだけれども、強い行動になるのかというのを、委員会として出していくのがいいのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"須藤委員","kind":"意見","question":"上へ上がっていくのは、両方とも区議会議長名になるんだけれども、それは同じことなんだけれども、今言った初めてやっていく仕組みになるので、そのあたりもちょっと厚生委員会で、もちろん委員会全部で行けばできますよという仕組みになっているんだけれども、議会として初めての行動なので、そのあたりも事務局とちょっとご相談していただければ、委員会で出すのもやぶさかではないし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/443219?Template=document&Id=3184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":68973,"voices":109}},{"id":"h19-20070926-8","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"建設委員会","time":"午前１０時０２分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"委員長、冒頭に委員会運営について一言いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。今日の委員会ですけれども、資料の配付が２日前ということですが、再開発のほうは昨日、耐震化促進計画については、つい１５分前に配られたということなので、その理由を説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"活発な委員会を進めるためにも、今まで２日前に資料を出して委員会を行ってきたという流れの中で、今回、理由は今ご説明がありましたけれども、ぜひ２日前に資料は出していただきたいと思うのと、とりわけ、後でご説明がありますけれども、耐震化促進計画については大事な問題だと思いますので、ぜひ今日の委員会だけで終わることなく、次回しっかり改めて時間をとって行うべきだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"に入ります。 (1)の戸越幹線中流域浸水対策事業説明会の開催","agenda":"に入ります。 (1)の戸越幹線中流域浸水対策事業説明会の開催","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その辺の数というんですか。そこら辺をちょっとご意見を聞いて検討というか、要は雨水５０mmに対応ということですが、生活排水がどんどん増えることによって、今回それでも問題ないような戸越幹線中流域の浸水対策ということで、そこら辺は計算に入っているんでしょうか。その辺をちょっとお聞かせください。","respondent":"家壽田下水道河川課長","answer":"今、委員ご質問の件ですけれども、５０mmの計画の中に生活排水の汚水量が含まれております。これにつきましては、一般的に５０mmのときにどれぐらいの比率が汚水と雨水になるかですが、汚水が仮に１としますと、雨水が７０ぐらいで考えております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"この出席者が８名ということですけれども、説明会の周知の方法はどうだったのか聞かせていただきたいのと、あと、この場所に貯留管方式ということですけど、今後この方式でこういう対策を行う計画みたいなのはあるのかないのか、教えていただけますか。","respondent":"家壽田下水道河川課長","answer":"説明会の周知方法についてですけれども、７月３１日に地域センターにビラを持ち込みまして、５町会の回覧板、それから掲示板に掲載しております。８月１７日には路上工事が発生しますお宅の、まさに近接する家屋には直接ビラも配っておりまして、周知を図っております。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"第１回定例会に契約議案が出てくるということで、３月中に工事契約をされるということなんですが、最終本会議が多分３月の終わり、２７日か２８日なのかなと思っています。それが４月１日か２日じゃ、年度的に書くんだったら、これは平成２０年度から２１年度でいいわけだよね。それが２５カ月だと、平成２２年度の４月になっちゃまずいと思われているのか、教えてもらいたい。","respondent":"家壽田下水道河川課長","answer":"発注方法等の２年債務にするのか３年債務にするのかにつきましては、受託事業ですので、現在、東京都の下水道局と協議をしておりまして、できれば平成１９、２０、２１年の３年間で工事をするということで考えております。","id":"exchange-006"},{"speaker":"三上委員","kind":"質問","question":"そうでなくて、もうこういう説明会をやって、それからいよいよこういう話が始まるぞとなって、それからまたああでもないこうでもないと始まるのでは、過去のそういう騒動が何の知識、知恵にもならないようなことで終わってしまうようなことであれば、この今の契約の案件にしても２５カ月で終わるという話ではなくなってくるということになるわけですから、そういうあたりの地元の理解度。","respondent":"家壽田下水道河川課長","answer":"ただし、水をためるときには、空気を抜いていただきませんと水が入っていきませんので、その空気の置換というものを戸越銀座通りのわきからぶつけてやる計画になっておりますので、このときに若干地上での工事が出てくるということで、地元でも説明させていただきましたけれども。","id":"exchange-007"},{"speaker":"三上委員","kind":"意見","question":"今のところそうなんですよ。ただ、現実にここの場所と特定した場合、そこから始まるんですよね。だから、この工事期間中は水が出ないように考えるのは当たり前であるけれども、そういうことがないように将来的なことをやるためにここに必要なんだということを今の段階からそこの場所に対しては説明しない限り、こういうところから反対運動が起きてくるんですよ。ぜひお願いしたいと思います。","respondent":"家壽田下水道河川課長","answer":"今のまさに工事をやるんだというイメージは、先ほどビラを配布したというところで、路上工事を予定するところについては、それに関して既にビラを配っておりまして、その方々が必ず全員出てきたわけではありませんけれども。","id":"exchange-008"}]},{"id":"topic-03","title":"目黒川親水護岸整備工事","agenda":"目黒川親水護岸整備工事","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ意見だけ述べさせていただきたいと思います。この公園は、きのうも言いましたけれども、開発事業者のクオリティーを上げるためのものであり、間違っていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"浮き桟橋までおりる護岸は、これで見ると、どこかを乗り越えていくわけだけれども、そのときの階段は水かさの違いもあるんだろうから、例えばこの護岸に沿って階段をつけるとか、そうすればどこの高さでも浮き桟橋を使って船で避難するとか、災害のときにいろいろなことが考えられるわけだけれども、その階段みたいなものもかいていないんだけれども、その２点を教えてもらいたいんですが。","respondent":"青木都市開発課長","answer":"ご指摘のとおり、そういった浮き桟橋を出し入れして使うことになるんですけれども、この絵にはのっかっておりませんけれども、先ほどご説明した三角形の陸地部分、民間事業者側で整備してもらいます提供公園の中に地域交流施設のようなものをつくる予定でございまして。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"しながわ水族館なんかもそういう形になっていますよね。今言ったはしごという壁沿いの部分というのは、実際に災害が起こって、全部道路が使えない。災害が何か起きたときには。そこら辺の河川管理者との話の中で、影響が今あるという話なのか、どうなのか。船に近づけないんだから、そういう問題じゃないと思うんだけど、そこら辺のところをもう１回ちょっと教えてもらいたい。その階段の部分だけ。","respondent":"青木都市開発課長","answer":"この件につきましては、工事は発注いたしますけれども、最終的な護岸を削るというご提案に対してはおこたえできかねると思うんですけれども、何らかの安全なタラップ、おりていく方法論については、その詳細な検討の中で最終的にしつらえていきたいというのが現状です。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"護岸を削らなくてはならないとは思っていないんだけど、それに足すだけでも階段はできると思うし、ただ、水の流れの問題はいろいろと考えていただかなくてはならないけれども、本当に積極的に使うというか、災害があったときに何が大切かということを考えるのであれば、そういうことを準備しておくというのが私は本来だと思うので、ぜひお願いだけしておきますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"そういう中にあって、こういう構造的な部分というのがなぜ考えられたのか、これが１つですね。人が通れるところは満潮時に水があふれてくる可能性もあるのかないのか、それはちょっとわからないんですけれども、そういう説明がないので、そこらあたりは本当に満潮時の時点でその地点から何ｍ上の部分にこの人が通れる平面があるのかというのを、もう１回ご説明していただけませんか。","respondent":"青木都市開発課長","answer":"そういったことから、いろいろと地元からもご要望がありましたし、私どももできるだけ親水性の高いものでいいものをつくっていきたいということを考え、なおかつ防災機能もということでいろいろ検討してきたんですけれども、現実的に現地の状況、広さ。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"完成後に区が引き継ぐということは、公園全体は区立公園になって、区がその管理をするということでよろしいんでしょうか。","respondent":"青木都市開発課長","answer":"そのとおりです。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"それで、この三角形のところは業者の土地で業者が整備するということですが、でき上がったら一体的な公園として使われるというので、使い勝手なんていうのを一体的にデザインされたほうがいいのではないかと思うのですけれども、それはここでかいていないだけで、一応そうした話はきちんとできていて、全体のデザインというのがある中で切り取ったここだけを今回示しているということでよろしいんでしょうか。","respondent":"青木都市開発課長","answer":"全体の絵は再開発事業の指導という観点からも建設委員会でご指導いただくべき案件ですので、ある一定の時期にこの公園全体の計画概要がまとまりましたら、改めてご報告させていただきたいと考えています。","id":"exchange-015"}]},{"id":"topic-04","title":"区民住宅ファミーユ西五反田西館の指定管理者募集","agenda":"区民住宅ファミーユ西五反田西館の指定管理者募集","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、現在６社ほど参加の話があって、締め切らせていただきましたというお話でしたけれども、書類審査、ヒアリング審査は選定委員会の中でどのような審査を行うのか、教えていただけますか。","respondent":"齋藤住宅課長","answer":"審査の具体的な個々の中身につきましては、地方自治法の契約締結権の中身になりますので、大まかなところでいわゆる企業としての執行体制ですとか、就業者は現場でどのような方法で取り組んでいるか、現状どうやってどのような管理体制をとっているかとか。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"今、審査の中身の大まかなご説明がありましたけれども、この審査の中で指定管理者の候補者を選定するわけだと思うんですけども、その指定管理者となる団体について、例えばその団体の、会社だったら社長、団体だったら代表者、その役員の中に、例えば品川の区議会議員がいたり、現職の区長や三役がいたり、また配偶者、親族、その他含めていろいろな者がいるという法人や団体については。","respondent":"齋藤住宅課長","answer":"もし、地方自治法に規定されている支配人に当たる者が議員や首長の親族にいるというのであれば、排除されますので契約はできないことになります。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"つまり、議員だったり三役だったり、教育長も含めて、議決や契約の締結に直接、間接的に関与する立場ですから、その権限が鈍るというか、恣意的に用いられてはだめだということで、制限されているわけですけれども、この地方自治法の請負禁止規定というのは、指定管理者制度にも適用されるものなのか、そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"適用されます。民法でいう請負よりも概念が広うございまして、継続的に利益を受け続ける立場にある者が契約の相手方になってはならない、排除しなさいですので、本件でも同様に解釈しています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"いわゆる請負には当たらないという話を聞いたことがあるんですよね。そうなると、今はなっていないとは思いますけど、今の制度のままでは指定管理者として指定される団体の長、社長だったり、取締役だったりというのは、区議会議員や区長がなる道を残しているんじゃないのかなという気がしてならないんですけれども、それについてはいかがでしょうか。","respondent":"齋藤住宅課長","answer":"契約の問題でございまして、私が住宅課長としてお答えはできかねます。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"品川区には現状そういう条例がないものですから、どういうお考えなのかなと。今のご説明ですと、審査の過程の中で、当然選ばれない理由の１つになるというお話でしたけれども、改めてその基準を再度ご説明いただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"確認","question":"じゃあ、確認ですけど、現在、ベニーエステートサービス株式会社も、社長、役員の中に議員はもちろん区の三役、親族も含めていないということでよろしいんでしょうか。","respondent":"齋藤住宅課長","answer":"おりません。","id":"exchange-021"}]},{"id":"topic-05","title":"平成１８年度区民住宅・区営住宅における指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成１８年度区民住宅・区営住宅における指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、冒頭に若干説明がありましたけど、区で点検したものを議会に報告するという話がありましたけど、そこのところをもうちょっと詳しく説明していただきたいと思ったのが１点と、あと、中間評価が出た時点で報告をするということの区の方針というか、その辺も含めて、もう少し詳しく教えていただけますか。","respondent":"齋藤住宅課長","answer":"今、委員ご質問の点は行財政改革特別委員会のほうで企画財政課のほうでご説明申し上げたところでございまして、住宅課長として説明するにはなかなか難しいのですが、要は、指定管理者制度をとってサービス向上、経費削減につながらなければ意味がない。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"その建設委員会に今の報告があったわけですから、所管の部としてどういう理由でこれを報告したのかというのは、きちんと説明をいただきたいなという思いで質問したので、これは建設委員会でそれぞれの業者を指定管理者として決定するか否かを審査をして、本会議で議決をしたわけですから、この報告をした理由をもう少し詳しく説明していただきたいという趣旨です。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"ただ、中身はどのような業務をしていて、どういった問題があるかは所管の課、私のほうから説明させていただいて、福祉の指定管理者であれば厚生委員会で、そういう形で説明をするということです。当然のことながら、議会の議決をいただいて決めた業者ですから、そのＰＤＣＡの適切な時期にきちっと議会にも明らかにしていくという、この１つの制度として、今回。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"その結果、こういう評価になりましたよというその両方が必要ではないのかなと思うんですよね。この区の評価を僕らが再評価するわけではなくて、その事業が適切に行われたかどうかをそれぞれの委員の目でチェックをするわけですから、事業計画書や事業報告書、基本協定書をしっかり出してもらった上で、区としてはこういうふうに総括シートをつくりました。","respondent":"齋藤住宅課長","answer":"統一の総括シートでもってお示しをする。これが今のところの区の考え方です。どこまで議員が関与していいか悪いか評価するについては、おそらくは今後研究することだと思います。ただ、例えば、契約締結権、契約自由の原則でございまして、決めたと。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的にその総括シートに書かれたことで１点伺いたいんですけど、指定管理者の三井不動産株式会社の総括のところで書かれているんですけれども、家賃滞納時には粘り強い対応というお話がありましたけれども、その家賃滞納者の理由というのは何かということと、直接家賃の滞納の理由になると、個人情報なんかの固まりみたいなものじゃないですか。","respondent":"齋藤住宅課長","answer":"個別の理由はちょっと言いにくいんですけれども、そういった方が悩ましいところでありまして、一般的にはそういうことです。家賃は五反田のあたりで１２万円とか１３万円で入れますので、普通の収入であれば滞納ということはおよそないです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"本当にいわゆる情報の漏えいをきちんと防ぐことができるのか、その仕組みがきちんと担保されているのか。三井不動産のことでなくしても、この間、いろいろ情報の漏えいの問題はあらゆる民間企業から社会問題化しているだけに、この問題というのはしっかり仕組みが担保されているのかどうか、非常に疑問に思うところなんですけれども、それについてはどういうふうにお考えなんでしょうか。","respondent":"齋藤住宅課長","answer":"不動産会社ですので、そういった情報が漏れるということ自体が会社の信用にかかわりますので、それについては今のところ問題はありません。区と同じように、あるいはそれ以上に守秘義務は守られていると考えております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"住宅の問題というのはその個人の生活の本当に基本中の基本だと思いますので、そこはやっぱり指定管理者が、ここでいう三井不動産株式会社というところであれば、いわゆる情報の漏えいの問題というのはやっぱり不安を抱かざるを得ない。それを防止する仕組みも今の説明では私はできないと思います。最後、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"宅建管理センターのところで区民住宅、区営住宅の退去から入居までの平均日数というのが９８.９８日とあるんですが、最短と最長で平均がどういう平均になっているのかわからないので、最短と最長がわかれば、教えてください。それと、３件ともそうなんですけれども、管理運営委託料の算定基準というか、どういうことでこういう金額になっているのかというのを教えていただければ。","respondent":"齋藤住宅課長","answer":"オーナーによって熱意が違いまして、急がなくてもいいと思うところはのんびりやってしまいますので、業者発注までなるべくすぐ入れてくださいというお話をさせてもらっているんですけれども、ところによっては５カ月ぐらいかからないと直さないというところがありまして。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"区民住宅、区営住宅の部分ではそんなに空きはないとは思いますけど、ここに限って言ったら、９８日というのは利用の要望が多いところのはずなのに、こんなにあるというのがよくわからないんですけど、そこのところを教えてほしい。","respondent":"齋藤住宅課長","answer":"かなり老朽化しておりますので、出た後、区のほうで壁紙とか水回りを直しますので、工事を発注するのに１カ月で、工事して１カ月、クリーニングして１カ月、大体３カ月ぐらいかかっているです。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっとよくわからない。普通に３カ月って、すごく要望があって大変な思いをして抽選もしてやっているというところで、その３カ月というのが妥当なのか。民間でもし早く入居させてというふうになれば、もっと早いのではないかなと思うのですが、それは仕組み的に３カ月もかからなければ対処できないということでしょうか。","respondent":"齋藤住宅課長","answer":"それは大概３カ月。住宅の傷みの程度によって違います。","id":"exchange-030"},{"speaker":"井上委員","kind":"提案","question":"ちょっと専門的なことなので、それはとにかく可能な限り努力をするということですので、それは徹底してほしいと思うんですが、１つだけ意見なんですが、区民満足の視点というところで、これは事業者側が区民満足の視点で回答しているところだと思うんですが、なおかつ、そのことについてのヒアリングも区が事業者に対してヒアリングをするということだと思うんですが、以前からこの指定管理者制度について。","respondent":"齋藤住宅課長","answer":"今後、モニタリングシステムの運用の中でどのような形でもって満足度を調査するか、今後指標が入ってくるかもしれませんが、今のところはアンケートという考えはないということのようです。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問・要望","question":"全体の取り組みとしてはそういうことですので、住宅の管理を指定管理者を導入するという意味では、当然、担当事業部の取り組みとしてチェックは必要だと思いますので、それは統一的な部分が本来であれば求められるところですけれども、指定管理の内容によって違いもあるかもしれませんけれども、そこのところは事業部ごとに検討し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"ほかのところではこういう点ではないかということがあって、でもここでは空欄になっていると。これはむしろ書けと言っても書かなかったんだというご説明がありましたけれども、逆に区民満足の視点からも運営していくというような、逆に誘導するようなことというのも、こういうことをしたら書けるよみたいなことで、実施を誘導するようなことというのは区ではなかったんでしょうか。","respondent":"齋藤住宅課長","answer":"２つありまして、１個はモニタリングシステムというのが導入されまして、私どもも指導できなかったということ、それと、これはどういうことを、どういう点を書くのかということを議論したんですけど、なかなかうまく指導できなかったということがあります。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"先ほどちょっと委託料の算定基準なんていうのもありましたけれども、逆に、小規模で数がたくさんのものを管理するときに、これはちょっと漠然とした質問ですけど、あまりにも業者が持ち出しが多くならないような配慮というのをされているんでしょうか。何かあんまりむちばかりでもかわいそうだなと、見て思っていたんですが。","respondent":"齋藤住宅課長","answer":"だからその分を人件費にあてなさいというのを、ずっとこの間、指導してきたことなんですけど、あと、宅建管理センターとしても自慢の組織であり、若干先進的なモデルなんだと本腰を入れられている状況だと思います。","id":"exchange-034"},{"speaker":"三上委員","kind":"意見","question":"利益を上げているから、それで人を増やせと簡単に言うけれども、それはそれで努力をしてそれだけの利益を出すということは、もう民間は当然それは考えることだと思うので、そこらあたりの考え方と、区がやはりこれはもう少しこういった点で人の手が増えないからこういうことが起きてくるんだとかという現実があるのかどうかということについて、どういうふうにとらえていらっしゃるのか。","respondent":"齋藤住宅課長","answer":"年齢を申しますと、５０代の女性職員が２人いらっしゃるだけなので、きめ細かさ、あるいは要望されたときに、すぐに行く。","id":"exchange-035"},{"speaker":"三上委員","kind":"確認","question":"今、住宅課長の感じていらっしゃることを伺った話の中で、そういった現実というのは宅建管理センターの役員の方は理解し、手を打ちますということは言っていらっしゃるのか。そこのところだけちょっと確認します。","respondent":"齋藤住宅課長","answer":"検討委員会を設けて５回開催されて、大分体制が変わってきております。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"様子は、それはもう見ていきます。ほかの２社と違うのは、１つの会社が担当しているということではない。やっぱり考えてみると、そういった点での弱点というのはあるわけですから、そこのところを逆手にとって、本当に自分たちがいろいろな意味でその４６０社のそういう知恵とかいろいろなものを出し合ったならば、それはまたすごい力になるということはあり得ると思うんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"確認","question":"全体のことからちょっとお聞きしたいんですけれども、確認なんですが、基本的に先ほど来、いろいろ宅建管理センターも含めていろいろなところと、例えば、三井不動産の部分でも報告書等の提出期限を守るようにとかいろいろ指示をしたという、この対応方針と行政側の最後の経営会議における検証、この２カ所で、あとは業者が書いてきたという理解でいいわけですよね。そこだけまず。","respondent":"齋藤住宅課長","answer":"これはヒアリングをして区で書いたものです。業者に書かせたものをそのまま出すことはしないという、こういうルールです。ただ言ったことを少しそしゃくして区で書いたということです。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"確認","question":"そうすると、宅建管理センターのヒアリングの場合、先ほど白紙というところは、ヒアリングをした際も、逆に「こういうことを書いたら」というお話もあったけど、それに対してもヒアリングのときに答えなかったのか、書いてこなかったのかというのがありますよね。だから白紙になっているということなのか、そこら辺のところをもう一度確認させてください。","respondent":"齋藤住宅課長","answer":"白紙で出すのは抵抗がありましたので、「こんなことを書けば」と水を向けたんですが、白紙のまま返ってきた。それで、企画財政課に確認しましたら、議会の意見を仰ぐということを言っておりました。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"意見","question":"それぞれ皆さん、今も６社来たと。これを見る限り、この３つの中ではベニーエステートサービスは非常によくやっているというのばかりなんだよね。そこら辺の資料のつくり方とか、そういうのは我々ももう一度ちょっと考えたいなと考えていますけれども、ぜひ我々にもわかるように、なるべく資料を出していただけるようにお願いしたいなと思うのと、それから、宅建管理センターはこれはいつごろやったの。","respondent":"齋藤住宅課長","answer":"７月です。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"意見","question":"先週、職員は採用したみたいですね。この４６０人のボランティアでの部分が非常にあるので、利益も出ると思う。なおかつ、今メンテナンスの部分も含めて、案内をしたって、こんな汚いところに案内するのかというようなところも、逆に怒られているようなところも５度も６度も行けと言われて、何度も何度もそういう努力をしている。","respondent":"齋藤住宅課長","answer":"この総括シートをつくるに当たって、いろいろ庁内で勉強しているんですけれども、企画財政課のほうで調整したものだです。宅健管理センターの目に見えない努力というものが伝わらないシートになっているということについては、担当の企画財政課長のほうにも伝えておきます。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"今のところに絡む話の中身になってくると思うんだけれども、これを見てもファミーユ西五反田西館といっても、何戸あってという基礎的なものが入っていないわけだよね。１団地の中で何戸とかという形になるんだろうけれども、そういうのが見えてこないと、基礎データ的な部分でこれでは比べようがない。ちょっと要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40371,"voices":115}},{"id":"h19-20070926-9","meetingId":"h19-cm09","date":"2007年9月26日","dateIso":"2007-09-26","committee":"文教委員会","time":"午前１０時０３分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"教員の独自採用制度","agenda":"教員の独自採用制度","exchanges":[{"speaker":"市川委員","kind":"質問・要望","question":"臨時的任用ということなんですけれども、この臨時的任用ということをもう少し詳しく説明していただきたい。この３点をお願いします。","respondent":"河野指導課長","answer":"いわゆる連携校で連携がやられていないのではというご指摘ですが、全ての学校で、小中での連携は実際に実施しております。","id":"exchange-001"},{"speaker":"市川委員","kind":"質問","question":"そうしますと、連携ができている学校というのは大体どれぐらいの学校なのかということを数でお聞きしたいということと、それから臨時的任用という言葉から、不安定な雇用のように聞こえるんですけれども、その辺はどうなのか。待遇として、普通の教員と同じ待遇が与えられるのかということをお聞きしたいんですけれども。","respondent":"河野指導課長","answer":"先ほどもご説明させていただきましたけれども、連携されている学校は、区内の小学校、中学校、全校です。それから、臨時的任用教員の処遇ですが、一般の新卒教員と同等の処遇を考えております。","id":"exchange-002"},{"speaker":"石田（慎）委員","kind":"質問","question":"参考にお伺いしますけれども、まず、区費教員は、都費教員と同じ位置でよろしいんでしょうか。","respondent":"河野指導課長","answer":"それぞれ、ただ来たから、人数が増えたからそれをいいように使うということでは研修になりませんので、その辺、受け入れた教員に与える研修テーマであるとか、いつごろ、どういう形で、どういうことをやらせるとか。","id":"exchange-003"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、研修内容とかテーマというのは、その受け入れる学校がそのテーマを決めるのか、それとも教育委員会にある程度のものがあって、それに従って受け入れ先がその条件を飲んで受け入れるのか、どちらでしょうか。","respondent":"河野指導課長","answer":"もうちょっと具体的な中身で申し上げますと、各教科、それから市民科、英語科も含む各教科と小中連携、あるいは小中一貫教育、生活指導、あるいは学校運営、そういうような大ざっぱな提示ですが、必ずそれぞれ研修先に行って勉強してきた教員が、自分の学校に戻って役に立つ。","id":"exchange-004"},{"speaker":"石田（慎）委員","kind":"質問","question":"もう１回だけお聞きしたいんですけど、このバイズティーチャー、せっかく各小中学校から他の学校で研修をして、前の学校に戻ってすぐに異動とかというのはないように心がけるのか。せっかくほかの学校で研修して、自分の学校に戻ってきたときに、「じゃあ、すみませんけど異動お願いします」と言われたりとか、異動とかというのがあったらどうなのかなと思ってお聞きしたいんですが。","respondent":"河野指導課長","answer":"ただ、初任者が初異動する場合、例えば品川区で初めて教壇に立った教員が３年以上勤務して異動する場合には、区内異動というのが認められませんので、必ず他の区市、あるいは島しょ地域に異動するというのが決まりになっておりますが、２地区以上経験した教員については、今。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"しかしその中で、この留学制度のところに書いてあるように、別の学校に研修・派遣というふうになっているんですが、どういう形で、どこの学校に１年間の任用という形であるか、その辺のあれがなかったからちょっとわからないんですけれども、とりあえず提供された資料を見てみると、小中一貫校を派遣先にするというふうに私は読んだんですけれども、一定期間、区内の別な学校に研修・派遣という。","respondent":"河野指導課長","answer":"この特色校が、例えば連携教育で他校にない斬新な取組をやっているとか、あるいは市民科の研究開発学校ということで研究しているとか、あるいは、例えば特別支援教育で非常に優れた実践をされている教員がいる学校であるとか、そういうようなこと全てですので。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"派遣し、研修を受ける、自分がこういう勉強を新たにしたいので、例えば今おっしゃった学校だとかそれぞれの特色のある学校にこういう目的で行きたいんだというのを当然出して、受け入れ校との調整が始まっていくと思うんですけれども、その辺は、直接的にはどういうふうになっていくのか伺いたいのと、同時に、受け入れ先の学校も、先ほど研修メニュー。","respondent":"河野指導課長","answer":"それとさらに、年間任用ということで応募されてきた方の資質、さらに所持している免許の整合性、そんなものを総合的に考えながら、最終的に年間任用教員の採用を決定していくという予定です。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと複雑なところがあってわかりにくいので教えていただきたいんですが、区費教員採用と、それから人材育成というものの整合をとりますよというお話だと思うんですが、この表を見ると、人材育成は教員採用の対象になるということなんですか。それがまず１点。それと、選考の仕方なんですけど、１次、２次。一つは、校長先生ということですから、各学校によって違う可能性がありますね。","respondent":"河野指導課長","answer":"年間任用教員の業績評価ということで、基準はどうするのかですが、こちらの方については、採用基準をきちんと我々の方で用意をして、その基準に照らし合わせてどうなのかということを、それぞれの学校に客観的に判断していただくというような方法をとる予定です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"１点目、もうちょっと私の意図が伝わっていないのかなと思うんですが、この表の中に、今のお答えだと、区費教員採用という部分と人材育成というところはリンクしないような気がする、そういうお答えですか。一緒にここに書く必要はなかったんじゃないでしょうか。だから、そこで育てた先生は品川区にいてほしいわけですよ。だから、別々に書いたほうがわかりやすいんじゃないですかということです。","respondent":"河野指導課長、若月教育長","answer":"しかも、この都費教員と区費教員、特に区費独自採用教員は定数外ですので、例えば今、Ａ小学校の教員の定数が１０名と決まっていたとしても。今の指導課長の説明のとおりなんですけれども、基本的に、ここの一番下に「品川区立学校教員（１年間任用）選考（公募）」と書いてありますね。せっかく優秀な教員で、身分が区でなくても、都費の身分でありながら、一生懸命品川のために働いてくれていて。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろご説明ありがとうございました。突き詰めてくると、区費職員の方が多くなるという可能性はあるんですか。ただ、私もいろいろお聞きするまでそのねらいがわからなかったんですよ。そういった場合に、評価をするときにそっちの評価がないと多分見方が違うと思うので、いろいろな評価を踏まえた上で選考していただきたいと考えますが、その考え方についてお聞きしたいと思います。","respondent":"河野指導課長","answer":"ただ、校長連絡会、それから副校長連絡会においてはこの概要を説明して、とにかくこれは教育委員会が施策として実施することではあるんだけれども、これがうまく機能するかどうかということは、これはもう学校現場と行政側との連携がどれだけうまくできるのか。","id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけ追加で質問したいんですが、この区費教員採用、実際に今回５名程度ということで、今年は５名採用されて、その方たちというのは、何もなければずっと採用されるわけですね。さらに、また新たに採用するに当たって、毎年５名程度ずつ増やしていくのか、それともその５名の中で欠員が出て、その欠員を補充するための採用なのかということをちょっとお聞きしたいんですが。","respondent":"河野指導課長","answer":"平成２１年４月に採用を予定しております５名は、これは採用当初は条件つき採用ということになりますので、一応１年間様子を見た上で、最終的に正式採用するかどうかが決定されるということになります。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私も今の質問と同じような角度で伺いたかったんですが、要するに区費ですから、教員の給料が８００万円ぐらいですよね。それを、最初は５名ですからともかく、４年か５年先には二十数名という状況にして、それ以降は、その方たちが少なくとも退職されるまでは、数億の財源を投入し続けるということになるわけですよね。要するに、品川区のそういう教育方針を定着させるための人材育成ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"平成１８年度品川区立体育館における指定管理者に対するモニタリング・評価の結果について","agenda":"平成１８年度品川区立体育館における指定管理者に対するモニタリング・評価の結果について","exchanges":[{"speaker":"西本委員","kind":"確認","question":"既に説明していることもあるかもしれませんので、確認の意味でもう一度お願いしたいと思います。組織的なところで、ここは、コナミスポーツが入っていたと思うんですけど、ここの会計はどうなっているのかなということをまず１点確認させてください。その辺は、独自でまかなっていたところがあって委託料が下がっているという解釈でいいのかというところを確認したいと思います。","respondent":"富田生涯学習課長","answer":"このほか、スポーツ協会としては、独自に、総合体育館を利用するに当たっての区民の方々の声を、投書箱等々の設置により集約をしているところでありまして、年度当初、体育館が開設された当初、これは業務委託部分でありますが、プール部分への苦情等々。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"それはやり方のことですから、別に委託するのが悪いというわけではないんですが、先ほどからトレーニング室、いろいろ改善されているんですけれども、運営についても改善に該当するところというふうな感じなんですけれども、これは、例えばコナミじゃなくて、ほかの団体というような、こういう評価のもとで分析をするときに、スポーツ協会にはいろいろ言えると思うんですけど。","respondent":"富田生涯学習課長","answer":"それと、先ほどご指摘のありました区民満足の視点につきましては、今回、このような形でまとめた結果となっておりますが、今後の評価に当たりましては改善してまいりたいと考えています。再委託先に対して、私ども直接の指示ということは行っておりません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"要は、ビル管理が一緒になったのでその分という感じなのでしょうから、わかりました。それから、再委託のフォローですが、再委託ですからわかるんですが、あくまでも区とスポーツ協会との関係であって、スポーツ協会がそれを遂行するために委託を使うということなんですから構わないと思うんですが、ただ、こういう評価をするときに、トレーニングルームとかでいろいろ改善がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"そして二つ目は、２番目と３番目のサービス向上および業務改善の視点ということで、施設の利用そのものをもっと効率的にということで改善されたということで、利用が少なかった団体の部屋の使い方を合同開催にするとか、団体多数のところに振りかえる、こういうことでの指導があって、効率化に努めたというところなんですが、当然これは、専門家のコナミなり、スポーツ協会の方の検討の中だから。","respondent":"富田生涯学習課長","answer":"２点目の、種類の違う競技を同じ部屋でですけれども、従前より、体育館のアリーナについては、半面貸出、半面使用ということを実施してきておりまして、競技にもよりますけれども、かなり多くの競技につきまして、半面ずつ別の競技利用というのは実施をしてきて。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解がもしあれば教えていただきたいと思います。熱中症だとか、そういう問題も健康被害として出てくるということもありますので、ですから、例えば風のとおりをよくするような構造だとか、窓をきちんと開ける指導だとか、そういうものを管理者の方から積極的にそういう声をかけていくということを含めて必要なんじゃないかと思いますので、その辺についてどういうふうになっているのか伺います。","respondent":"富田生涯学習課長","answer":"事務局体制の強化等々についてどう考えているのかですけれども、従前の管理運営委託と、指定管理者になったこととの違いの部分というのは先ほども申し上げましたけれども、その辺をきちんと、スポーツ協会の事務局として認識し。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"戸越体育館については、競技中心なので、つけるつもりはない、つける必要はないというふうに考えている、そういうことなんですか。ですから、そういう他の使い方というのは、総合体育館以外にもあるだろうと思うし、その辺で、クーラーは整備してもこれからの時代は当然じゃないかなと思いますので、そのあたりの見解を改めて伺いたいと思います。とりあえずそういうことで、よろしくお願いします。","respondent":"富田生涯学習課長","answer":"戸越体育館については、現時点でクーラーを設置する考えは持っておりません。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"要請ですけれども、先ほど言ったような理由で、戸越体育館にもクーラーは必要ではないか。ぜひつけていただきたいということを、これから予算要望の時期だし、決算特別委員会もありますので、そういう時期をとおしてお願いをしていきたいと考えていますが、出た関係があったので、そのことも話しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"引き続きまして、(3)「南大井文化センターの改修工事について」","agenda":"引き続きまして、(3)「南大井文化センターの改修工事について」","exchanges":[{"speaker":"南委員","kind":"質問","question":"質問は、空調機の更新工事ということなんですが、その際も非常に暑い日だったので、空調を当然使わせていただけましたけど、各部屋での調節機能というのがなくて、電話で「使いますので」というふうに言うとスイッチを入れてくださって、クーラーが入ってくるようになっているようなんですが、更新するということなので、当然、各部屋でスイッチを入れたり切ったり、暑いときは強にしたり。","respondent":"富田生涯学習課長","answer":"従来は全館空調、第３講習室は個別になっていますが、そのほかは全館一斉のスイッチのオン・オフでありましたが、今回は個別に空調機がついておりますが、コントロールについては１カ所で集中して、連絡した上で調整をしてもらうという形を予定しています。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"そうすると、例えば区役所の私どもの控え室は、全館空調とは違って、個別に部屋に空調設備が整って、スイッチがあり、そこでつけたり消したり、温度調節もできるようになっていて、非常に使い勝手がいいんですけど、大体品川区の施設というのは、まちの中にある様々な施設も全館空調になっていて、ここの文教委員会の担当じゃないけれども、八潮の地域センターもやっぱりそうで。","respondent":"富田生涯学習課長","answer":"室温を個別にコントロールするのではなく、たしか事務室の方だったと思いますが、そちらの方で調整をするというふうになっているはずです。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"重複するところがありますので、確認していきたいと思うんですが、不登校の数がその中でもと思うんですけれども、不登校といじめとの関連についてというのがありまして、そこで、荏原第二中学校で実施している通級学級について、将来どういう形になるのかということも含めて教えていただきたいと思います。","respondent":"河野指導課長","answer":"話が前後して申しわけございませんが、荏原第二中学校の方も、不登校以外にも発達障害を受け入れるということで今年から進めておりますので、現在のまま推移をしていきますと、荏原第二中学校の方も手狭になるということが予想されますので、荏原第二中学校の方の移設。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"全区的に学校を巡回したりとかいろいろされていると思うんですが、そことの関連性はどうなっていくのか。位置づけとしてですね。その場合に、当該の学校の状況も含めて、その情報をお互いに共有することで、早く復帰できるという形がつくれるんじゃないかと私は思うんですが、そういう動きは今後つくっていけるのか、つくってあるのか、いかがでしょうか。","respondent":"河野指導課長","answer":"そういう関係で、どちらも教育委員会所属ということでもありますので、守秘義務ももちろん前提としてあるわけですけれども、同じ組織の中での対応ということで、できるだけ具体的なことも含めて、情報交換をするように努めております。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"要望も含めて伺いました。荏原第二中学校とマイスクールについては、そういうことになっているということで、今の説明を含めて、事業の拡大という形でぜひ広げていけるように、本当に積極的にまかなえるように、増えていくといいなと思っています。ですから、親が学校に問いかけたりとかしなくてはならないというところが出たりして、わりと当事者間だけだとやりにくい部分もあるんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4614#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":38342,"voices":73}}]);
